const HSK30_1_FULL_DATA = {"1":{"pages":"1–4","titleZh":"AI小语，你好！","titlePy":"AI Xiǎoyǔ, nǐ hǎo!","titleVi":"Xin chào AI Tiểu Ngữ!","goals":["Có thể nghe hiểu và sử dụng được ngôn ngữ lịch sự để chào hỏi, cảm ơn và tạm biệt.","Hiểu về nghi thức giao tiếp tiếng Trung Quốc, có thể nghe hiểu và sử dụng được đại từ nhân xưng ngôi thứ hai mang tính trang trọng “您”."],"words":[{"zh":"你好","py":"nǐ hǎo","vi":"xin chào, chào bạn","pos":""},{"zh":"王老师","py":"Wáng lǎoshī","vi":"cô Vương","pos":"dt. riêng"},{"zh":"大家","py":"dàjiā","vi":"mọi người","pos":"đt."},{"zh":"好","py":"hǎo","vi":"tốt, khoẻ","pos":"tt."},{"zh":"学生","py":"xuéshēng","vi":"học sinh, sinh viên","pos":"dt."},{"zh":"们","py":"men","vi":"dùng sau đại từ nhân xưng hoặc danh từ để chỉ số nhiều","pos":"htố."},{"zh":"老师","py":"lǎoshī","vi":"thầy giáo, cô giáo, giáo viên","pos":"dt."},{"zh":"您","py":"nín","vi":"ngài, ông, bà... (đại từ nhân xưng ngôi thứ hai thể hiện sự trang trọng)","pos":"đt."},{"zh":"你们","py":"nǐmen","vi":"các bạn, các anh, các chị... (đại từ nhân xưng ngôi thứ hai số nhiều)","pos":"đt."},{"zh":"谢谢","py":"xièxie","vi":"cảm ơn","pos":"đgt."},{"zh":"不客气","py":"bú kèqi","vi":"đừng khách sáo, không cần khách khí","pos":""},{"zh":"同学","py":"tóngxué","vi":"bạn học","pos":"dt."},{"zh":"再见","py":"zàijiàn","vi":"tạm biệt","pos":"đgt."}],"dialog":[{"section":"Bài khóa 1","context":"Ngày đầu tiên đi học, Vương Nhất Phi chào hỏi trợ giảng AI Tiểu Ngữ ở trong văn phòng.","audio":"01-1.mp3","speaker":"A","name":"王一飞","zh":"AI小语，你好！","py":"AI Xiǎoyǔ, nǐ hǎo!","vi":"Xin chào AI Tiểu Ngữ!"},{"section":"Bài khóa 1","context":"","audio":"01-1.mp3","speaker":"B","name":"小语","zh":"王老师，你好！","py":"Wáng lǎoshī, nǐ hǎo!","vi":"Chào cô Vương!"},{"section":"Bài khóa 2","context":"Ngày đầu tiên đi học, các bạn học sinh học cách diễn đạt chào hỏi tại lớp.","audio":"01-3.mp3","speaker":"A","name":"王一飞","zh":"大家好！","py":"Dàjiā hǎo!","vi":"Chào cả lớp!"},{"section":"Bài khóa 2","context":"","audio":"01-3.mp3","speaker":"B","name":"学生们","zh":"老师，您好！","py":"Lǎoshī, nín hǎo!","vi":"Chào cô ạ!"},{"section":"Bài khóa 2","context":"","audio":"01-3.mp3","speaker":"C","name":"小语","zh":"你们好！","py":"Nǐmen hǎo!","vi":"Chào các bạn!"},{"section":"Bài khóa 2","context":"","audio":"01-3.mp3","speaker":"B","name":"学生们","zh":"你好，小语！","py":"Nǐ hǎo, Xiǎoyǔ!","vi":"Chào Tiểu Ngữ!"},{"section":"Bài khóa 3","context":"Ngày đầu tiên đi học, các bạn học sinh học các mẫu câu cảm ơn và tạm biệt ở trong lớp học.","audio":"01-5.mp3","speaker":"A","name":"学生们","zh":"谢谢！","py":"Xièxie!","vi":"Cảm ơn bạn!"},{"section":"Bài khóa 3","context":"","audio":"01-5.mp3","speaker":"B","name":"小语","zh":"不客气！","py":"Bú kèqi!","vi":"Đừng khách sáo!"},{"section":"Bài khóa 3","context":"","audio":"01-5.mp3","speaker":"C","name":"王一飞","zh":"同学们，再见！","py":"Tóngxuémen, zàijiàn!","vi":"Tạm biệt các em!"},{"section":"Bài khóa 3","context":"","audio":"01-5.mp3","speaker":"A","name":"学生们","zh":"老师，再见！","py":"Lǎoshī, zàijiàn!","vi":"Tạm biệt cô ạ!"}],"dialogQuestions":[],"grammar":{"g1":{"han":"您","py":"nín","title":"1. Đại từ nhân xưng kính ngữ “您”","explain":"“您” là đại từ nhân xưng ngôi thứ hai mang sắc thái trang trọng, được dùng để xưng hô với người lớn tuổi hoặc những người mà bạn kính trọng.","examples":[{"zh":"老师，您好！","py":"Lǎoshī, nín hǎo!","vi":"Chào cô ạ!","hl":"您"}],"struct":"Danh xưng + 您好！","note":"Phân biệt với “你” (bạn, em — dùng ngang hàng hoặc với người nhỏ tuổi hơn) và “你们” (các bạn — số nhiều)."},"g2":{"han":"你好 / 谢谢 / 不客气 / 再见","py":"nǐ hǎo / xièxie / bú kèqi / zàijiàn","title":"2. Mẫu câu chào hỏi, cảm ơn và tạm biệt","explain":"Các mẫu câu giao tiếp lịch sự cơ bản trong tiếng Trung Quốc: dùng “你好 / 大家好 / 你们好” để chào hỏi; dùng “谢谢” để cảm ơn và đáp lại bằng “不客气”; dùng “再见” để tạm biệt.","examples":[{"zh":"大家好！","py":"Dàjiā hǎo!","vi":"Chào cả lớp!","hl":"大家好"},{"zh":"谢谢！— 不客气！","py":"Xièxie! — Bú kèqi!","vi":"Cảm ơn bạn! — Đừng khách sáo!","hl":"谢谢"},{"zh":"同学们，再见！","py":"Tóngxuémen, zàijiàn!","vi":"Tạm biệt các em!","hl":"再见"}],"struct":"Chào hỏi: (Đối tượng +) 你好/您好/大家好/你们好！ | Cảm ơn: 谢谢！— 不客气！ | Tạm biệt: (Đối tượng +) 再见！","note":"Hậu tố “们” (men) dùng sau đại từ nhân xưng hoặc danh từ chỉ người để chỉ số nhiều, ví dụ: 你们 (các bạn), 学生们 (các học sinh), 同学们 (các bạn học)."}},"grammarQuiz":[],"chars":["你","好","王","老","师","大","家","学","生","们","您","谢","不","客","气","同","再","见"],"rhyme":{"zh":"妈种麻，我放马。\n马吃麻，妈骂马。","py":"Mā zhòng má, wǒ fàng mǎ.\nMǎ chī má, mā mà mǎ.","vi":"Mẹ trồng cây gai, tôi thả ngựa.\nNgựa ăn cây gai, mẹ mắng ngựa.","audio":"01-7.mp3"},"notes":["Tiểu Ngữ giúp sức (trang 2): “您” là đại từ nhân xưng mang sắc thái trang trọng, được dùng để xưng hô với người lớn tuổi hoặc những người mà bạn kính trọng.","Tiểu Ngữ giúp sức (trang 4): Bạn có muốn học thêm kiến thức về phiên âm tiếng Trung Quốc không? Hãy ghé thăm chuyên mục “Món quà của Tiểu Ngữ” (汉语拼音 — Phiên âm tiếng Trung Quốc, video 1-1)."],"workbook":{"exercisesNote":"SBT Bài 1 (tr. 1–4): Tiểu Ngữ giảng đường — Luyện nghe đọc (听读练): 2. Nghe viết thanh mẫu \u0026 đọc to; 3. Nghe viết vận mẫu \u0026 đọc to; 4. Nghe viết thanh điệu \u0026 đọc to; 5. Nhìn tranh chọn hội thoại đúng; kèm tập viết nét chữ Hán cơ bản.","answerKeyNote":"听读练:\n• 2 (Thanh mẫu): dà, gěi, pán, bù, mǎi | lěng, fó, hǎo, tóng, hěn | bān, dōu, kè, nǐ, máng (d, g, p, b, m, l, f, h, t, h, b, d, k, n, m).\n• 3 (Vận mẫu): tā, hěn, māo, dì, fáng | dōng, hàn, gǒu, péng, gē | kāi, fēi, nù, lěng, bō (a, en, ao, i, ang, ong, an, ou, eng, e, ai, ei, u, eng, o).\n• 4 (Thanh điệu): lǎo, néng, gè, bā | fēn, kàn, bái, lǐ | gōng, máng, gǒu, hòu.\n• 5 (Nhìn tranh chọn hội thoại): ① · ③ · ②.","transcriptNote":""}},"2":{"pages":"5–9","titleZh":"我叫李文","titlePy":"Wǒ jiào Lǐ Wén","titleVi":"Mình tên là Lý Văn","goals":["Có thể nghe hiểu và tự giới thiệu họ tên mình bằng tiếng Trung Quốc.","Có thể nghe hiểu và sử dụng được cách nói xin lỗi, biết dùng “对不起” để xin lỗi và đáp lại bằng “没关系”.","Nắm vững trật tự từ cơ bản của câu trong tiếng Trung Quốc.","Hiểu về cấu trúc họ tên của người Trung Quốc."],"words":[{"zh":"请问","py":"qǐngwèn","vi":"xin hỏi","pos":"đgt."},{"zh":"你","py":"nǐ","vi":"bạn, anh, chị, em... (đại từ nhân xưng ngôi thứ hai số ít)","pos":"đt."},{"zh":"叫","py":"jiào","vi":"gọi là, tên là","pos":"đgt."},{"zh":"什么","py":"shénme","vi":"gì, cái gì","pos":"đt."},{"zh":"名字","py":"míngzi","vi":"tên","pos":"dt."},{"zh":"我","py":"wǒ","vi":"tôi, mình... (đại từ nhân xưng ngôi thứ nhất số ít)","pos":"đt."},{"zh":"不","py":"bù","vi":"không","pos":"phó."},{"zh":"是","py":"shì","vi":"là","pos":"đgt."},{"zh":"对不起","py":"duìbuqǐ","vi":"xin lỗi","pos":"đgt."},{"zh":"没关系","py":"méi guānxi","vi":"không sao, không có gì","pos":""},{"zh":"没事","py":"méishì","vi":"không sao, không có gì","pos":"đgt."},{"zh":"很","py":"hěn","vi":"rất","pos":"phó."},{"zh":"高兴","py":"gāoxìng","vi":"vui, vui vẻ","pos":"tt."},{"zh":"认识","py":"rènshi","vi":"quen, làm quen","pos":"đgt."},{"zh":"也","py":"yě","vi":"cũng","pos":"phó."}],"dialog":[{"section":"Bài khóa 1","context":"Vương Nhất Phi đang làm quen với học sinh ở trong lớp học.","audio":"02-1.mp3","speaker":"A","name":"王一飞","zh":"请问，你叫什么名字？","py":"Qǐngwèn, nǐ jiào shénme míngzi?","vi":"Xin hỏi, em tên là gì?"},{"section":"Bài khóa 1","context":"","audio":"02-1.mp3","speaker":"B","name":"陈天中","zh":"我叫陈天中。","py":"Wǒ jiào Chén Tiānzhōng.","vi":"Em tên là Trần Thiên Trung ạ."},{"section":"Bài khóa 2","context":"Trần Thiên Trung đã nhầm Bạch Gia Nguyệt với người khác khi chào hỏi cô ấy ở trong khuôn viên trường.","audio":"02-3.mp3","speaker":"A","name":"陈天中","zh":"你好，安妮！","py":"Nǐ hǎo, Ānnī!","vi":"Chào Annie!"},{"section":"Bài khóa 2","context":"","audio":"02-3.mp3","speaker":"B","name":"白家月","zh":"你好，陈天中！我不是安妮，我是白家月。","py":"Nǐ hǎo, Chén Tiānzhōng! Wǒ bú shì Ānnī, wǒ shì Bái Jiāyuè.","vi":"Chào Trần Thiên Trung! Mình không phải là Annie, mình là Bạch Gia Nguyệt."},{"section":"Bài khóa 2","context":"","audio":"02-3.mp3","speaker":"A","name":"陈天中","zh":"对不起！","py":"Duìbuqǐ!","vi":"Xin lỗi bạn!"},{"section":"Bài khóa 2","context":"","audio":"02-3.mp3","speaker":"B","name":"白家月","zh":"没关系！","py":"Méi guānxi!","vi":"Không sao đâu!"},{"section":"Bài khóa 3","context":"Lý Văn và Bạch Gia Nguyệt lần đầu gặp nhau trong khuôn viên trường.","audio":"02-5.mp3","speaker":"A","name":"李文","zh":"你好！我叫李文。","py":"Nǐ hǎo! Wǒ jiào Lǐ Wén.","vi":"Chào bạn! Mình tên là Lý Văn."},{"section":"Bài khóa 3","context":"","audio":"02-5.mp3","speaker":"B","name":"白家月","zh":"你好！我叫白家月。","py":"Nǐ hǎo! Wǒ jiào Bái Jiāyuè.","vi":"Xin chào! Mình tên là Bạch Gia Nguyệt."},{"section":"Bài khóa 3","context":"","audio":"02-5.mp3","speaker":"A","name":"李文","zh":"很高兴认识你。","py":"Hěn gāoxìng rènshi nǐ.","vi":"Rất vui được làm quen với bạn."},{"section":"Bài khóa 3","context":"","audio":"02-5.mp3","speaker":"B","name":"白家月","zh":"认识你我也很高兴。","py":"Rènshi nǐ wǒ yě hěn gāoxìng.","vi":"Mình cũng rất vui được làm quen với bạn."}],"dialogQuestions":[],"grammar":{"g1":{"han":"主语 + 谓语 + 宾语","py":"Zhǔyǔ + Wèiyǔ + Bīnyǔ","title":"1. Trật tự từ cơ bản của câu trong tiếng Trung Quốc (汉语的基本语序)","explain":"Trật tự từ cơ bản của câu trong tiếng Trung Quốc là: Chủ ngữ + vị ngữ + tân ngữ. Ví dụ: 我 (chủ ngữ) 叫 (vị ngữ) 陈天中 (tân ngữ).","examples":[{"zh":"你叫什么名字？","py":"Nǐ jiào shénme míngzi?","vi":"Bạn tên là gì?","hl":"叫"},{"zh":"我叫白家月。","py":"Wǒ jiào Bái Jiāyuè.","vi":"Mình tên là Bạch Gia Nguyệt.","hl":"叫"},{"zh":"我是学生。","py":"Wǒ shì xuéshēng.","vi":"Tôi là học sinh.","hl":"是"}],"struct":"Chủ ngữ (主语) + Vị ngữ (谓语) + Tân ngữ (宾语)","note":"Họ tên của người Trung Quốc gồm: họ + tên (姓 + 名), ví dụ: 李文 (họ Lý, tên Văn)."}},"grammarQuiz":[],"chars":["请","问","你","叫","什","么","名","字","我","不","是","对","起","没","关","系","事","很","高","兴","认","识","也"],"rhyme":{"zh":"七加一，再减一，加完减完等于几？加完减完还是七。","py":"Qī jiā yī, zài jiǎn yī, jiāwán jiǎnwán děngyú jǐ? Jiāwán jiǎnwán hái shì qī.","vi":"Bảy cộng một, lại trừ một.\nCộng xong trừ xong thì bằng mấy?\nCộng xong trừ xong vẫn là bảy.","audio":"02-7.mp3"},"notes":["Tiểu Ngữ giúp sức (trang 6): “请问” là một kính ngữ, được sử dụng khi đề nghị ai đó trả lời câu hỏi.","Tiểu Ngữ giúp sức (trang 7): Trong văn nói, mọi người cũng dùng “没事” hoặc “没事没事” thay cho “没关系”.","Tiểu Ngữ giúp sức (trang 8): Họ tên của người Trung Quốc gồm: họ + tên (中国人的姓名：姓+名).","Món quà của Tiểu Ngữ (trang 9): 世界各国的中文名称 — Tên tiếng Trung Quốc của các nước trên thế giới."],"workbook":{"exercisesNote":"SBT Bài 2 (tr. 5–8): Tiểu Ngữ giảng đường — Luyện nghe đọc (听读练): 1. Nghe viết thanh mẫu j/q/x; 2. Nghe viết vận mẫu; 3. Nghe viết thanh điệu; 4. Nhìn tranh chọn hội thoại đúng; kèm luyện viết chữ Hán.","answerKeyNote":"听读练:\n• 1 (Thanh mẫu): qián, jīn, xiǎng | jiào, xiè, qǐng | jǐ, qù, xià (q, j, x, j, x, q, j, q, x).\n• 2 (Vận mẫu): jiàn, xiě, qù, jiào, qǐng | xué, jiǎo, xīng, jiě, qián | xiàn, qǐ, jiā, xiū, quán.\n• 3 (Thanh điệu): xué, jiào, qún, jiǔ | xīn, qǐng, xià, jiā | qù, jī, xiǎo, jiě.\n• 4 (Nhìn tranh chọn hội thoại): ③ · ① · ④ · ②.","transcriptNote":""}},"3":{"pages":"10–17","titleZh":"我是中国人","titlePy":"Wǒ shì Zhōngguó rén","titleVi":"Mình là người Trung Quốc","goals":["Có thể nghe hiểu và sử dụng được câu chữ “是” để diễn đạt sự đồng nhất hoặc phân loại.","Nắm vững cách dùng của trợ từ kết cấu “的”.","Nắm vững cách dùng của câu hỏi “có... (hay) không” sử dụng từ “吗”."],"words":[{"zh":"人","py":"rén","vi":"người","pos":"dt."},{"zh":"的","py":"de","vi":"của (dùng sau định ngữ)","pos":"trợ."},{"zh":"中国","py":"Zhōngguó","vi":"Trung Quốc (tên nước)","pos":"dt. riêng"},{"zh":"法国","py":"Fǎguó","vi":"Pháp (tên nước)","pos":"dt. riêng"},{"zh":"中文","py":"Zhōngwén","vi":"tiếng Trung Quốc","pos":"dt. riêng"},{"zh":"这","py":"zhè","vi":"này, đây","pos":"đt."},{"zh":"谁","py":"shéi/shuí","vi":"ai","pos":"đt."},{"zh":"女朋友","py":"nǚpéngyou","vi":"bạn gái, người yêu","pos":"dt."},{"zh":"哪","py":"nǎ","vi":"nào","pos":"đt."},{"zh":"国","py":"guó","vi":"quốc gia, đất nước","pos":"dt."},{"zh":"她","py":"tā","vi":"cô ấy, chị ấy, bạn ấy...","pos":"đt."},{"zh":"泰国","py":"Tàiguó","vi":"Thái Lan (tên nước)","pos":"dt. riêng"},{"zh":"喂","py":"wèi","vi":"a lô","pos":"ct."},{"zh":"姐姐","py":"jiějie","vi":"chị gái","pos":"dt."},{"zh":"工作","py":"gōngzuò","vi":"công việc","pos":"dt."},{"zh":"还","py":"hái","vi":"vẫn","pos":"phó."},{"zh":"忙","py":"máng","vi":"bận, bận rộn","pos":"tt."},{"zh":"吗","py":"ma","vi":"... phải không? (dùng ở cuối câu để hỏi)","pos":"trợ."},{"zh":"对","py":"duì","vi":"đúng","pos":"tt."},{"zh":"太","py":"tài","vi":"quá, lắm","pos":"phó."},{"zh":"我们","py":"wǒmen","vi":"chúng tôi, chúng ta (đại từ nhân xưng ngôi thứ nhất số nhiều)","pos":"đt."},{"zh":"想","py":"xiǎng","vi":"nhớ","pos":"đgt."}],"dialog":[{"section":"Bài khóa 1","context":"Lý Văn và Bạch Gia Nguyệt gặp nhau lần đầu, hai người tiếp tục trò chuyện trong khuôn viên trường.","audio":"03-1.mp3","speaker":"A","name":"李文","zh":"我是中国人。","py":"Wǒ shì Zhōngguó rén.","vi":"Mình là người Trung Quốc."},{"section":"Bài khóa 1","context":"","audio":"03-1.mp3","speaker":"B","name":"白家月","zh":"我是法国人。我的中文老师也是中国人。","py":"Wǒ shì Fǎguó rén. Wǒ de Zhōngwén lǎoshī yě shì Zhōngguó rén.","vi":"Mình là người Pháp. Giáo viên tiếng Trung Quốc của mình cũng là người Trung Quốc."},{"section":"Bài khóa 2","context":"Sau giờ học, Annie đang xem ảnh trên điện thoại di động của Trần Thiên Trung ở trong lớp học.","audio":"03-3.mp3","speaker":"A","name":"安妮","zh":"这是谁？","py":"Zhè shì shéi?","vi":"Đây là ai vậy?"},{"section":"Bài khóa 2","context":"","audio":"03-3.mp3","speaker":"B","name":"陈天中","zh":"这是我女朋友。","py":"Zhè shì wǒ nǚpéngyou.","vi":"Đây là bạn gái mình."},{"section":"Bài khóa 2","context":"","audio":"03-3.mp3","speaker":"A","name":"安妮","zh":"你女朋友是哪国人？","py":"Nǐ nǚpéngyou shì nǎ guó rén?","vi":"Bạn gái của bạn là người nước nào?"},{"section":"Bài khóa 2","context":"","audio":"03-3.mp3","speaker":"B","name":"陈天中","zh":"她也是泰国人。","py":"Tā yě shì Tàiguó rén.","vi":"Cô ấy cũng là người Thái Lan."},{"section":"Bài khóa 3","context":"Vương Nhất Tuyết đang gọi video cho Vương Nhất Phi ở trong nhà.","audio":"03-5.mp3","speaker":"A","name":"王一雪","zh":"喂，一飞！","py":"Wèi, Yīfēi!","vi":"A lô, Nhất Phi à!"},{"section":"Bài khóa 3","context":"","audio":"03-5.mp3","speaker":"B","name":"王一飞","zh":"姐姐！","py":"Jiějie!","vi":"Vâng, chị!"},{"section":"Bài khóa 3","context":"","audio":"03-5.mp3","speaker":"A","name":"王一雪","zh":"你工作还忙吗？","py":"Nǐ gōngzuò hái máng ma?","vi":"Công việc của em vẫn bận lắm à?"},{"section":"Bài khóa 3","context":"","audio":"03-5.mp3","speaker":"B","name":"王一飞","zh":"对，还很忙。你也很忙吗？","py":"Duì, hái hěn máng. Nǐ yě hěn máng ma?","vi":"Vâng, vẫn rất bận. Chị cũng bận lắm phải không?"},{"section":"Bài khóa 3","context":"","audio":"03-5.mp3","speaker":"A","name":"王一雪","zh":"我不太忙。我们很想你。","py":"Wǒ bú tài máng. Wǒmen hěn xiǎng nǐ.","vi":"Chị không bận lắm. Mọi người đều rất nhớ em."},{"section":"Bài khóa 3","context":"","audio":"03-5.mp3","speaker":"B","name":"王一飞","zh":"我也想你们。","py":"Wǒ yě xiǎng nǐmen.","vi":"Em cũng nhớ mọi người."}],"dialogQuestions":[],"grammar":{"g1":{"han":"是","py":"shì","title":"1. Câu chữ “是” (“是”字句)","explain":"Câu chữ “是” được dùng để định danh người hoặc sự vật (biểu thị sự đồng nhất hoặc phân loại), hình thức phủ định là “不是”.","examples":[{"zh":"我是法国人。","py":"Wǒ shì Fǎguó rén.","vi":"Mình là người Pháp.","hl":"是"},{"zh":"她是中文老师。","py":"Tā shì Zhōngwén lǎoshī.","vi":"Cô ấy là giáo viên tiếng Trung Quốc.","hl":"是"},{"zh":"我老师不是法国人。","py":"Wǒ lǎoshī bú shì Fǎguó rén.","vi":"Giáo viên của tôi không phải là người Pháp.","hl":"不是"}],"struct":"Chủ ngữ + 是 / 不是 + Tân ngữ","note":"Trong “不是”, “不” biến điệu thành thanh 2, đọc là “bú shì”."},"g2":{"han":"的","py":"de","title":"2. Trợ từ kết cấu “的” (结构助词“的”)","explain":"Trợ từ kết cấu “的” được đặt giữa định ngữ và trung tâm ngữ để diễn đạt mối quan hệ sở hữu. Trong trường hợp trước “的” là đại từ nhân xưng, sau “的” là từ chỉ quan hệ thân thuộc hoặc danh từ chỉ người, “的” có thể được lược bỏ.","examples":[{"zh":"白家月的中文老师","py":"Bái Jiāyuè de Zhōngwén lǎoshī","vi":"Giáo viên tiếng Trung Quốc của Bạch Gia Nguyệt","hl":"的"},{"zh":"你的名字","py":"nǐ de míngzi","vi":"Tên của bạn","hl":"的"},{"zh":"我老师","py":"wǒ lǎoshī","vi":"Giáo viên của tôi (lược bỏ “的”)","hl":"我老师"},{"zh":"我学生","py":"wǒ xuéshēng","vi":"Học sinh của tôi (lược bỏ “的”)","hl":"我学生"},{"zh":"你同学","py":"nǐ tóngxué","vi":"Bạn học của bạn (lược bỏ “的”)","hl":"你同学"},{"zh":"我妈妈","py":"wǒ māma","vi":"Mẹ của tôi (lược bỏ “的”)","hl":"我妈妈"}],"struct":"Định ngữ + 的 + Trung tâm ngữ","note":"Hoàn thành hội thoại (trang 12): (1) A: 这是我（老师）。 B: 老师，您好！ | (2) 李文: 请问，你（中文老师）叫什么名字？ 白家月: 我（中文老师）叫王一飞。"},"g3":{"han":"吗","py":"ma","title":"3. Câu hỏi “có... (hay) không?” sử dụng từ “吗” (用“吗”的是非问句)","explain":"“吗” là trợ từ ngữ khí, thường được đặt ở cuối câu để tạo thành câu hỏi “có... (hay) không?”.","examples":[{"zh":"你也很忙吗？","py":"Nǐ yě hěn máng ma?","vi":"Bạn cũng rất bận phải không?","hl":"吗"},{"zh":"你是他的中文老师吗？","py":"Nǐ shì tā de Zhōngwén lǎoshī ma?","vi":"Bạn là giáo viên tiếng Trung Quốc của anh ấy phải không?","hl":"吗"},{"zh":"你有姐姐吗？","py":"Nǐ yǒu jiějie ma?","vi":"Bạn có chị gái không?","hl":"吗"}],"struct":"……吗？","note":"Lưu ý: “有” (yǒu) nghĩa là “có”."}},"grammarQuiz":[{"id":"hsk1_b3_q1","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (选词填空).","q":"你工作忙______？","opts":[{"t":"哪","ok":false},{"t":"吗","ok":true},{"t":"谁","ok":false},{"t":"中国人","ok":false},{"t":"想","ok":false}],"exp":"Đặt trợ từ ngữ khí “吗” ở cuối câu để tạo câu hỏi “Công việc của bạn có bận không?”."},{"id":"hsk1_b3_q2","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (选词填空).","q":"我很______你们。","opts":[{"t":"哪","ok":false},{"t":"吗","ok":false},{"t":"谁","ok":false},{"t":"中国人","ok":false},{"t":"想","ok":true}],"exp":"“我很想你们。” nghĩa là “Tôi rất nhớ các bạn.”"},{"id":"hsk1_b3_q3","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (选词填空).","q":"白家月：你是______国人？","opts":[{"t":"哪","ok":true},{"t":"吗","ok":false},{"t":"谁","ok":false},{"t":"中国人","ok":false},{"t":"想","ok":false}],"exp":"“哪国人” (nǎ guó rén) dùng để hỏi quốc tịch: “Bạn là người nước nào?”."},{"id":"hsk1_b3_q4","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (选词填空).","q":"白家月：你是哪国人？ — 李文：我是______。","opts":[{"t":"哪","ok":false},{"t":"吗","ok":false},{"t":"谁","ok":false},{"t":"中国人","ok":true},{"t":"想","ok":false}],"exp":"Lý Văn trả lời quốc tịch của mình: “我是中国人。” (Mình là người Trung Quốc.)."},{"id":"hsk1_b3_q5","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (选词填空).","q":"白家月：她是______？ — 安妮：她是陈天中的女朋友。","opts":[{"t":"哪","ok":false},{"t":"吗","ok":false},{"t":"谁","ok":true},{"t":"中国人","ok":false},{"t":"想","ok":false}],"exp":"Dùng đại từ nghi vấn “谁” (ai) để hỏi danh tính: “Cô ấy là ai?”."}],"chars":["人","的","中","国","法","文","这","谁","女","朋","友","哪","她","泰","喂","姐","工","作","还","忙","吗","对","太","我","们","想"],"rhyme":{"zh":"四是四，十是十。\n十四是十四，四十是四十。","py":"Sì shì sì, shí shì shí.\nShísì shì shísì, sìshí shì sìshí.","vi":"Bốn là bốn, mười là mười.\nMười bốn là mười bốn, bốn mươi là bốn mươi.","audio":"03-7.mp3"},"notes":["Tiểu Ngữ giúp sức (trang 12): Từ “谁” (shéi) cũng có thể đọc là “shuí”.","Bài tập miêu tả hình ảnh (trang 15): (1) 他____陈天中，是泰国人，他____也____泰国人。 (2) 王一飞是____中文老师，她____很____。","Hoạt động trên lớp (trang 16) — Ví dụ của Tiểu Ngữ: 我叫白家月，我是法国人。陈天中是我同学，他是……","Tổng kết học tập Bài 1–3 (trang 16–17): Trật tự từ cơ bản (我叫白家月), chào hỏi (你好!), cảm ơn (谢谢!), tạm biệt (再见!), xin lỗi (对不起。), tự giới thiệu (我叫李文。), câu chữ “是” (我是学生。), trợ từ kết cấu “的” (我的中文老师。), câu hỏi “吗” (你是学生吗？)."],"workbook":{"exercisesNote":"SBT Bài 3 (tr. 9–12): Tiểu Ngữ giảng đường — Luyện nghe đọc (听读练): 1. Nghe viết thanh mẫu z/c/s/zh/ch/sh/r; 2. Nghe viết vận mẫu; 3. Nghe viết thanh điệu; 4. Nhìn tranh chọn hội thoại đúng; kèm luyện viết chữ Hán.","answerKeyNote":"听读练:\n• 1 (Thanh mẫu): sān, chī, zǒu, zhèng | zì, chàng, rén, suì | cài, shuǐ, rì, zhōng (s, ch, z, zh, z, ch, r, s, c, sh, r, zh).\n• 2 (Vận mẫu): zū, zhī, cài, zì, chāo | rèn, shàng, zěn, rì, sān | chuān, rè, zhuō, cóng, shéi.\n• 3 (Thanh điệu): chē, rén, chàng, zǎo, shǒu | zhēn, suì, shēng, rì, zhōng | shuǐ, zuò, chuáng, shū, sì.\n• 4 (Nhìn tranh chọn hội thoại): ③ · ④ · ① · ②.","transcriptNote":""}},"4":{"pages":"018–026","titleZh":"我有两个孩子","titlePy":"Wǒ yǒu liǎng gè háizi","titleVi":"Chị có hai con","goals":["Có thể nghe hiểu và sử dụng được câu chữ “有” (1) để diễn đạt sự sở hữu đối với người hoặc vật.","Nắm vững cách sử dụng của cấu trúc “A……，B呢？”.","Nắm vững cách sử dụng của số từ và lượng từ trong bài.","Hiểu về cách người Trung Quốc hỏi và trả lời về tuổi tác, đồng thời có thể sử dụng các từ ngữ phù hợp để hỏi đáp về tuổi."],"words":[{"zh":"有","py":"yǒu","vi":"có","pos":"đgt."},{"zh":"多少","py":"duōshao","vi":"bao nhiêu","pos":"đt."},{"zh":"个","py":"gè","vi":"dùng chung cho nhiều danh từ","pos":"lượng."},{"zh":"哥哥","py":"gēge","vi":"anh trai","pos":"dt."},{"zh":"呢","py":"ne","vi":"thì sao (dùng ở cuối câu hỏi)","pos":"trợ."},{"zh":"没有","py":"méiyǒu","vi":"không có","pos":"đgt."},{"zh":"家","py":"jiā","vi":"gia đình, nhà","pos":"dt."},{"zh":"几","py":"jǐ","vi":"mấy","pos":"đt."},{"zh":"口","py":"kǒu","vi":"chỉ người trong gia đình","pos":"lượng."},{"zh":"爸爸","py":"bàba","vi":"bố, ba","pos":"dt."},{"zh":"妈妈","py":"māma","vi":"mẹ","pos":"dt."},{"zh":"妹妹","py":"mèimei","vi":"em gái","pos":"dt."},{"zh":"和","py":"hé","vi":"và","pos":"liên."},{"zh":"儿子","py":"érzi","vi":"con trai","pos":"dt."},{"zh":"孩子","py":"háizi","vi":"con, trẻ con, trẻ em","pos":"dt."},{"zh":"女儿","py":"nǚ\u0027ér","vi":"con gái","pos":"dt."},{"zh":"岁","py":"suì","vi":"tuổi","pos":"lượng."},{"zh":"他","py":"tā","vi":"anh ấy, cậu ấy, ông ấy...","pos":"đt."},{"zh":"今年","py":"jīnnián","vi":"năm nay","pos":"dt."},{"zh":"多","py":"duō","vi":"bao nhiêu (phó từ chỉ mức độ)","pos":"đt."},{"zh":"大","py":"dà","vi":"lớn (chỉ tuổi tác)","pos":"tt."}],"dialog":[{"section":"Bài khóa 1","context":"Lưu Minh và Vương Nhất Tuyết đang trò chuyện ở trong nhà.","audio":"04-1.mp3","speaker":"刘明","name":"Lưu Minh","zh":"一飞忙吗？","py":"Yīfēi máng ma?","vi":"Nhất Phi có bận không?"},{"section":"Bài khóa 1","context":"Lưu Minh và Vương Nhất Tuyết đang trò chuyện ở trong nhà.","audio":"04-1.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"她很忙。","py":"Tā hěn máng.","vi":"Dì ấy rất bận."},{"section":"Bài khóa 1","context":"Lưu Minh và Vương Nhất Tuyết đang trò chuyện ở trong nhà.","audio":"04-1.mp3","speaker":"刘明","name":"Lưu Minh","zh":"她有多少个学生？","py":"Tā yǒu duōshao gè xuéshēng?","vi":"Dì ấy có bao nhiêu học sinh?"},{"section":"Bài khóa 1","context":"Lưu Minh và Vương Nhất Tuyết đang trò chuyện ở trong nhà.","audio":"04-1.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"她有二十个学生。","py":"Tā yǒu èrshí gè xuéshēng.","vi":"Dì ấy có hai mươi học sinh."},{"section":"Bài khóa 2","context":"Vương Nhất Tuyết và Dương Đồng Lạc trò chuyện với nhau trong giờ nghỉ ở công ty.","audio":"04-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"我有两个哥哥，你呢？","py":"Wǒ yǒu liǎng gè gēge, nǐ ne?","vi":"Chị có hai anh trai. Em thì sao?"},{"section":"Bài khóa 2","context":"Vương Nhất Tuyết và Dương Đồng Lạc trò chuyện với nhau trong giờ nghỉ ở công ty.","audio":"04-3.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"我没有哥哥。","py":"Wǒ méiyǒu gēge.","vi":"Em không có anh trai."},{"section":"Bài khóa 2","context":"Vương Nhất Tuyết và Dương Đồng Lạc trò chuyện với nhau trong giờ nghỉ ở công ty.","audio":"04-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"你家有几口人？","py":"Nǐ jiā yǒu jǐ kǒu rén?","vi":"Nhà em có mấy người?"},{"section":"Bài khóa 2","context":"Vương Nhất Tuyết và Dương Đồng Lạc trò chuyện với nhau trong giờ nghỉ ở công ty.","audio":"04-3.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"我家有四口人，爸爸、妈妈、妹妹和我。","py":"Wǒ jiā yǒu sì kǒu rén, bàba, māma, mèimei hé wǒ.","vi":"Nhà em có bốn người: bố, mẹ, em gái và em."},{"section":"Bài khóa 3","context":"Khi Vương Nhất Tuyết đang đi cùng con trai trên phố thì tình cờ gặp Dương Đồng Lạc.","audio":"04-5.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"这是您儿子吗？","py":"Zhè shì nín érzi ma?","vi":"Đây là con trai chị phải không?"},{"section":"Bài khóa 3","context":"Khi Vương Nhất Tuyết đang đi cùng con trai trên phố thì tình cờ gặp Dương Đồng Lạc.","audio":"04-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"是的。我有两个孩子，一个儿子，一个女儿。","py":"Shì de. Wǒ yǒu liǎng gè háizi, yí gè érzi, yí gè nǚ\u0027ér.","vi":"Đúng vậy. Chị có hai con, một con trai và một con gái."},{"section":"Bài khóa 3","context":"Khi Vương Nhất Tuyết đang đi cùng con trai trên phố thì tình cờ gặp Dương Đồng Lạc.","audio":"04-5.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"您儿子几岁？","py":"Nín érzi jǐ suì?","vi":"Con trai chị mấy tuổi rồi?"},{"section":"Bài khóa 3","context":"Khi Vương Nhất Tuyết đang đi cùng con trai trên phố thì tình cờ gặp Dương Đồng Lạc.","audio":"04-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"他今年五岁。","py":"Tā jīnnián wǔ suì.","vi":"Cháu năm nay năm tuổi."},{"section":"Bài khóa 3","context":"Khi Vương Nhất Tuyết đang đi cùng con trai trên phố thì tình cờ gặp Dương Đồng Lạc.","audio":"04-5.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"您女儿多大？","py":"Nín nǚ\u0027ér duō dà?","vi":"Con gái chị bao nhiêu tuổi?"},{"section":"Bài khóa 3","context":"Khi Vương Nhất Tuyết đang đi cùng con trai trên phố thì tình cờ gặp Dương Đồng Lạc.","audio":"04-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"她今年十二。","py":"Tā jīnnián shí\u0027èr.","vi":"Cháu năm nay mười hai tuổi."}],"dialogQuestions":[],"grammar":{"g1":{"han":"“有”字句（1）","py":"“Yǒu” zì jù (1)","title":"Câu chữ “有” (1)","explain":"Từ “有” trong bài này biểu thị sự sở hữu. Phủ định của “有” là “没/没有”.","examples":[{"zh":"她有二十个学生。","py":"Tā yǒu èrshí gè xuéshēng.","vi":"Cô ấy có hai mươi học sinh.","hl":"有"},{"zh":"她有一个姐姐。","py":"Tā yǒu yí gè jiějie.","vi":"Cô ấy có một người chị gái.","hl":"有"},{"zh":"我没/没有姐姐。","py":"Wǒ méi/méiyǒu jiějie.","vi":"Tôi không có chị gái.","hl":"没/没有"}],"struct":"Chủ ngữ + 有 / 没(有) + Tân ngữ","note":"Phủ định của “有” chỉ dùng “没” hoặc “没有”, không dùng “不”."},"g2":{"han":"数字的表达","py":"Shùzì de biǎodá","title":"Cách diễn đạt các con số","explain":"Trong tiếng Trung Quốc, các con số có thể được viết dưới hai dạng: số Ả Rập (ví dụ: “1”) và chữ Hán (ví dụ: “一”). Gồm các số từ 0–99, từ 100 đến dưới 10.000 và cách phân biệt số “2”: viết/đọc là “二 (èr)” hoặc “两 (liǎng)”. Thông thường, “二 (èr)” được dùng chỉ số thứ tự (như “第二”) và khi đếm số; còn “两 (liǎng)” được dùng trước lượng từ.","examples":[{"zh":"二百零八 (208)","py":"èrbǎi líng bā","vi":"Hai trăm linh tám (208)","hl":"二百零八"},{"zh":"一千五百二十八 (1528)","py":"yìqiān wǔbǎi èrshíbā","vi":"Một nghìn năm trăm hai mươi tám (1528)","hl":"一千五百二十八"},{"zh":"十二 / 二十二 / 一百二十二","py":"shí\u0027èr / èrshí\u0027èr / yìbǎi èrshí\u0027èr","vi":"12 / 22 / 122","hl":"二"},{"zh":"两个人 / 两口人 / 两本书","py":"liǎng gè rén / liǎng kǒu rén / liǎng běn shū","vi":"Hai người / hai nhân khẩu / hai quyển sách","hl":"两"}],"struct":"0–99 (零~九十九); 100–9999 (一百~九千九百九十九); 两 + Lượng từ","note":"Chú ý bảng số cơ bản: 零 (0), 一 (1), 二 (2), 三 (3), 四 (4), 五 (5), 六 (6), 七 (7), 八 (8), 九 (9), 十 (10), 百 (100), 千 (1000)."},"g3":{"han":"语气助词“呢”（1）","py":"Yǔqì zhùcí “ne” (1)","title":"Trợ từ ngữ khí “呢” (1)","explain":"Từ “呢” trong bài này được dùng ở cuối câu để biểu thị nghi vấn, dùng để hỏi về tình huống đã được đề cập trước đó.","examples":[{"zh":"我有两个哥哥，你呢？","py":"Wǒ yǒu liǎng gè gēge, nǐ ne?","vi":"Chị có hai anh trai, em thì sao?","hl":"呢"},{"zh":"我叫白家月，你呢？","py":"Wǒ jiào Bái Jiāyuè, nǐ ne?","vi":"Mình tên là Bạch Gia Nguyệt, còn bạn?","hl":"呢"},{"zh":"我是中国人，你呢？","py":"Wǒ shì Zhōngguórén, nǐ ne?","vi":"Tôi là người Trung Quốc, còn bạn?","hl":"呢"}],"struct":"A……，B呢？"},"g4":{"han":"名量词和名量结构","py":"Míngliàngcí hé míngliàng jiégòu","title":"Danh lượng từ và cấu trúc danh lượng","explain":"Khi diễn đạt số lượng, trong tiếng Trung Quốc sau số từ thường phải có lượng từ. Trong bài này học các danh lượng từ biểu thị số lượng người hoặc vật như “口”, “个” và cấu trúc danh lượng.","examples":[{"zh":"四口 / 四口人","py":"sì kǒu / sì kǒu rén","vi":"Bốn người (trong gia đình)","hl":"四口"},{"zh":"两个 / 两个学生","py":"liǎng gè / liǎng gè xuéshēng","vi":"Hai người / hai học sinh","hl":"两个"}],"struct":"Số từ + Lượng từ + (Danh từ)","note":"“口” dùng chỉ số người trong gia đình (nhân khẩu); “个” là lượng từ phổ biến dùng chung cho nhiều danh từ."}},"grammarQuiz":[{"id":"hsk1_b4_q1","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"选词填空：王一飞老师有______个学生。","opts":[{"t":"呢","ok":false},{"t":"二十","ok":true},{"t":"没","ok":false},{"t":"口","ok":false},{"t":"大","ok":false}],"exp":"Trước lượng từ “个” cần số từ để chỉ số lượng học sinh: “二十个学生” (20 học sinh)."},{"id":"hsk1_b4_q2","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"选词填空：杨同乐家有四______人。","opts":[{"t":"呢","ok":false},{"t":"二十","ok":false},{"t":"没","ok":false},{"t":"口","ok":true},{"t":"大","ok":false}],"exp":"Lượng từ chỉ số người trong gia đình là “口”: “四口人” (bốn nhân khẩu)."},{"id":"hsk1_b4_q3","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"选词填空：王一雪：我有两个孩子，你______？","opts":[{"t":"呢","ok":true},{"t":"二十","ok":false},{"t":"没","ok":false},{"t":"口","ok":false},{"t":"大","ok":false}],"exp":"Cấu trúc “A……，B呢？” dùng “呢” ở cuối câu để hỏi lại tình huống vừa nêu."},{"id":"hsk1_b4_q4","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"选词填空：杨同乐：我______孩子。","opts":[{"t":"呢","ok":false},{"t":"二十","ok":false},{"t":"没","ok":true},{"t":"口","ok":false},{"t":"大","ok":false}],"exp":"Phủ định của “有” là “没/没有”: “我没孩子” (Em không có con)."},{"id":"hsk1_b4_q5","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"选词填空：杨同乐：您女儿今年多______？王一雪：我女儿今年十二。","opts":[{"t":"呢","ok":false},{"t":"二十","ok":false},{"t":"没","ok":false},{"t":"口","ok":false},{"t":"大","ok":true}],"exp":"Hỏi tuổi người trên 10 tuổi dùng “多大”: “您女儿今年多大？”."}],"chars":["有","多","少","个","哥","呢","没","家","几","口","爸","妈","妹","和","儿","孩","女","岁","年","大"],"rhyme":null,"notes":["小语助力 (Tiểu Ngữ giúp sức): “几岁？” — 十岁以下时的问法。Đây là cách để hỏi tuổi của trẻ em dưới mười tuổi.","小语助力 (Tiểu Ngữ giúp sức): 十岁以上一般不问“几岁”，要问“多大”。Đối với những người trên mười tuổi, chúng ta thường hỏi “多大”, không hỏi “几岁”.","根据课文内容回答问题 (Trả lời câu hỏi theo nội dung bài khóa): (1) 王一雪有几个儿子？几个女儿？(Vương Nhất Tuyết có mấy con trai? Mấy con gái?) (2) 王一雪儿子今年几岁？(Con trai của Vương Nhất Tuyết năm nay lên mấy?)","小语的彩蛋 (Món quà của Tiểu Ngữ 4-1): 年龄的问法 — Cách hỏi tuổi."],"workbook":{"exercisesNote":"SBT Bài 4 (tr. 13–21): Tiểu Ngữ giảng đường — Luyện nghe đọc (chọn âm tiết nghe được) + Đề luyện mô phỏng 模拟测练 (20 câu: Phần I Nghe 1–10, Phần II Đọc hiểu 11–20).","answerKeyNote":"听读练 1 (Chọn âm tiết): (1) pā | (2) zì | (3) láng | (4) jǔ | (5) mén | (6) rù | (7) kè | (8) qǐng.\n模拟测练 — Nghe (1–10): P1: 1.B 2.C 3.B | P2: 4.B 5.B | P3: 6.D 7.C 8.B | P4: 9.A 10.C.\n模拟测练 — Đọc (11–20): P1: 11.C 12.D 13.B | P2: 14.C 15.D 16.B | P3: 17.B 18.A | P4: 19.B 20.A.","transcriptNote":""}},"5":{"pages":"027–034","titleZh":"今天我休息","titlePy":"Jīntiān wǒ xiūxi","titleVi":"Hôm nay anh được nghỉ","goals":["Có thể nghe hiểu, đọc hiểu và miêu tả được ngày tháng xảy ra sự việc hoặc hành động theo cách diễn đạt thông thường trong tiếng Trung Quốc.","Có thể nghe hiểu và sử dụng được động từ năng nguyện “会” để diễn đạt việc biết hoặc có khả năng làm một việc gì đó.","Nắm vững cách sử dụng của câu vị ngữ danh từ."],"words":[{"zh":"今天","py":"jīntiān","vi":"hôm nay","pos":"dt."},{"zh":"号","py":"hào","vi":"ngày, mùng","pos":"lượng."},{"zh":"月","py":"yuè","vi":"tháng","pos":"dt."},{"zh":"日","py":"rì","vi":"ngày","pos":"lượng."},{"zh":"星期","py":"xīngqī","vi":"thứ, tuần","pos":"dt."},{"zh":"星期日","py":"Xīngqīrì","vi":"Chủ nhật","pos":"dt."},{"zh":"星期天","py":"Xīngqītiān","vi":"Chủ nhật","pos":"dt."},{"zh":"休息","py":"xiūxi","vi":"nghỉ, nghỉ ngơi","pos":"đgt."},{"zh":"会","py":"huì","vi":"biết, có thể","pos":"đtnn."},{"zh":"做饭","py":"zuò fàn","vi":"nấu ăn","pos":""},{"zh":"做","py":"zuò","vi":"làm, nấu","pos":"đgt."},{"zh":"面条儿","py":"miàntiáor","vi":"mì, mì sợi","pos":"dt."},{"zh":"饺子","py":"jiǎozi","vi":"sủi cảo","pos":"dt."},{"zh":"一些","py":"yìxiē","vi":"một số, một vài","pos":"sl."},{"zh":"菜","py":"cài","vi":"món ăn, rau","pos":"dt."},{"zh":"下班","py":"xiàbān","vi":"tan làm, tan ca","pos":"đgt."},{"zh":"新","py":"xīn","vi":"mới","pos":"tt."},{"zh":"电脑","py":"diànnǎo","vi":"máy tính, máy vi tính","pos":"dt."},{"zh":"真","py":"zhēn","vi":"thật, thực sự","pos":"phó."},{"zh":"好看","py":"hǎokàn","vi":"đẹp","pos":"tt."},{"zh":"喜欢","py":"xǐhuan","vi":"thích","pos":"đgt."},{"zh":"它","py":"tā","vi":"nó","pos":"đt."}],"dialog":[{"section":"Bài khóa 1","context":"Lưu Minh và Vương Nhất Tuyết đang trò chuyện ở trong nhà.","audio":"05-1.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"今天几号？","py":"Jīntiān jǐ hào?","vi":"Hôm nay ngày mấy anh nhỉ?"},{"section":"Bài khóa 1","context":"Lưu Minh và Vương Nhất Tuyết đang trò chuyện ở trong nhà.","audio":"05-1.mp3","speaker":"刘明","name":"Lưu Minh","zh":"今天9月8号。","py":"Jīntiān jiǔ yuè bā hào.","vi":"Hôm nay là ngày 8 tháng 9."},{"section":"Bài khóa 1","context":"Lưu Minh và Vương Nhất Tuyết đang trò chuyện ở trong nhà.","audio":"05-1.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"星期几？","py":"Xīngqī jǐ?","vi":"Thứ mấy vậy?"},{"section":"Bài khóa 1","context":"Lưu Minh và Vương Nhất Tuyết đang trò chuyện ở trong nhà.","audio":"05-1.mp3","speaker":"刘明","name":"Lưu Minh","zh":"星期日。今天我休息。","py":"Xīngqīrì. Jīntiān wǒ xiūxi.","vi":"Chủ nhật. Hôm nay anh được nghỉ."},{"section":"Bài khóa 2","context":"Vương Nhất Tuyết và Dương Đồng Lạc đang trò chuyện trong giờ nghỉ tại công ty.","audio":"05-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"你会做饭吗？","py":"Nǐ huì zuò fàn ma?","vi":"Em có biết nấu ăn không?"},{"section":"Bài khóa 2","context":"Vương Nhất Tuyết và Dương Đồng Lạc đang trò chuyện trong giờ nghỉ tại công ty.","audio":"05-3.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"我会做。","py":"Wǒ huì zuò.","vi":"Em biết."},{"section":"Bài khóa 2","context":"Vương Nhất Tuyết và Dương Đồng Lạc đang trò chuyện trong giờ nghỉ tại công ty.","audio":"05-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"你会做什么？","py":"Nǐ huì zuò shénme?","vi":"Em biết nấu món gì?"},{"section":"Bài khóa 2","context":"Vương Nhất Tuyết và Dương Đồng Lạc đang trò chuyện trong giờ nghỉ tại công ty.","audio":"05-3.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"我会做面条儿、饺子，也会做一些菜。星期天我也做饭。","py":"Wǒ huì zuò miàntiáor, jiǎozi, yě huì zuò yìxiē cài. Xīngqītiān wǒ yě zuò fàn.","vi":"Em biết nấu mì, sủi cảo và biết chế biến một số món ăn khác. Chủ nhật em cũng nấu ăn."},{"section":"Bài khóa 3","context":"Vương Nhất Tuyết và Dương Đồng Lạc đang trò chuyện sau giờ làm ở công ty.","audio":"05-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"同乐，下班吗？","py":"Tónglè, xiàbān ma?","vi":"Đồng Lạc, em tan làm chưa?"},{"section":"Bài khóa 3","context":"Vương Nhất Tuyết và Dương Đồng Lạc đang trò chuyện sau giờ làm ở công ty.","audio":"05-5.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"下班。","py":"Xiàbān.","vi":"Em tan làm rồi."},{"section":"Bài khóa 3","context":"Vương Nhất Tuyết và Dương Đồng Lạc đang trò chuyện sau giờ làm ở công ty.","audio":"05-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"这是你的新电脑吗？","py":"Zhè shì nǐ de xīn diànnǎo ma?","vi":"Đây là máy tính mới của em à?"},{"section":"Bài khóa 3","context":"Vương Nhất Tuyết và Dương Đồng Lạc đang trò chuyện sau giờ làm ở công ty.","audio":"05-5.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"是的，是我的新电脑。","py":"Shì de, shì wǒ de xīn diànnǎo.","vi":"Đúng vậy, đây là máy tính mới của em."},{"section":"Bài khóa 3","context":"Vương Nhất Tuyết và Dương Đồng Lạc đang trò chuyện sau giờ làm ở công ty.","audio":"05-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"真好看！","py":"Zhēn hǎokàn!","vi":"Đẹp thật đấy!"},{"section":"Bài khóa 3","context":"Vương Nhất Tuyết và Dương Đồng Lạc đang trò chuyện sau giờ làm ở công ty.","audio":"05-5.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"我也很喜欢它。","py":"Wǒ yě hěn xǐhuan tā.","vi":"Em cũng rất thích nó."}],"dialogQuestions":[],"grammar":{"g1":{"han":"时间的表达（1）","py":"Shíjiān de biǎodá (1)","title":"Cách diễn đạt thời gian (1)","explain":"Trong bài này học cách diễn đạt ngày tháng và các thứ trong tuần. Trật tự diễn đạt ngày tháng và thứ trong tiếng Trung Quốc đi từ lớn đến nhỏ: 年→月→日/号→星期.","examples":[{"zh":"1992年5月16日/号，星期六","py":"yī jiǔ jiǔ èr nián wǔ yuè shíliù rì / hào, Xīngqīliù","vi":"Thứ Bảy, ngày 16 tháng 5 năm 1992","hl":"1992年5月16日/号，星期六"},{"zh":"2024年10月22日/号，星期二","py":"èr líng èr sì nián shí yuè èrshí\u0027èr rì / hào, Xīngqī\u0027èr","vi":"Thứ Ba, ngày 22 tháng 10 năm 2024","hl":"2024年10月22日/号，星期二"},{"zh":"今天9月8号。","py":"Jīntiān jiǔ yuè bā hào.","vi":"Hôm nay là ngày 8 tháng 9.","hl":"9月8号"},{"zh":"今天是2025年5月22号。","py":"Jīntiān shì èr líng èr wǔ nián wǔ yuè èrshí\u0027èr hào.","vi":"Hôm nay là ngày 22 tháng 5 năm 2025.","hl":"2025年5月22号"},{"zh":"明天是2024年8月18号，星期天。","py":"Míngtiān shì èr líng èr sì nián bā yuè shíbā hào, Xīngqītiān.","vi":"Ngày mai là Chủ nhật, ngày 18 tháng 8 năm 2024.","hl":"2024年8月18号，星期天"}],"struct":"年 (năm) → 月 (tháng) → 日/号 (ngày) → 星期 (thứ)","note":"Tháng 1–12: 一月 đến 十二月. Thứ Hai đến Thứ Bảy: 星期一 đến 星期六; Chủ nhật: 星期日 / 星期天."},"g2":{"han":"名词谓语句","py":"Míngcí wèiyǔjù","title":"Câu có vị ngữ danh từ","explain":"Trong câu vị ngữ danh từ, thành phần vị ngữ chỉ có danh từ hoặc thành phần có tính chất như một danh từ thì những thành phần này thường là những từ ngữ được dùng để chỉ thời gian, ngày tháng, tuổi tác...","examples":[{"zh":"A：今天几号？ B：今天5月1号。","py":"A: Jīntiān jǐ hào? B: Jīntiān wǔ yuè yī hào.","vi":"A: Hôm nay ngày mấy? B: Hôm nay ngày 1 tháng 5.","hl":"5月1号"},{"zh":"我妹妹12岁。","py":"Wǒ mèimei shí\u0027èr suì.","vi":"Em gái tôi 12 tuổi.","hl":"12岁"}],"struct":"Chủ ngữ + Cụm danh từ (thời gian / ngày tháng / tuổi tác)","note":"Không cần dùng động từ “是” trong câu khẳng định vị ngữ danh từ chỉ thời gian, ngày tháng, tuổi tác."},"g3":{"han":"能愿动词“会”","py":"Néngyuàn dòngcí “huì”","title":"Động từ năng nguyện “会”","explain":"“会” đặt trước động từ, biểu thị việc biết hoặc có khả năng thực hiện một hành động nào đó thông qua học tập.","examples":[{"zh":"你会做饭吗？","py":"Nǐ huì zuò fàn ma?","vi":"Bạn có biết nấu ăn không?","hl":"会"},{"zh":"我会做面条儿。","py":"Wǒ huì zuò miàntiáor.","vi":"Tôi biết nấu mì.","hl":"会"},{"zh":"我不会做菜。","py":"Wǒ bú huì zuò cài.","vi":"Tôi không biết nấu món ăn.","hl":"不会"}],"struct":"Chủ ngữ + (不)会 + Động từ + (Tân ngữ)","note":"Dạng phủ định là “不会” (bú huì)."}},"grammarQuiz":[{"id":"hsk1_b5_q1","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"选词填空：今天______。","opts":[{"t":"菜","ok":false},{"t":"喜欢","ok":false},{"t":"6月22号","ok":true},{"t":"新","ok":false},{"t":"真","ok":false}],"exp":"Câu vị ngữ danh từ chỉ ngày tháng: “今天6月22号。” (Hôm nay là ngày 22 tháng 6)."},{"id":"hsk1_b5_q2","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"选词填空：杨同乐有一个______电脑。","opts":[{"t":"菜","ok":false},{"t":"喜欢","ok":false},{"t":"6月22号","ok":false},{"t":"新","ok":true},{"t":"真","ok":false}],"exp":"Tính từ “新” (mới) làm định ngữ cho danh từ “电脑”: “一个新电脑” (một chiếc máy tính mới)."},{"id":"hsk1_b5_q3","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"选词填空：王一雪：你会做这两个______吗？杨同乐：我会做。","opts":[{"t":"菜","ok":true},{"t":"喜欢","ok":false},{"t":"6月22号","ok":false},{"t":"新","ok":false},{"t":"真","ok":false}],"exp":"Tân ngữ của động từ “做” (nấu) là “菜” (món ăn): “做这两个菜” (nấu hai món này)."},{"id":"hsk1_b5_q4","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"选词填空：王一雪：你的电脑______好看！","opts":[{"t":"菜","ok":false},{"t":"喜欢","ok":false},{"t":"6月22号","ok":false},{"t":"新","ok":false},{"t":"真","ok":true}],"exp":"Phó từ “真” (thật) đứng trước tính từ “好看” để cảm thán: “真好看！” (Đẹp thật đấy!)."},{"id":"hsk1_b5_q5","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"选词填空：杨同乐：我也很______。","opts":[{"t":"菜","ok":false},{"t":"喜欢","ok":true},{"t":"6月22号","ok":false},{"t":"新","ok":false},{"t":"真","ok":false}],"exp":"Động từ tâm lý “喜欢” (thích) đi sau phó từ mức độ “很”: “我也很喜欢” (Em cũng rất thích)."}],"chars":["今","天","号","月","日","星","期","休","息","会","做","饭","面","菜","下","新","电","真","喜","它"],"rhyme":null,"notes":["小语助力 (Tiểu Ngữ giúp sức): 也说“9月8日”。Ngày 8 tháng 9 cũng có thể được diễn đạt là “9月8日”.","小语助力 (Tiểu Ngữ giúp sức): 也说“星期天”。Chủ nhật cũng có thể được diễn đạt là “星期天”.","根据课文内容回答问题 (Trả lời câu hỏi theo nội dung bài khóa): (1) 杨同乐的新电脑怎么样？(Máy tính mới của Dương Đồng Lạc như thế nào?) (2) 杨同乐喜欢他的新电脑吗？(Dương Đồng Lạc có thích máy tính mới của anh ấy không?)","小语的彩蛋 (Món quà của Tiểu Ngữ 5-1): 中国美食——饺子 — Món ngon của Trung Quốc: Bánh sủi cảo."],"workbook":{"exercisesNote":"SBT Bài 5 (tr. 22–30): Tiểu Ngữ giảng đường — Luyện nghe đọc (chọn âm tiết nghe được) + Đề luyện mô phỏng 模拟测练 (20 câu: Phần I Nghe 1–10, Phần II Đọc hiểu 11–20).","answerKeyNote":"听读练 1 (Chọn âm tiết): (1) gē | (2) qiǎng | (3) sóng | (4) nìng | (5) jiā | (6) cuàn | (7) tōu | (8) shí.\n模拟测练 — Nghe (1–10): P1: 1.C 2.A 3.B | P2: 4.A 5.B | P3: 6.C 7.B 8.D | P4: 9.B 10.B.\n模拟测练 — Đọc (11–20): P1: 11.D 12.C 13.B | P2: 14.C 15.B 16.D | P3: 17.A 18.B | P4: 19.C 20.B.","transcriptNote":""}},"6":{"pages":"035–044","titleZh":"你的手机号是多少？","titlePy":"Nǐ de shǒujīhào shì duōshao?","titleVi":"Số điện thoại di động của bạn là bao nhiêu?","goals":["Có thể nghe hiểu số điện thoại di động và sử dụng chúng để gọi điện.","Có thể nghe hiểu và sử dụng được hai hoặc nhiều cụm động từ để diễn đạt mục đích hoặc cách thức của hành động.","Nắm vững cách dùng của động từ năng nguyện “想”.","Nắm vững cách dùng của đại từ nghi vấn “怎么” để hỏi về phương thức thực hiện hành động."],"words":[{"zh":"手机","py":"shǒujī","vi":"điện thoại di động","pos":"dt."},{"zh":"电话","py":"diànhuà","vi":"điện thoại (máy cố định)","pos":"dt."},{"zh":"号","py":"hào","vi":"số","pos":"dt."},{"zh":"明天","py":"míngtiān","vi":"ngày mai","pos":"dt."},{"zh":"去","py":"qù","vi":"đi","pos":"đgt."},{"zh":"哪儿","py":"nǎr","vi":"đâu, chỗ nào, nơi nào","pos":"đt."},{"zh":"想","py":"xiǎng","vi":"muốn","pos":"đtnn."},{"zh":"超市","py":"chāoshì","vi":"siêu thị","pos":"dt."},{"zh":"买","py":"mǎi","vi":"mua","pos":"đgt."},{"zh":"东西","py":"dōngxi","vi":"đồ, đồ đạc","pos":"dt."},{"zh":"些","py":"xiē","vi":"một ít, một vài","pos":"lượng."},{"zh":"牛奶","py":"niúnǎi","vi":"sữa (bò)","pos":"dt."},{"zh":"吃","py":"chī","vi":"ăn","pos":"đgt."},{"zh":"晚饭","py":"wǎnfàn","vi":"bữa tối","pos":"dt."},{"zh":"那边","py":"nàbiān","vi":"bên kia, chỗ đó","pos":"đt."},{"zh":"包子","py":"bāozi","vi":"bánh bao (có nhân)","pos":"dt."},{"zh":"非常","py":"fēicháng","vi":"rất, vô cùng, cực kỳ","pos":"phó."},{"zh":"好吃","py":"hǎochī","vi":"ngon","pos":"tt."},{"zh":"米饭","py":"mǐfàn","vi":"cơm (cơm trắng)","pos":"dt."},{"zh":"怎么","py":"zěnme","vi":"thế nào, bằng cách nào, như thế nào","pos":"đt."},{"zh":"坐","py":"zuò","vi":"ngồi, đi (xe, tàu...)","pos":"đgt."},{"zh":"出租车","py":"chūzūchē","vi":"xe taxi","pos":"dt."},{"zh":"西安饭店","py":"Xī\u0027ān Fàndiàn","vi":"nhà hàng Tây An","pos":"dt. riêng"}],"dialog":[{"section":"Bài khóa 1","context":"Lý Văn đang hỏi xin số điện thoại di động của Bạch Gia Nguyệt trong khuôn viên trường.","audio":"06-1.mp3","speaker":"李文","name":"Lý Văn","zh":"家月，你的手机号是多少？","py":"Jiāyuè, nǐ de shǒujīhào shì duōshao?","vi":"Gia Nguyệt, số điện thoại di động của bạn là bao nhiêu?"},{"section":"Bài khóa 1","context":"Lý Văn đang hỏi xin số điện thoại di động của Bạch Gia Nguyệt trong khuôn viên trường.","audio":"06-1.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"我的手机号是+33 601493190。","py":"Wǒ de shǒujīhào shì sān sān liù líng yāo sì jiǔ sān yāo jiǔ líng.","vi":"Số điện thoại di động của mình là +33 601493190."},{"section":"Bài khóa 1","context":"Lý Văn đang hỏi xin số điện thoại di động của Bạch Gia Nguyệt trong khuôn viên trường.","audio":"06-1.mp3","speaker":"李文","name":"Lý Văn","zh":"我的手机号是+86 13552721160。","py":"Wǒ de shǒujīhào shì bā liù yāo sān wǔ wǔ èr qī èr yāo yāo liù líng.","vi":"Số của mình là +86 13552721160."},{"section":"Bài khóa 1","context":"Lý Văn đang hỏi xin số điện thoại di động của Bạch Gia Nguyệt trong khuôn viên trường.","audio":"06-1.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"好的。","py":"Hǎo de.","vi":"Ừ."},{"section":"Bài khóa 2","context":"Bạch Gia Nguyệt và Trần Thiên Trung đang trò chuyện trong lớp sau khi tan học.","audio":"06-3.mp3","speaker":"陈天中","name":"Trần Thiên Trung","zh":"家月，明天你去哪儿？","py":"Jiāyuè, míngtiān nǐ qù nǎr?","vi":"Gia Nguyệt, ngày mai bạn đi đâu?"},{"section":"Bài khóa 2","context":"Bạch Gia Nguyệt và Trần Thiên Trung đang trò chuyện trong lớp sau khi tan học.","audio":"06-3.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"我想去超市买东西。","py":"Wǒ xiǎng qù chāoshì mǎi dōngxi.","vi":"Mình muốn đi siêu thị mua đồ."},{"section":"Bài khóa 2","context":"Bạch Gia Nguyệt và Trần Thiên Trung đang trò chuyện trong lớp sau khi tan học.","audio":"06-3.mp3","speaker":"陈天中","name":"Trần Thiên Trung","zh":"你去超市买什么？","py":"Nǐ qù chāoshì mǎi shénme?","vi":"Bạn đi siêu thị mua gì vậy?"},{"section":"Bài khóa 2","context":"Bạch Gia Nguyệt và Trần Thiên Trung đang trò chuyện trong lớp sau khi tan học.","audio":"06-3.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"我想买些牛奶。","py":"Wǒ xiǎng mǎi xiē niúnǎi.","vi":"Mình muốn mua ít sữa."},{"section":"Bài khóa 3","context":"Gia đình Vương Nhất Tuyết đang bàn về kế hoạch cho bữa tối cuối tuần ở trong nhà.","audio":"06-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"星期天我们去哪儿吃晚饭？","py":"Xīngqītiān wǒmen qù nǎr chī wǎnfàn?","vi":"Chủ nhật này nhà mình đi đâu ăn tối nhỉ?"},{"section":"Bài khóa 3","context":"Gia đình Vương Nhất Tuyết đang bàn về kế hoạch cho bữa tối cuối tuần ở trong nhà.","audio":"06-5.mp3","speaker":"刘明","name":"Lưu Minh","zh":"我还想去西安饭店。","py":"Wǒ hái xiǎng qù Xī\u0027ān Fàndiàn.","vi":"Bố vẫn muốn đến nhà hàng Tây An."},{"section":"Bài khóa 3","context":"Gia đình Vương Nhất Tuyết đang bàn về kế hoạch cho bữa tối cuối tuần ở trong nhà.","audio":"06-5.mp3","speaker":"刘小雪","name":"Lưu Tiểu Tuyết","zh":"那边的包子非常好吃，我想吃包子。","py":"Nàbiān de bāozi fēicháng hǎochī, wǒ xiǎng chī bāozi.","vi":"Bánh bao ở đó rất ngon, con muốn ăn bánh bao."},{"section":"Bài khóa 3","context":"Gia đình Vương Nhất Tuyết đang bàn về kế hoạch cho bữa tối cuối tuần ở trong nhà.","audio":"06-5.mp3","speaker":"刘小明","name":"Lưu Tiểu Minh","zh":"妈妈，我想吃米饭，不想吃包子。","py":"Māma, wǒ xiǎng chī mǐfàn, bù xiǎng chī bāozi.","vi":"Mẹ ơi, con muốn ăn cơm, không muốn ăn bánh bao đâu."},{"section":"Bài khóa 3","context":"Gia đình Vương Nhất Tuyết đang bàn về kế hoạch cho bữa tối cuối tuần ở trong nhà.","audio":"06-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"好的。我们怎么去？","py":"Hǎo de. Wǒmen zěnme qù?","vi":"Được thôi. Chúng ta đi thế nào nhỉ?"},{"section":"Bài khóa 3","context":"Gia đình Vương Nhất Tuyết đang bàn về kế hoạch cho bữa tối cuối tuần ở trong nhà.","audio":"06-5.mp3","speaker":"刘明","name":"Lưu Minh","zh":"坐出租车去。","py":"Zuò chūzūchē qù.","vi":"Đi taxi nhé."}],"dialogQuestions":[],"grammar":{"g1":{"han":"能愿动词“想”","py":"Néngyuàn dòngcí “xiǎng”","title":"Động từ năng nguyện “想”","explain":"Động từ năng nguyện “想” đặt trước động từ, dùng để biểu thị mong muốn hoặc dự định.","examples":[{"zh":"我想去超市。","py":"Wǒ xiǎng qù chāoshì.","vi":"Tôi muốn đi siêu thị.","hl":"想"},{"zh":"我哥哥不想休息。","py":"Wǒ gēge bù xiǎng xiūxi.","vi":"Anh trai tôi không muốn nghỉ ngơi.","hl":"不想"}],"struct":"Chủ ngữ + (不)想 + Động từ + (Tân ngữ)","note":"Dạng phủ định là “不想”."},"g2":{"han":"连动句（1）","py":"Liándòngjù (1)","title":"Câu liên động (1)","explain":"Câu liên động là câu mà vị ngữ do hai hoặc nhiều hơn hai cụm động từ tạo nên. Câu liên động thường có hai ý nghĩa: (1) Chỉ mục đích của hành động; (2) Chỉ phương thức của hành động.","examples":[{"zh":"我想去超市买东西。","py":"Wǒ xiǎng qù chāoshì mǎi dōngxi.","vi":"Tôi muốn đi siêu thị mua đồ. (chỉ mục đích)","hl":"去超市买东西"},{"zh":"我们去西安饭店吃晚饭。","py":"Wǒmen qù Xī\u0027ān Fàndiàn chī wǎnfàn.","vi":"Chúng tôi đến nhà hàng Tây An ăn tối. (chỉ mục đích)","hl":"去西安饭店吃晚饭"},{"zh":"我们坐出租车去西安饭店。","py":"Wǒmen zuò chūzūchē qù Xī\u0027ān Fàndiàn.","vi":"Chúng tôi đi taxi đến nhà hàng Tây An. (chỉ phương thức)","hl":"坐出租车去西安饭店"},{"zh":"她坐出租车去超市。","py":"Tā zuò chūzūchē qù chāoshì.","vi":"Cô ấy đi taxi đến siêu thị. (chỉ phương thức)","hl":"坐出租车去超市"}],"struct":"Chủ ngữ + Động từ 1 (tân ngữ 1) + Động từ 2 (tân ngữ 2)","note":"Khi chỉ mục đích: động từ 2 nêu mục đích của động từ 1. Khi chỉ phương thức: động từ 1 nêu phương tiện/cách thức để thực hiện động từ 2."},"g3":{"han":"疑问代词“怎么”","py":"Yíwèn dàicí “zěnme”","title":"Đại từ nghi vấn “怎么”","explain":"Đại từ nghi vấn “怎么” đặt trước động từ, để hỏi về phương thức thực hiện hành động.","examples":[{"zh":"我们怎么去？","py":"Wǒmen zěnme qù?","vi":"Chúng ta đi như thế nào?","hl":"怎么"},{"zh":"她怎么去超市？","py":"Tā zěnme qù chāoshì?","vi":"Cô ấy đi siêu thị bằng cách nào?","hl":"怎么"}],"struct":"Chủ ngữ + 怎么 + Động từ + (Tân ngữ)?"}},"grammarQuiz":[{"id":"hsk1_b6_q1","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"选词填空：我想______超市买牛奶。","opts":[{"t":"多少","ok":false},{"t":"买","ok":false},{"t":"米饭","ok":false},{"t":"坐","ok":false},{"t":"去","ok":true}],"exp":"Câu liên động chỉ mục đích: “去超市买牛奶” (đi siêu thị mua sữa)."},{"id":"hsk1_b6_q2","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"选词填空：我想去超市______牛奶。","opts":[{"t":"多少","ok":false},{"t":"买","ok":true},{"t":"米饭","ok":false},{"t":"坐","ok":false},{"t":"去","ok":false}],"exp":"Động từ thứ hai chỉ mục đích ở siêu thị là “买” (mua): “去超市买牛奶”."},{"id":"hsk1_b6_q3","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"选词填空：我们______出租车去西安饭店吃晚饭。","opts":[{"t":"多少","ok":false},{"t":"买","ok":false},{"t":"米饭","ok":false},{"t":"坐","ok":true},{"t":"去","ok":false}],"exp":"Đi phương tiện giao thông như xe taxi dùng động từ “坐”: “坐出租车”."},{"id":"hsk1_b6_q4","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"选词填空：妈妈：你想吃什么？孩子：我想吃______。","opts":[{"t":"多少","ok":false},{"t":"买","ok":false},{"t":"米饭","ok":true},{"t":"坐","ok":false},{"t":"去","ok":false}],"exp":"Tân ngữ chỉ đồ ăn đi với “吃” là “米饭” (cơm trắng)."},{"id":"hsk1_b6_q5","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"选词填空：老师：你的手机号是______？学生：我的手机号是13126975002。","opts":[{"t":"多少","ok":true},{"t":"买","ok":false},{"t":"米饭","ok":false},{"t":"坐","ok":false},{"t":"去","ok":false}],"exp":"Hỏi số điện thoại dùng đại từ nghi vấn “多少”: “你的手机号是多少？”."}],"chars":["手","机","话","明","去","哪","想","买","东","西","些","牛","奶","吃","晚","包","米","怎","么","坐","车"],"rhyme":null,"notes":["小语助力 (Tiểu Ngữ giúp sức): 现在人们有时也用“电话”指代“手机”。Hiện nay, đôi khi người ta cũng dùng từ “电话” (điện thoại) để thay cho “手机” (điện thoại di động).","小语助力 (Tiểu Ngữ giúp sức): 手机号要一位一位地读，而且数字“1”要读成“yāo”。Số điện thoại di động cần đọc từng chữ số một. Riêng số “1” phải đọc là “yāo”.","根据课文内容回答问题 (Trả lời câu hỏi theo nội dung bài khóa): (1) 西安饭店的包子好吃吗？(Bánh bao của nhà hàng Tây An có ngon không?) (2) 他们怎么去西安饭店？(Họ sẽ đến nhà hàng Tây An bằng cách nào?)","学习小结 (Tổng kết học tập Bài 4–6, trang 043–044): Câu chữ “有” (1), Cách diễn đạt các con số, Trợ từ ngữ khí “呢” (1), Danh lượng từ và cấu trúc danh lượng, Cách hỏi tuổi với các độ tuổi khác nhau, Cách diễn đạt thời gian (1), Câu vị ngữ danh từ, Động từ năng nguyện “会”, Động từ năng nguyện “想”, Câu liên động (1), Đại từ nghi vấn “怎么”."],"workbook":{"exercisesNote":"SBT Bài 6 (tr. 31–38): Tiểu Ngữ giảng đường — Luyện nghe đọc (chọn từ song âm tiết nghe được) + Đề luyện mô phỏng 模拟测练 (20 câu: Phần I Nghe 1–10, Phần II Đọc hiểu 11–20).","answerKeyNote":"听读练 1 (Chọn song âm tiết): (1) nàbiān | (2) dōngxi | (3) chāoshì | (4) wǎnfàn | (5) shǒujī | (6) diànhuà.\n模拟测练 — Nghe (1–10): P1: 1.B 2.B 3.C | P2: 4.A 5.C | P3: 6.C 7.B 8.D | P4: 9.A 10.C.\n模拟测练 — Đọc (11–20): P1: 11.C 12.B 13.D | P2: 14.C 15.A 16.B | P3: 17.B 18.A | P4: 19.A 20.B.","transcriptNote":""}},"7":{"pages":"045–053","titleZh":"我晚上六点半下班","titlePy":"Wǒ wǎnshang liù diǎn bàn xiàbān","titleVi":"Em tan làm lúc 6 rưỡi tối","goals":["Có thể nghe hiểu và miêu tả được thời gian xảy ra sự việc.","Nắm vững cách dùng của trợ từ ngữ khí “吧” (1) khi đưa ra lời đề nghị, thương lượng...","Nắm vững cách dùng của trợ từ ngữ khí “呢” (2) để xác nhận sự việc.","Nắm vững vị trí của phó từ, từ ngữ chỉ thời gian khi làm trạng ngữ."],"words":[{"zh":"现在","py":"xiànzài","vi":"bây giờ, hiện tại","pos":"dt."},{"zh":"点","py":"diǎn","vi":"giờ","pos":"lượng."},{"zh":"早上","py":"zǎoshang","vi":"buổi sáng, sáng sớm","pos":"dt."},{"zh":"上午","py":"shàngwǔ","vi":"buổi sáng","pos":"dt."},{"zh":"分","py":"fēn","vi":"phút","pos":"lượng."},{"zh":"课","py":"kè","vi":"tiết học, giờ học","pos":"dt."},{"zh":"下午","py":"xiàwǔ","vi":"buổi chiều","pos":"dt."},{"zh":"见","py":"jiàn","vi":"gặp, gặp mặt","pos":"đgt."},{"zh":"吧","py":"ba","vi":"nhé (dùng ở cuối câu để đưa ra đề nghị, gợi ý, thương lượng hoặc yêu cầu)","pos":"trợ."},{"zh":"电影院","py":"diànyǐngyuàn","vi":"rạp chiếu phim, rạp chiếu bóng","pos":"dt."},{"zh":"看","py":"kàn","vi":"xem, nhìn, đọc","pos":"đgt."},{"zh":"电影","py":"diànyǐng","vi":"phim, điện ảnh","pos":"dt."},{"zh":"事","py":"shì","vi":"việc, sự việc","pos":"dt."},{"zh":"上课","py":"shàngkè","vi":"lên lớp, đi học","pos":"đgt."},{"zh":"呢","py":"ne","vi":"đặt ở cuối câu, dùng để nhấn mạnh hoặc duy trì ngữ khí trong câu trần thuật và câu hỏi","pos":"trợ."},{"zh":"半","py":"bàn","vi":"một nửa, rưỡi","pos":"số."},{"zh":"下课","py":"xiàkè","vi":"tan học","pos":"đgt."},{"zh":"在","py":"zài","vi":"ở, tại","pos":"đgt."},{"zh":"家","py":"jiā","vi":"nhà","pos":"dt."},{"zh":"里","py":"li/lǐ","vi":"trong, bên trong","pos":"dt."},{"zh":"晚上","py":"wǎnshang","vi":"buổi tối","pos":"dt."},{"zh":"医院","py":"yīyuàn","vi":"bệnh viện","pos":"dt."},{"zh":"上班","py":"shàngbān","vi":"đi làm, vào ca","pos":"đgt."},{"zh":"店","py":"diàn","vi":"cửa hàng, cửa tiệm","pos":"dt."},{"zh":"菜","py":"cài","vi":"thức ăn, món ăn, rau","pos":"dt."},{"zh":"分钟","py":"fēnzhōng","vi":"phút","pos":"lượng."},{"zh":"后","py":"hòu","vi":"sau, sau đó","pos":"dt."}],"dialog":[{"section":"Bài khoá 1","context":"Bạch Gia Nguyệt và Annie đang nói chuyện điện thoại.","audio":"07-1.mp3","speaker":"A","name":"白家月","zh":"现在几点？","py":"Xiànzài jǐ diǎn?","vi":"Bây giờ là mấy giờ rồi?"},{"section":"Bài khoá 1","context":"Bạch Gia Nguyệt và Annie đang nói chuyện điện thoại.","audio":"07-1.mp3","speaker":"B","name":"安妮","zh":"早上八点四十。","py":"Zǎoshang bā diǎn sìshí.","vi":"8 giờ 40 sáng."},{"section":"Bài khoá 1","context":"Bạch Gia Nguyệt và Annie đang nói chuyện điện thoại.","audio":"07-1.mp3","speaker":"A","name":"白家月","zh":"我上午十点十分有课。","py":"Wǒ shàngwǔ shí diǎn shí fēn yǒu kè.","vi":"Mình có tiết học lúc 10 giờ 10 phút sáng."},{"section":"Bài khoá 1","context":"Bạch Gia Nguyệt và Annie đang nói chuyện điện thoại.","audio":"07-1.mp3","speaker":"B","name":"安妮","zh":"好的，我们下午两点见吧。","py":"Hǎo de, wǒmen xiàwǔ liǎng diǎn jiàn ba.","vi":"Ừ, vậy chúng ta gặp nhau lúc 2 giờ chiều nhé."},{"section":"Bài khoá 2","context":"Lý Văn gặp Bạch Gia Nguyệt trong khuôn viên trường.","audio":"07-3.mp3","speaker":"A","name":"李文","zh":"下午我想去电影院看电影，你去吗？","py":"Xiàwǔ wǒ xiǎng qù diànyǐngyuàn kàn diànyǐng, nǐ qù ma?","vi":"Chiều nay mình muốn đi xem phim ở rạp chiếu phim. Bạn có đi không?"},{"section":"Bài khoá 2","context":"Lý Văn gặp Bạch Gia Nguyệt trong khuôn viên trường.","audio":"07-3.mp3","speaker":"B","name":"白家月","zh":"我不想去，下午还有事。","py":"Wǒ bù xiǎng qù, xiàwǔ hái yǒu shì.","vi":"Mình không muốn đi. Chiều nay mình còn có việc."},{"section":"Bài khoá 2","context":"Lý Văn gặp Bạch Gia Nguyệt trong khuôn viên trường.","audio":"07-3.mp3","speaker":"A","name":"李文","zh":"好的。明天呢？","py":"Hǎo de. Míngtiān ne?","vi":"Ừ. Vậy ngày mai thì sao?"},{"section":"Bài khoá 2","context":"Lý Văn gặp Bạch Gia Nguyệt trong khuôn viên trường.","audio":"07-3.mp3","speaker":"B","name":"白家月","zh":"我明天下午两点还上课呢，四点半下课。","py":"Wǒ míngtiān xiàwǔ liǎng diǎn hái shàngkè ne, sì diǎn bàn xiàkè.","vi":"2 giờ chiều mai mình phải lên lớp, 4 giờ rưỡi tan học."},{"section":"Bài khoá 3","context":"Vương Nhất Tuyết đang gọi điện cho Lưu Minh ở trong phòng làm việc.","audio":"07-5.mp3","speaker":"A","name":"王一雪","zh":"喂，你在哪儿呢？","py":"Wèi, nǐ zài nǎr ne?","vi":"A lô, anh đang ở đâu thế?"},{"section":"Bài khoá 3","context":"Vương Nhất Tuyết đang gọi điện cho Lưu Minh ở trong phòng làm việc.","audio":"07-5.mp3","speaker":"B","name":"刘明","zh":"我在家里呢。","py":"Wǒ zài jiā li ne.","vi":"Anh đang ở nhà."},{"section":"Bài khoá 3","context":"Vương Nhất Tuyết đang gọi điện cho Lưu Minh ở trong phòng làm việc.","audio":"07-5.mp3","speaker":"A","name":"王一雪","zh":"我晚上六点半下班。","py":"Wǒ wǎnshang liù diǎn bàn xiàbān.","vi":"Em tan làm lúc 6 rưỡi tối."},{"section":"Bài khoá 3","context":"Vương Nhất Tuyết đang gọi điện cho Lưu Minh ở trong phòng làm việc.","audio":"07-5.mp3","speaker":"B","name":"刘明","zh":"我八点去医院上班。","py":"Wǒ bā diǎn qù yīyuàn shàngbān.","vi":"8 giờ anh đến bệnh viện làm việc."},{"section":"Bài khoá 3","context":"Vương Nhất Tuyết đang gọi điện cho Lưu Minh ở trong phòng làm việc.","audio":"07-5.mp3","speaker":"A","name":"王一雪","zh":"好的，你去店里买些菜吧。","py":"Hǎo de, nǐ qù diàn li mǎi xiē cài ba.","vi":"Vâng, anh ra cửa hàng mua ít thức ăn nhé."},{"section":"Bài khoá 3","context":"Vương Nhất Tuyết đang gọi điện cho Lưu Minh ở trong phòng làm việc.","audio":"07-5.mp3","speaker":"B","name":"刘明","zh":"好，我十分钟后去。","py":"Hǎo, wǒ shí fēnzhōng hòu qù.","vi":"Ừ, 10 phút nữa anh đi."}],"dialogQuestions":[],"grammar":{"g1":{"han":"点 / 分","py":"diǎn / fēn","title":"Cách diễn đạt thời gian (2)","explain":"(1) “点” và “分” được dùng để biểu thị thời điểm cụ thể, giờ chẵn thì dùng “点”; giờ không chẵn có lẻ là đơn vị phút thì dùng “分”. Trong một số trường hợp, “分” có thể được lược bỏ. Tuy nhiên, khi thời gian là “十分” thì không được lược bỏ “分”; khi số phút dưới mười, cần đọc thêm “零” trước số phút. (2) Các danh từ chỉ thời gian như “上午”, “中午”, “下午” và “晚上” có thể diễn đạt khoảng thời gian; phía sau chúng có thể thêm các từ chỉ thời điểm.","examples":[{"zh":"九点","py":"jiǔ diǎn","vi":"9:00 (9 giờ)","hl":"点"},{"zh":"十五点四十","py":"shíwǔ diǎn sìshí","vi":"15:40 (15 giờ 40)","hl":"点"},{"zh":"二十一点十分","py":"èrshíyī diǎn shí fēn","vi":"21:10 (21 giờ 10 phút)","hl":"十分"},{"zh":"二十二点零五","py":"èrshí\u0027èr diǎn líng wǔ","vi":"22:05 (22 giờ 05)","hl":"零五"},{"zh":"中午十二点","py":"zhōngwǔ shí\u0027èr diǎn","vi":"12 giờ trưa","hl":"中午"},{"zh":"下午两点半","py":"xiàwǔ liǎng diǎn bàn","vi":"2 giờ rưỡi chiều","hl":"两点半"},{"zh":"晚上九点十分","py":"wǎnshang jiǔ diǎn shí fēn","vi":"9 giờ 10 phút tối","hl":"晚上"}],"struct":"(上午/中午/下午/晚上) + Số + 点 + (Số + 分 / 半)","note":"Khi thời gian là “十分” (10 phút) không được lược bỏ “分”; khi số phút dưới 10 cần đọc thêm “零” (như 二十二点零五)."},"g2":{"han":"吧","py":"ba","title":"Trợ từ ngữ khí “吧” (1)","explain":"Trợ từ ngữ khí “吧” trong bài được đọc thanh nhẹ (ba), đứng cuối câu, biểu thị đề nghị, bàn bạc, khuyên nhủ hoặc yêu cầu.","examples":[{"zh":"我们下午三点见吧。","py":"Wǒmen xiàwǔ sān diǎn jiàn ba.","vi":"Chiều 3 giờ chúng ta gặp nhau nhé.","hl":"吧"},{"zh":"你去超市买吧。","py":"Nǐ qù chāoshì mǎi ba.","vi":"Bạn ra siêu thị mua đi nhé.","hl":"吧"},{"zh":"我们去西安饭店吃晚饭吧。","py":"Wǒmen qù Xī\u0027ān Fàndiàn chī wǎnfàn ba.","vi":"Chúng ta đến khách sạn Tây An ăn cơm tối nhé.","hl":"吧"}],"struct":"Câu trần thuật / Câu đề nghị + 吧。","note":"“吧” đọc thanh nhẹ, giúp lời đề nghị hoặc yêu cầu trở nên mềm mỏng, tự nhiên."},"g3":{"han":"状语","py":"zhuàngyǔ","title":"Vị trí của phó từ, từ ngữ chỉ thời gian khi làm trạng ngữ","explain":"Trong tiếng Trung Quốc, phó từ và từ ngữ chỉ thời gian khi làm trạng ngữ trong câu thường được đặt trước động từ hoặc tính từ.","examples":[{"zh":"我不想去。","py":"Wǒ bù xiǎng qù.","vi":"Tôi không muốn đi.","hl":"不"},{"zh":"妹妹很高兴。","py":"Mèimei hěn gāoxìng.","vi":"Em gái rất vui.","hl":"很"},{"zh":"她上午十点半上课。","py":"Tā shàngwǔ shí diǎn bàn shàngkè.","vi":"Cô ấy lên lớp lúc 10 giờ rưỡi sáng.","hl":"上午十点半"}],"struct":"Chủ ngữ + (Từ ngữ chỉ thời gian / Phó từ) + Động từ / Tính từ","note":"Khác với tiếng Việt thường đặt thời gian ở cuối câu, tiếng Trung đặt từ ngữ chỉ thời gian và phó từ trước động từ hoặc tính từ."},"g4":{"han":"呢","py":"ne","title":"Trợ từ ngữ khí “呢” (2)","explain":"Trợ từ ngữ khí “呢” trong bài đứng cuối câu để biểu thị một sự thực được xác nhận.","examples":[{"zh":"我明天下午两点还上课呢。","py":"Wǒ míngtiān xiàwǔ liǎng diǎn hái shàngkè ne.","vi":"2 giờ chiều mai tôi vẫn còn lên lớp đấy.","hl":"呢"},{"zh":"妹妹会做两个菜呢。","py":"Mèimei huì zuò liǎng gè cài ne.","vi":"Em gái biết nấu hai món ăn cơ đấy.","hl":"呢"},{"zh":"李文晚上还有事呢。","py":"Lǐ Wén wǎnshang hái yǒu shì ne.","vi":"Buổi tối Lý Văn vẫn còn có việc đấy.","hl":"呢"}],"struct":"……呢。","note":"Đứng cuối câu trần thuật để xác nhận, nhấn mạnh một sự thật."}},"grammarQuiz":[{"id":"hsk1_b7_q1","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"她星期天没有___。","opts":[{"t":"课","ok":true},{"t":"医院","ok":false},{"t":"现在","ok":false}],"exp":"“没有课” nghĩa là không có tiết học (Chủ nhật cô ấy không có tiết học).","ansZh":"她星期天没有课。"},{"id":"hsk1_b7_q2","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"我们中午___下课，下午两点见吧。","opts":[{"t":"十二点半","ok":true},{"t":"医院","ok":false},{"t":"课","ok":false}],"exp":"Trước động từ “下课” (tan học) cần từ ngữ chỉ thời điểm “十二点半” (12 giờ rưỡi).","ansZh":"我们中午十二点半下课，下午两点见吧。"},{"id":"hsk1_b7_q3","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"我们中午十二点半下课，下午两点___吧。","opts":[{"t":"见","ok":true},{"t":"现在","ok":false},{"t":"课","ok":false}],"exp":"“下午两点见吧” nghĩa là 2 giờ chiều gặp nhau nhé.","ansZh":"我们中午十二点半下课，下午两点见吧。"},{"id":"hsk1_b7_q4","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"白家月：对不起，我___有事呢，你去吧。","opts":[{"t":"现在","ok":true},{"t":"医院","ok":false},{"t":"见","ok":false}],"exp":"Từ chỉ thời gian “现在” làm trạng ngữ đứng trước động từ “有”.","ansZh":"对不起，我现在有事呢，你去吧。"},{"id":"hsk1_b7_q5","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"王一雪：你今天晚上几点去___上班？","opts":[{"t":"医院","ok":true},{"t":"课","ok":false},{"t":"十二点半","ok":false}],"exp":"Sau động từ “去” cần danh từ chỉ địa điểm “医院” (bệnh viện).","ansZh":"你今天晚上几点去医院上班？"}],"chars":["现","在","点","早","上","午","分","课","下","见","吧","电","影","看","事","呢","半","家","里","晚"],"rhyme":null,"notes":["Tiểu Ngữ giúp sức (p051): Khi “里” là phương vị từ, đứng sau các danh từ như “家” (nhà), “超市” (siêu thị), thì thường đọc thanh nhẹ “li”. Nhưng trong các từ ngữ như “里边”, thì “里” cần đọc thanh ba “lǐ”.","Trả lời câu hỏi (Bài khoá 3, p051): (1) 刘明晚上还去做什么？(Buổi tối Lưu Minh còn đi làm gì?) (2) 刘明十分钟后去做什么？(Mười phút nữa Lưu Minh sẽ đi làm gì?)","Tiểu Ngữ giúp sức (p053): Bạn đã biết viết con số rồi, bạn có muốn viết chữ Hán không? Hãy ghé thăm chuyên mục “Món quà của Tiểu Ngữ” nhé!","Món quà của Tiểu Ngữ (Video 7-1, p053): 学汉字 — Học chữ Hán."],"workbook":{"exercisesNote":"SBT Bài 7 (tr. 39–47): Đề luyện mô phỏng 模拟测练 (20 câu: Phần I Nghe 1–10, Phần II Đọc hiểu 11–20) và luyện viết chữ Hán.","answerKeyNote":"模拟测练 — Nghe (1–10): P1: 1.C 2.A 3.C | P2: 4.B 5.C | P3: 6.C 7.D 8.B | P4: 9.A 10.C.\n模拟测练 — Đọc (11–20): P1: 11.D 12.C 13.B | P2: 14.C 15.A 16.B | P3: 17.B 18.A | P4: 19.B 20.A.","transcriptNote":""}},"8":{"pages":"054–060","titleZh":"我爸爸也在医院工作","titlePy":"Wǒ bàba yě zài yīyuàn gōngzuò","titleVi":"Bố em cũng làm việc ở bệnh viện","goals":["Có thể nghe hiểu và miêu tả được thông tin về vị trí, địa điểm...","Nắm vững cách dùng của giới từ “在” để chỉ phương hướng, vị trí.","Nắm vững cách dùng của động từ năng nguyện “能”."],"words":[{"zh":"房间","py":"fángjiān","vi":"căn phòng","pos":"dt."},{"zh":"外","py":"wài","vi":"ngoài, bên ngoài","pos":"dt."},{"zh":"只","py":"zhī","vi":"con (chim, chó, hổ...)","pos":"lượng."},{"zh":"小","py":"xiǎo","vi":"nhỏ, bé","pos":"tt."},{"zh":"猫","py":"māo","vi":"mèo","pos":"dt."},{"zh":"没","py":"méi","vi":"không, chưa","pos":"phó."},{"zh":"看见","py":"kànjiàn","vi":"nhìn thấy, trông thấy","pos":"đgt."},{"zh":"桌子","py":"zhuōzi","vi":"bàn, cái bàn","pos":"dt."},{"zh":"下","py":"xià","vi":"dưới, bên dưới","pos":"dt."},{"zh":"漂亮","py":"piàoliang","vi":"đẹp, xinh đẹp","pos":"tt."},{"zh":"在","py":"zài","vi":"ở, tại","pos":"giới."},{"zh":"学校","py":"xuéxiào","vi":"trường học","pos":"dt."},{"zh":"书店","py":"shūdiàn","vi":"hiệu sách, nhà sách","pos":"dt."},{"zh":"前","py":"qián","vi":"phía trước","pos":"dt."},{"zh":"能","py":"néng","vi":"có thể","pos":"đtnn."},{"zh":"到","py":"dào","vi":"đến","pos":"đgt."},{"zh":"午饭","py":"wǔfàn","vi":"bữa trưa","pos":"dt."},{"zh":"饭","py":"fàn","vi":"cơm","pos":"dt."},{"zh":"大","py":"dà","vi":"lớn, to","pos":"tt."},{"zh":"病人","py":"bìngrén","vi":"bệnh nhân","pos":"dt."},{"zh":"多","py":"duō","vi":"nhiều","pos":"tt."},{"zh":"医生","py":"yīshēng","vi":"bác sĩ","pos":"dt."},{"zh":"工作","py":"gōngzuò","vi":"làm việc","pos":"đgt."},{"zh":"胡医生","py":"Hú yīshēng","vi":"bác sĩ Hồ","pos":"dt. riêng"}],"dialog":[{"section":"Bài khoá 1","context":"Bạch Gia Nguyệt và Trần Thiên Trung đến thăm nhà Vương Nhất Phi.","audio":"08-1.mp3","speaker":"A","name":"白家月","zh":"房间外有一只小猫。","py":"Fángjiān wài yǒu yì zhī xiǎo māo.","vi":"Bên ngoài phòng có một con mèo nhỏ."},{"section":"Bài khoá 1","context":"Bạch Gia Nguyệt và Trần Thiên Trung đến thăm nhà Vương Nhất Phi.","audio":"08-1.mp3","speaker":"B","name":"陈天中","zh":"我没看见，它在哪儿呢？","py":"Wǒ méi kànjiàn, tā zài nǎr ne?","vi":"Mình không nhìn thấy, nó ở đâu thế?"},{"section":"Bài khoá 1","context":"Bạch Gia Nguyệt và Trần Thiên Trung đến thăm nhà Vương Nhất Phi.","audio":"08-1.mp3","speaker":"A","name":"白家月","zh":"它在桌子下呢。","py":"Tā zài zhuōzi xià ne.","vi":"Nó ở dưới cái bàn kìa."},{"section":"Bài khoá 1","context":"Bạch Gia Nguyệt và Trần Thiên Trung đến thăm nhà Vương Nhất Phi.","audio":"08-1.mp3","speaker":"B","name":"陈天中","zh":"这只小猫真漂亮！","py":"Zhè zhī xiǎo māo zhēn piàoliang!","vi":"Con mèo nhỏ này xinh thật!"},{"section":"Bài khoá 2","context":"Bạch Gia Nguyệt gọi điện thoại cho Lý Văn ở trong lớp sau khi tan học.","audio":"08-3.mp3","speaker":"A","name":"白家月","zh":"我们在哪儿见呢？","py":"Wǒmen zài nǎr jiàn ne?","vi":"Chúng mình gặp nhau ở đâu nhỉ?"},{"section":"Bài khoá 2","context":"Bạch Gia Nguyệt gọi điện thoại cho Lý Văn ở trong lớp sau khi tan học.","audio":"08-3.mp3","speaker":"B","name":"李文","zh":"在学校书店前见吧。","py":"Zài xuéxiào shūdiàn qián jiàn ba.","vi":"Ở trước cửa hiệu sách của trường nhé."},{"section":"Bài khoá 2","context":"Bạch Gia Nguyệt gọi điện thoại cho Lý Văn ở trong lớp sau khi tan học.","audio":"08-3.mp3","speaker":"A","name":"白家月","zh":"好的。下午两点你能到吗？","py":"Hǎo de. Xiàwǔ liǎng diǎn nǐ néng dào ma?","vi":"Ừ. 2 giờ chiều bạn đến được không?"},{"section":"Bài khoá 2","context":"Bạch Gia Nguyệt gọi điện thoại cho Lý Văn ở trong lớp sau khi tan học.","audio":"08-3.mp3","speaker":"B","name":"李文","zh":"我能到。我在学校吃午饭。","py":"Wǒ néng dào. Wǒ zài xuéxiào chī wǔfàn.","vi":"Mình đến được. Mình ăn trưa ở trường."},{"section":"Bài khoá 3","context":"Lưu Minh đang trò chuyện với đồng nghiệp của anh là bác sĩ Hồ ở trong bệnh viện.","audio":"08-5.mp3","speaker":"A","name":"刘明","zh":"小胡，还没吃饭呢？","py":"Xiǎo Hú, hái méi chī fàn ne?","vi":"Tiểu Hồ, em vẫn chưa ăn cơm à?"},{"section":"Bài khoá 3","context":"Lưu Minh đang trò chuyện với đồng nghiệp của anh là bác sĩ Hồ ở trong bệnh viện.","audio":"08-5.mp3","speaker":"B","name":"胡医生","zh":"没吃呢。","py":"Méi chī ne.","vi":"Em chưa ăn ạ."},{"section":"Bài khoá 3","context":"Lưu Minh đang trò chuyện với đồng nghiệp của anh là bác sĩ Hồ ở trong bệnh viện.","audio":"08-5.mp3","speaker":"A","name":"刘明","zh":"大医院病人多，医生非常忙。","py":"Dà yīyuàn bìngrén duō, yīshēng fēicháng máng.","vi":"Ở bệnh viện lớn, bệnh nhân rất đông, bác sĩ cực kỳ bận."},{"section":"Bài khoá 3","context":"Lưu Minh đang trò chuyện với đồng nghiệp của anh là bác sĩ Hồ ở trong bệnh viện.","audio":"08-5.mp3","speaker":"B","name":"胡医生","zh":"是的。我爸爸也在医院工作，他也非常忙。","py":"Shì de. Wǒ bàba yě zài yīyuàn gōngzuò, tā yě fēicháng máng.","vi":"Vâng. Bố em cũng làm việc ở bệnh viện, ông ấy cũng bận lắm."},{"section":"Bài khoá 3","context":"Lưu Minh đang trò chuyện với đồng nghiệp của anh là bác sĩ Hồ ở trong bệnh viện.","audio":"08-5.mp3","speaker":"A","name":"刘明","zh":"你家有两个医生？","py":"Nǐ jiā yǒu liǎng gè yīshēng?","vi":"Nhà em có hai bác sĩ cơ à?"},{"section":"Bài khoá 3","context":"Lưu Minh đang trò chuyện với đồng nghiệp của anh là bác sĩ Hồ ở trong bệnh viện.","audio":"08-5.mp3","speaker":"B","name":"胡医生","zh":"对。","py":"Duì.","vi":"Vâng."}],"dialogQuestions":[],"grammar":{"g1":{"han":"方位词","py":"fāngwèicí","title":"Phương vị từ","explain":"Các phương vị từ dùng để diễn đạt phương hướng và vị trí được giới thiệu trong quyển sách này gồm có: 上, 下, 里, 外, 前, 后 và 外边.","examples":[{"zh":"房间里有一只小猫。","py":"Fángjiān li yǒu yì zhī xiǎo māo.","vi":"Trong phòng có một con mèo nhỏ.","hl":"里"},{"zh":"我们去书店外吧。","py":"Wǒmen qù shūdiàn wài ba.","vi":"Chúng ta ra ngoài hiệu sách đi nhé.","hl":"外"},{"zh":"小雪的手机在桌子上呢。","py":"Xiǎoxuě de shǒujī zài zhuōzi shang ne.","vi":"Điện thoại của Tiểu Tuyết ở trên bàn kìa.","hl":"上"}],"struct":"Danh từ + Phương vị từ (上 / 下 / 里 / 外 / 前 / 后 / 外边)","note":"Phương vị từ đứng sau danh từ để tạo thành cụm danh từ chỉ vị trí, nơi chốn."},"g2":{"han":"在","py":"zài","title":"Giới từ “在”","explain":"Cấu trúc được kết hợp bởi giới từ “在” và từ ngữ chỉ vị trí, nơi chốn thường đứng trước động từ, biểu thị vị trí, nơi chốn diễn ra hành động.","examples":[{"zh":"我在学校吃午饭。","py":"Wǒ zài xuéxiào chī wǔfàn.","vi":"Tôi ăn trưa ở trường.","hl":"在学校"},{"zh":"他爸爸在医院工作。","py":"Tā bàba zài yīyuàn gōngzuò.","vi":"Bố anh ấy làm việc ở bệnh viện.","hl":"在医院"},{"zh":"你在哪儿买菜？","py":"Nǐ zài nǎr mǎi cài?","vi":"Bạn mua thức ăn ở đâu?","hl":"在哪儿"}],"struct":"Chủ ngữ + 在 + Vị trí / Nơi chốn + Động từ (+ Tân ngữ)","note":"Cụm giới từ “在 + nơi chốn” đứng trước động từ làm trạng ngữ chỉ địa điểm."},"g3":{"han":"能","py":"néng","title":"Động từ năng nguyện “能”","explain":"Động từ năng nguyện “能” đứng trước động từ, biểu thị có năng lực, điều kiện hoặc khả năng làm một việc gì đó.","examples":[{"zh":"下午两点你能到吗？","py":"Xiàwǔ liǎng diǎn nǐ néng dào ma?","vi":"2 giờ chiều bạn có thể đến không?","hl":"能"},{"zh":"爸爸能去。","py":"Bàba néng qù.","vi":"Bố có thể đi.","hl":"能"},{"zh":"我不能去学校吃午饭。","py":"Wǒ bù néng qù xuéxiào chī wǔfàn.","vi":"Tôi không thể đến trường ăn trưa.","hl":"不能"}],"struct":"Chủ ngữ + (不)能 + Động từ (+ Tân ngữ)","note":"Dạng phủ định của “能” là “不能” (không thể)."}},"grammarQuiz":[{"id":"hsk1_b8_q1","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"胡医生的爸爸___医院工作。","opts":[{"t":"在","ok":true},{"t":"能","ok":false},{"t":"哪儿","ok":false}],"exp":"Giới từ “在” kết hợp với nơi chốn “医院” đứng trước động từ “工作”.","ansZh":"胡医生的爸爸在医院工作。"},{"id":"hsk1_b8_q2","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"我下午两点___到学校。","opts":[{"t":"能","ok":true},{"t":"在","ok":false},{"t":"书店","ok":false}],"exp":"Động từ năng nguyện “能” đứng trước động từ “到” biểu thị khả năng đến được.","ansZh":"我下午两点能到学校。"},{"id":"hsk1_b8_q3","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"陈天中：小猫在___呢？","opts":[{"t":"哪儿","ok":true},{"t":"桌子","ok":false},{"t":"能","ok":false}],"exp":"Câu hỏi vị trí dùng đại từ nghi vấn “哪儿” (ở đâu).","ansZh":"小猫在哪儿呢？"},{"id":"hsk1_b8_q4","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"白家月：小猫在___下。","opts":[{"t":"桌子","ok":true},{"t":"哪儿","ok":false},{"t":"在","ok":false}],"exp":"“桌子下” nghĩa là dưới cái bàn (danh từ + phương vị từ 下).","ansZh":"小猫在桌子下。"},{"id":"hsk1_b8_q5","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"白家月：我们去___，你去吗？","opts":[{"t":"书店","ok":true},{"t":"能","ok":false},{"t":"在","ok":false}],"exp":"Sau động từ “去” cần danh từ chỉ địa điểm “书店” (hiệu sách).","ansZh":"我们去书店，你去吗？"}],"chars":["房","间","外","只","小","猫","没","桌","漂","亮","学","校","书","前","能","到","饭","病","医","工"],"rhyme":null,"notes":["Tiểu Ngữ giúp sức (p055): Lượng từ có thể kết hợp trực tiếp với đại từ chỉ thị (ví dụ: 这只小猫).","Tiểu Ngữ giúp sức (p059): “小 + họ” là cách xưng hô thân mật với những người ít tuổi hơn mình (ví dụ: 小胡).","Trả lời câu hỏi (Bài khoá 3, p059): (1) 胡医生的爸爸在哪儿工作？(Bố của bác sĩ Hồ làm việc ở đâu?) (2) 胡医生的爸爸工作忙吗？(Bố của bác sĩ Hồ làm việc có bận không?)"],"workbook":{"exercisesNote":"SBT Bài 8 (tr. 48–56): Tiểu Ngữ giảng đường — Ngữ âm (1. Phân biệt âm tiết; 2. Chọn từ song âm tiết không phải điệp âm/lặp) + Đề luyện mô phỏng 模拟测练 (20 câu: Nghe 1–10, Đọc hiểu 11–20).","answerKeyNote":"语音 1 (Phân biệt âm tiết): (1) nián | (2) rěn | (3) tiē | (4) chǎn | (5) lüè | (6) hún | (7) bīng | (8) kǒng.\n语音 2 (Không phải điệp âm): (1) B tīnglì | (2) C gè kè | (3) B kànjiàn | (4) A méiyǒu.\n模拟测练 — Nghe (1–10): P1: 1.C 2.B 3.A | P2: 4.B 5.A | P3: 6.D 7.C 8.B | P4: 9.C 10.B.\n模拟测练 — Đọc (11–20): P1: 11.B 12.D 13.C | P2: 14.C 15.B 16.A | P3: 17.B 18.A | P4: 19.A 20.A.","transcriptNote":""}},"9":{"pages":"061–069","titleZh":"我明天上午在学校学习","titlePy":"Wǒ míngtiān shàngwǔ zài xuéxiào xuéxí","titleVi":"Sáng mai mình học ở trường","goals":["Có thể nghe hiểu và sử dụng được “有/是” để diễn đạt sự tồn tại.","Nắm vững trật tự của từ ngữ chỉ thời gian và từ ngữ chỉ nơi chốn khi chúng cùng xuất hiện.","Nắm vững cách dùng của từ “第”.","Hiểu về các hoạt động giải trí của người Trung Quốc hiện đại."],"words":[{"zh":"前边","py":"qiánbian","vi":"phía trước","pos":"dt."},{"zh":"边","py":"bian/biān","vi":"phía, bên","pos":"htố./dt."},{"zh":"家","py":"jiā","vi":"cái, chiếc (dùng cho cửa hàng, cơ quan, doanh nghiệp)","pos":"lượng."},{"zh":"那个","py":"nàge","vi":"đó, cái đó","pos":"đt."},{"zh":"外边","py":"wàibian","vi":"phía ngoài, bên ngoài","pos":"dt."},{"zh":"椅子","py":"yǐzi","vi":"ghế","pos":"dt."},{"zh":"上","py":"shang/shàng","vi":"trên, trước (dùng sau danh từ, chỉ vị trí)","pos":"dt."},{"zh":"本","py":"běn","vi":"quyển, cuốn","pos":"lượng."},{"zh":"书","py":"shū","vi":"sách","pos":"dt."},{"zh":"那","py":"nà","vi":"kia, đó","pos":"đt."},{"zh":"第","py":"dì","vi":"thứ (dùng để biểu thị số thứ tự)","pos":"ttố."},{"zh":"学习","py":"xuéxí","vi":"học, học tập","pos":"đgt."},{"zh":"做","py":"zuò","vi":"làm","pos":"đgt."},{"zh":"白天","py":"báitiān","vi":"ban ngày","pos":"dt."},{"zh":"读书","py":"dúshū","vi":"đọc sách, xem sách","pos":"đgt."},{"zh":"和","py":"hé","vi":"với, cùng","pos":"giới."},{"zh":"朋友","py":"péngyou","vi":"bạn, bạn bè","pos":"dt."},{"zh":"唱","py":"chàng","vi":"hát","pos":"đgt."},{"zh":"歌","py":"gē","vi":"bài hát","pos":"dt."},{"zh":"好听","py":"hǎotīng","vi":"hay, nghe hay","pos":"tt."},{"zh":"电视","py":"diànshì","vi":"ti vi, vô tuyến","pos":"dt."},{"zh":"狗","py":"gǒu","vi":"chó","pos":"dt."},{"zh":"玩","py":"wán","vi":"chơi","pos":"đgt."}],"dialog":[{"section":"Bài khoá 1","context":"Lý Văn và Bạch Gia Nguyệt đang trò chuyện ở trong khuôn viên trường.","audio":"09-1.mp3","speaker":"A","name":"李文","zh":"学校前边有一家电影院。","py":"Xuéxiào qiánbian yǒu yì jiā diànyǐngyuàn.","vi":"Phía trước trường học có một rạp chiếu phim."},{"section":"Bài khoá 1","context":"Lý Văn và Bạch Gia Nguyệt đang trò chuyện ở trong khuôn viên trường.","audio":"09-1.mp3","speaker":"B","name":"白家月","zh":"对。我们晚上去那个电影院看电影吧。","py":"Duì. Wǒmen wǎnshang qù nàge diànyǐngyuàn kàn diànyǐng ba.","vi":"Đúng vậy. Tối chúng mình đến đó xem phim nhé."},{"section":"Bài khoá 1","context":"Lý Văn và Bạch Gia Nguyệt đang trò chuyện ở trong khuôn viên trường.","audio":"09-1.mp3","speaker":"A","name":"李文","zh":"好！我们七点在电影院外边见，好吗？","py":"Hǎo! Wǒmen qī diǎn zài diànyǐngyuàn wàibian jiàn, hǎo ma?","vi":"Được, chúng mình gặp nhau lúc 7 giờ ở bên ngoài rạp chiếu phim, được không?"},{"section":"Bài khoá 1","context":"Lý Văn và Bạch Gia Nguyệt đang trò chuyện ở trong khuôn viên trường.","audio":"09-1.mp3","speaker":"B","name":"白家月","zh":"好的，晚上七点见！","py":"Hǎo de, wǎnshang qī diǎn jiàn!","vi":"Ừ, tối 7 giờ gặp nhau nhé."},{"section":"Bài khoá 2","context":"Bạch Gia Nguyệt đang trò chuyện với Trần Thiên Trung ở trong lớp sau khi tan học.","audio":"09-3.mp3","speaker":"A","name":"白家月","zh":"椅子上有一本中文书，那是谁的书？","py":"Yǐzi shang yǒu yì běn Zhōngwén shū, nà shì shéi de shū?","vi":"Có một quyển sách tiếng Trung Quốc ở trên ghế. Đó là sách của ai vậy?"},{"section":"Bài khoá 2","context":"Bạch Gia Nguyệt đang trò chuyện với Trần Thiên Trung ở trong lớp sau khi tan học.","audio":"09-3.mp3","speaker":"B","name":"陈天中","zh":"是我的书，谢谢。这是我的第二本中文书。","py":"Shì wǒ de shū, xièxie. Zhè shì wǒ de dì-èr běn Zhōngwén shū.","vi":"Là sách của mình, cảm ơn bạn. Đây là quyển sách tiếng Trung Quốc thứ hai của mình."},{"section":"Bài khoá 2","context":"Bạch Gia Nguyệt đang trò chuyện với Trần Thiên Trung ở trong lớp sau khi tan học.","audio":"09-3.mp3","speaker":"A","name":"白家月","zh":"不客气。你明天上午在哪儿？","py":"Bú kèqi. Nǐ míngtiān shàngwǔ zài nǎr?","vi":"Đừng khách sáo nhé. Sáng mai bạn ở đâu?"},{"section":"Bài khoá 2","context":"Bạch Gia Nguyệt đang trò chuyện với Trần Thiên Trung ở trong lớp sau khi tan học.","audio":"09-3.mp3","speaker":"B","name":"陈天中","zh":"我明天上午在学校学习。","py":"Wǒ míngtiān shàngwǔ zài xuéxiào xuéxí.","vi":"Sáng mai mình học ở trường."},{"section":"Bài khoá 3","context":"Vương Nhất Tuyết và Dương Đồng Lạc đang trò chuyện về cuộc sống cuối tuần của họ trong lúc nghỉ ngơi ở văn phòng.","audio":"09-5.mp3","speaker":"A","name":"王一雪","zh":"明天星期六，你做什么？","py":"Míngtiān Xīngqīliù, nǐ zuò shénme?","vi":"Mai là thứ Bảy rồi, em định làm gì?"},{"section":"Bài khoá 3","context":"Vương Nhất Tuyết và Dương Đồng Lạc đang trò chuyện về cuộc sống cuối tuần của họ trong lúc nghỉ ngơi ở văn phòng.","audio":"09-5.mp3","speaker":"B","name":"杨同乐","zh":"我白天在家里读书，晚上和朋友们去外边唱歌。","py":"Wǒ báitiān zài jiā li dúshū, wǎnshang hé péngyoumen qù wàibian chàng gē.","vi":"Ban ngày em sẽ ở nhà đọc sách, buổi tối sẽ ra ngoài hát cùng bạn bè."},{"section":"Bài khoá 3","context":"Vương Nhất Tuyết và Dương Đồng Lạc đang trò chuyện về cuộc sống cuối tuần của họ trong lúc nghỉ ngơi ở văn phòng.","audio":"09-5.mp3","speaker":"A","name":"王一雪","zh":"你唱歌很好听。","py":"Nǐ chàng gē hěn hǎotīng.","vi":"Em hát rất hay."},{"section":"Bài khoá 3","context":"Vương Nhất Tuyết và Dương Đồng Lạc đang trò chuyện về cuộc sống cuối tuần của họ trong lúc nghỉ ngơi ở văn phòng.","audio":"09-5.mp3","speaker":"B","name":"杨同乐","zh":"谢谢！您星期六做什么？","py":"Xièxie! Nín Xīngqīliù zuò shénme?","vi":"Cảm ơn chị! Thứ Bảy chị làm gì?"},{"section":"Bài khoá 3","context":"Vương Nhất Tuyết và Dương Đồng Lạc đang trò chuyện về cuộc sống cuối tuần của họ trong lúc nghỉ ngơi ở văn phòng.","audio":"09-5.mp3","speaker":"A","name":"王一雪","zh":"我在家里做饭、看电视，和孩子们、小狗玩。","py":"Wǒ zài jiā li zuò fàn, kàn diànshì, hé háizimen, xiǎo gǒu wán.","vi":"Chị ở nhà nấu ăn, xem ti vi, chơi với các con và con chó nhỏ của chị."},{"section":"Bài khoá 3","context":"Vương Nhất Tuyết và Dương Đồng Lạc đang trò chuyện về cuộc sống cuối tuần của họ trong lúc nghỉ ngơi ở văn phòng.","audio":"09-5.mp3","speaker":"B","name":"杨同乐","zh":"我也有一只小狗。","py":"Wǒ yě yǒu yì zhī xiǎo gǒu.","vi":"Em cũng có một con chó nhỏ đấy."}],"dialogQuestions":[],"grammar":{"g1":{"han":"有 / 是","py":"yǒu / shì","title":"Câu tồn hiện (1)","explain":"Câu tồn hiện là câu biểu thị sự tồn tại của người hoặc sự vật ở một nơi hoặc vị trí nào đó. Câu tồn hiện thường được nhận biết khi có từ “有” hoặc “是”. Khi phủ định, không thêm số lượng từ vào trước tân ngữ.","examples":[{"zh":"学校前边有一家电影院。","py":"Xuéxiào qiánbian yǒu yì jiā diànyǐngyuàn.","vi":"Phía trước trường học có một rạp chiếu phim.","hl":"有"},{"zh":"电影院前边是一家超市。","py":"Diànyǐngyuàn qiánbian shì yì jiā chāoshì.","vi":"Phía trước rạp chiếu phim là một siêu thị.","hl":"是"},{"zh":"电影院前边不是超市。","py":"Diànyǐngyuàn qiánbian bú shì chāoshì.","vi":"Phía trước rạp chiếu phim không phải là siêu thị.","hl":"不是"},{"zh":"桌子上没有小猫。","py":"Zhuōzi shang méiyǒu xiǎo māo.","vi":"Trên bàn không có mèo nhỏ.","hl":"没有"}],"struct":"Nơi chốn + 有 / 是 + Người / Vật | Phủ định: Nơi chốn + 没有 / 不是 + Danh từ","note":"Khi phủ định câu tồn hiện, không thêm số lượng từ vào trước tân ngữ (ví dụ: 桌子上没有小猫)."},"g2":{"han":"时间+处所","py":"shíjiān + chùsuǒ","title":"Trật tự của từ ngữ chỉ thời gian và từ ngữ chỉ nơi chốn khi cùng làm trạng ngữ","explain":"Khi từ ngữ chỉ thời gian và từ ngữ chỉ nơi chốn cùng làm trạng ngữ thì từ ngữ chỉ thời gian đứng trước từ ngữ chỉ nơi chốn.","examples":[{"zh":"我们七点在电影院外边见。","py":"Wǒmen qī diǎn zài diànyǐngyuàn wàibian jiàn.","vi":"Chúng ta gặp nhau lúc 7 giờ ở bên ngoài rạp chiếu phim.","hl":"七点在电影院外边"},{"zh":"安妮下午在家里学中文。","py":"Ānnī xiàwǔ zài jiā li xué Zhōngwén.","vi":"Buổi chiều Annie học tiếng Trung ở nhà.","hl":"下午在家里"},{"zh":"陈天中明天中午在学校吃午饭。","py":"Chén Tiānzhōng míngtiān zhōngwǔ zài xuéxiào chī wǔfàn.","vi":"Trưa mai Trần Thiên Trung ăn trưa ở trường.","hl":"明天中午在学校"}],"struct":"Chủ ngữ + Từ ngữ chỉ thời gian + 在 + Nơi chốn + Động từ (+ Tân ngữ)","note":"Trật tự luôn là: Thời gian → Nơi chốn → Hành động."},"g3":{"han":"第","py":"dì","title":"“第” dùng để biểu thị số thứ tự","explain":"“第” đặt trước số từ (số nguyên) để biểu thị số thứ tự.","examples":[{"zh":"第一，第二，第三","py":"dì-yī, dì-èr, dì-sān","vi":"thứ nhất, thứ hai, thứ ba","hl":"第"},{"zh":"第一个，第二个，第一本","py":"dì-yī gè, dì-èr gè, dì-yī běn","vi":"cái thứ nhất, cái thứ hai, quyển thứ nhất","hl":"第"},{"zh":"第一个学生，第一本书","py":"dì-yī gè xuésheng, dì-yī běn shū","vi":"học sinh thứ nhất, quyển sách thứ nhất","hl":"第"}],"struct":"(1) 第 + Số từ; (2) 第 + Số từ + Lượng từ + (Danh từ)","note":"Với số thứ tự thứ hai dùng “第二”, không dùng “第两”."}},"grammarQuiz":[{"id":"hsk1_b9_q1","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"___上有一只小猫，房间外是一只小狗。","opts":[{"t":"椅子","ok":true},{"t":"是","ok":false},{"t":"好听","ok":false}],"exp":"“椅子上” (trên ghế) đứng đầu câu tồn hiện để chỉ vị trí.","ansZh":"椅子上有一只小猫，房间外是一只小狗。"},{"id":"hsk1_b9_q2","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"椅子上有一只小猫，房间外___一只小狗。","opts":[{"t":"是","ok":true},{"t":"椅子","ok":false},{"t":"在学校","ok":false}],"exp":"Dùng “是” trong câu tồn hiện để biểu thị bên ngoài phòng là một con chó nhỏ.","ansZh":"椅子上有一只小猫，房间外是一只小狗。"},{"id":"hsk1_b9_q3","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"她___在家里学习。","opts":[{"t":"今天上午","ok":true},{"t":"在学校","ok":false},{"t":"好听","ok":false}],"exp":"Từ ngữ chỉ thời gian “今天上午” đứng trước cụm nơi chốn “在家里”.","ansZh":"她今天上午在家里学习。"},{"id":"hsk1_b9_q4","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"王一雪：你唱歌很___。","opts":[{"t":"好听","ok":true},{"t":"是","ok":false},{"t":"椅子","ok":false}],"exp":"Tính từ “好听” (nghe hay) đứng sau phó từ “很”.","ansZh":"你唱歌很好听。"},{"id":"hsk1_b9_q5","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"安妮：我下午还___上课。","opts":[{"t":"在学校","ok":true},{"t":"今天上午","ok":false},{"t":"好听","ok":false}],"exp":"Cụm nơi chốn “在学校” đứng sau thời gian “下午” và trước động từ “上课”.","ansZh":"我下午还在学校上课。"}],"chars":["边","那","椅","本","第","习","做","白","天","读","和","朋","友","唱","歌","听","视","狗","玩","前"],"rhyme":null,"notes":["Tiểu Ngữ giúp sức (p062): “前边” có thể thêm âm uốn lưỡi, đọc thành “前边儿”. “边” là hậu tố, đọc thanh nhẹ. Khi “边” là danh từ thì đọc “biān”.","Tiểu Ngữ giúp sức (p062): Trong văn nói, “那个” cũng có thể đọc thành “nèige”.","Tiểu Ngữ giúp sức (p064): Phương vị từ “上” đứng sau danh từ, ví dụ “椅子上”, “书上” đọc thanh nhẹ. Khi dùng để biểu thị vị trí cao hoặc chỉ thứ tự, thời gian ở trước đó, ví dụ “上方”, “上半年” thì “上” đọc thanh 4.","Trả lời câu hỏi (Bài khoá 2, p064): (1) 椅子上的书是谁的？(Quyển sách ở trên ghế là của ai?) (2) 陈天中明天上午在哪儿学习？(Sáng mai, Trần Thiên Trung học ở đâu?)","Tiểu Ngữ giúp sức (p066): Trong văn nói, “玩” thường thêm âm uốn lưỡi, đọc là “玩儿”.","Trả lời câu hỏi (Bài khoá 3, p066): (1) 杨同乐星期六做什么？(Thứ Bảy Dương Đồng Lạc sẽ làm gì?) (2) 王一雪星期六做什么？(Thứ Bảy Vương Nhất Tuyết sẽ làm gì?)"],"workbook":{"exercisesNote":"SBT Bài 9 (tr. 57–65): Tiểu Ngữ giảng đường — Ngữ âm (1. Đánh dấu thanh điệu; 2. Phân biệt thanh điệu khác biệt) + Đề luyện mô phỏng 模拟测练 (20 câu: Nghe 1–10, Đọc hiểu 11–20).","answerKeyNote":"语音 1 (Đánh dấu thanh điệu): (1) hǎo | (2) xiè | (3) nín | (4) zhōng | (5) tóngxué | (6) dàjiā | (7) zàijiàn | (8) rènshi.\n语音 2 (Phân biệt thanh điệu): (1) B xiǎo | (2) A chàng | (3) C xué | (4) C dì.\n模拟测练 — Nghe (1–10): P1: 1.B 2.C 3.A | P2: 4.B 5.C | P3: 6.D 7.C 8.B | P4: 9.A 10.B.\n模拟测练 — Đọc (11–20): P1: 11.D 12.C 13.B | P2: 14.C 15.A 16.B | P3: 17.B 18.A | P4: 19.A 20.B.","transcriptNote":""}},"10":{"pages":"70–77","titleZh":"这儿的苹果真便宜！","titlePy":"Zhèr de píngguǒ zhēn piányi!","titleVi":"Táo ở đây rẻ thật!","goals":["Có thể nghe hiểu, đọc hiểu và trao đổi đơn giản về giá cả hàng hoá.","Nắm vững cách sử dụng của câu vị ngữ tính từ.","Nắm vững cách dùng của đại từ nghi vấn “怎么样”.","Nhận biết được đồng Nhân dân tệ."],"words":[{"zh":"杯子","py":"bēizi","vi":"cốc, ly","pos":"dt."},{"zh":"售货员","py":"shòuhuòyuán","vi":"nhân viên bán hàng","pos":"dt."},{"zh":"这边","py":"zhèbiān","vi":"bên này, phía này","pos":"đt."},{"zh":"钱","py":"qián","vi":"tiền","pos":"dt."},{"zh":"这些","py":"zhèxiē","vi":"những cái này","pos":"đt."},{"zh":"块","py":"kuài","vi":"đồng (đơn vị tiền tệ)","pos":"lượng."},{"zh":"那些","py":"nàxiē","vi":"những cái kia","pos":"đt."},{"zh":"这儿","py":"zhèr","vi":"ở đây, chỗ này","pos":"đt."},{"zh":"水果","py":"shuǐguǒ","vi":"hoa quả, trái cây","pos":"dt."},{"zh":"少","py":"shǎo","vi":"ít","pos":"tt."},{"zh":"斤","py":"jīn","vi":"cân (đơn vị đo lường của Trung Quốc, 1 cân bằng 0,5 kg)","pos":"lượng."},{"zh":"苹果","py":"píngguǒ","vi":"táo","pos":"dt."},{"zh":"便宜","py":"piányi","vi":"rẻ","pos":"tt."},{"zh":"商店","py":"shāngdiàn","vi":"cửa hàng","pos":"dt."},{"zh":"衣服","py":"yīfu","vi":"quần áo","pos":"dt."},{"zh":"件","py":"jiàn","vi":"chiếc, cái (dùng cho quần áo)","pos":"lượng."},{"zh":"元","py":"yuán","vi":"đồng (nhân dân tệ)","pos":"lượng."},{"zh":"怎么样","py":"zěnmeyàng","vi":"thế nào, như thế nào","pos":"đt."},{"zh":"贵","py":"guì","vi":"đắt","pos":"tt."},{"zh":"穿","py":"chuān","vi":"mặc","pos":"đgt."},{"zh":"女","py":"nǚ","vi":"nữ, con gái","pos":"tt."},{"zh":"男","py":"nán","vi":"nam, con trai","pos":"tt."},{"zh":"那儿","py":"nàr","vi":"ở kia, chỗ đó","pos":"đt."}],"dialog":[{"section":"Bài khoá 1","context":"在一家小店，王一雪在买杯子。 Vương Nhất Tuyết mua cốc ở một cửa hàng nhỏ.","audio":"10-1.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"请问，有杯子吗？","py":"Qǐngwèn, yǒu bēizi ma?","vi":"Xin hỏi, ở đây có bán cốc không?"},{"section":"Bài khoá 1","context":"在一家小店，王一雪在买杯子。 Vương Nhất Tuyết mua cốc ở một cửa hàng nhỏ.","audio":"10-1.mp3","speaker":"售货员","name":"Nhân viên bán hàng","zh":"有，杯子在这边。","py":"Yǒu, bēizi zài zhèbiān.","vi":"Có ạ, cốc ở phía bên này."},{"section":"Bài khoá 1","context":"在一家小店，王一雪在买杯子。 Vương Nhất Tuyết mua cốc ở một cửa hàng nhỏ.","audio":"10-1.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"多少钱一个？","py":"Duōshao qián yí gè?","vi":"Bao nhiêu tiền một chiếc vậy?"},{"section":"Bài khoá 1","context":"在一家小店，王一雪在买杯子。 Vương Nhất Tuyết mua cốc ở một cửa hàng nhỏ.","audio":"10-1.mp3","speaker":"售货员","name":"Nhân viên bán hàng","zh":"这些五块钱一个，那些十块钱一个。","py":"Zhèxiē wǔ kuài qián yí gè, nàxiē shí kuài qián yí gè.","vi":"Những chiếc này 5 đồng một chiếc, còn những chiếc kia 10 đồng một chiếc."},{"section":"Bài khoá 1","context":"在一家小店，王一雪在买杯子。 Vương Nhất Tuyết mua cốc ở một cửa hàng nhỏ.","audio":"10-1.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"我买这个吧。","py":"Wǒ mǎi zhège ba.","vi":"Tôi lấy chiếc này."},{"section":"Bài khoá 2","context":"在菜市场，王一雪在买水果。 Vương Nhất Tuyết đang mua hoa quả ở chợ.","audio":"10-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"这儿的水果真不少！","py":"Zhèr de shuǐguǒ zhēn bù shǎo!","vi":"Hoa quả ở đây nhiều nhỉ!"},{"section":"Bài khoá 2","context":"在菜市场，王一雪在买水果。 Vương Nhất Tuyết đang mua hoa quả ở chợ.","audio":"10-3.mp3","speaker":"售货员","name":"Người bán hàng","zh":"您想买什么？","py":"Nín xiǎng mǎi shénme?","vi":"Chị muốn mua gì?"},{"section":"Bài khoá 2","context":"在菜市场，王一雪在买水果。 Vương Nhất Tuyết đang mua hoa quả ở chợ.","audio":"10-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"我想买两斤苹果。","py":"Wǒ xiǎng mǎi liǎng jīn píngguǒ.","vi":"Tôi muốn mua hai cân táo."},{"section":"Bài khoá 2","context":"在菜市场，王一雪在买水果。 Vương Nhất Tuyết đang mua hoa quả ở chợ.","audio":"10-3.mp3","speaker":"售货员","name":"Người bán hàng","zh":"苹果三块五一斤。这些七块二，七块钱吧。","py":"Píngguǒ sān kuài wǔ yì jīn. Zhèxiē qī kuài èr, qī kuài qián ba.","vi":"Táo 3 đồng rưỡi một cân. Chỗ này 7,2 đồng, lấy chị 7 đồng nhé."},{"section":"Bài khoá 2","context":"在菜市场，王一雪在买水果。 Vương Nhất Tuyết đang mua hoa quả ở chợ.","audio":"10-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"好的，这儿的苹果真便宜！","py":"Hǎo de, zhèr de píngguǒ zhēn piányi!","vi":"Vâng, táo ở đây rẻ thật!"},{"section":"Bài khoá 3","context":"在商场里，刘明和王一雪在给孩子买衣服。 Lưu Minh và Vương Nhất Tuyết đang mua quần áo cho các con trong trung tâm thương mại.","audio":"10-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"这家商店衣服真多！这件一百元，怎么样？","py":"Zhè jiā shāngdiàn yīfu zhēn duō! Zhè jiàn yìbǎi yuán, zěnmeyàng?","vi":"Cửa hàng này nhiều quần áo thật đấy! Chiếc này 100 đồng, anh thấy thế nào?"},{"section":"Bài khoá 3","context":"在商场里，刘明和王一雪在给孩子买衣服。 Lưu Minh và Vương Nhất Tuyết đang mua quần áo cho các con trong trung tâm thương mại.","audio":"10-5.mp3","speaker":"刘明","name":"Lưu Minh","zh":"好看，也不贵。","py":"Hǎokàn, yě bú guì.","vi":"Đẹp đấy, mà cũng không đắt."},{"section":"Bài khoá 3","context":"在商场里，刘明和王一雪在给孩子买衣服。 Lưu Minh và Vương Nhất Tuyết đang mua quần áo cho các con trong trung tâm thương mại.","audio":"10-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"小雪能穿，买一件吧。","py":"Xiǎoxuě néng chuān, mǎi yí jiàn ba.","vi":"Tiểu Tuyết mặc được đấy, mua một chiếc nhé."},{"section":"Bài khoá 3","context":"在商场里，刘明和王一雪在给孩子买衣服。 Lưu Minh và Vương Nhất Tuyết đang mua quần áo cho các con trong trung tâm thương mại.","audio":"10-5.mp3","speaker":"刘明","name":"Lưu Minh","zh":"好的。小明能穿吗？","py":"Hǎo de. Xiǎomíng néng chuān ma?","vi":"Ừ. Tiểu Minh có mặc được không?"},{"section":"Bài khoá 3","context":"在商场里，刘明和王一雪在给孩子买衣服。 Lưu Minh và Vương Nhất Tuyết đang mua quần áo cho các con trong trung tâm thương mại.","audio":"10-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"不能。这些是女孩子穿的衣服，男孩子的衣服在那儿。","py":"Bù néng. Zhèxiē shì nǚ háizi chuān de yīfu, nán háizi de yīfu zài nàr.","vi":"Không được đâu. Những cái này là quần áo dành cho bé gái. Quần áo dành cho bé trai ở đằng kia cơ."},{"section":"Bài khoá 3","context":"在商场里，刘明和王一雪在给孩子买衣服。 Lưu Minh và Vương Nhất Tuyết đang mua quần áo cho các con trong trung tâm thương mại.","audio":"10-5.mp3","speaker":"刘明","name":"Lưu Minh","zh":"好的。","py":"Hǎo de.","vi":"Ừ nhỉ."}],"dialogQuestions":[],"grammar":{"g1":{"han":"钱数的表达","py":"Qiánshù de biǎodá","title":"Cách diễn đạt số tiền","explain":"Đơn vị tiền tệ của Trung Quốc được gọi là Nhân dân tệ (RMB). Các đơn vị của Nhân dân tệ xếp từ lớn đến nhỏ là “元”, “角” và “分”, trong văn nói lần lượt được gọi là “块”, “毛” và “分”.","examples":[{"zh":"0.02元（两分）","py":"liǎng fēn","vi":"0,02 tệ (2 xu)","hl":"两分"},{"zh":"0.2元（两毛）","py":"liǎng máo","vi":"0,2 tệ (2 hào)","hl":"两毛"},{"zh":"3元（三块）","py":"sān kuài","vi":"3 tệ (3 đồng)","hl":"三块"},{"zh":"3.2元（三块二）","py":"sān kuài èr","vi":"3,2 tệ (3 đồng 2 hào)","hl":"三块二"},{"zh":"6.02元（六块零两分）","py":"liù kuài líng liǎng fēn","vi":"6,02 tệ (6 đồng lẻ 2 xu)","hl":"六块零两分"},{"zh":"202.2元（二百零二块两毛）","py":"èrbǎi líng èr kuài liǎng máo","vi":"202,2 tệ (202 đồng 2 hào)","hl":"二百零二块两毛"}],"struct":"元/块 → 角/毛 → 分","note":"Trong văn viết thường dùng “元、角、分”, trong văn nói thường dùng “块、毛、分”."},"g2":{"han":"形容词谓语句","py":"Xíngróngcí wèiyǔjù","title":"Câu vị ngữ tính từ","explain":"Tính từ có thể trực tiếp làm vị ngữ, trước tính từ có thể thêm phó từ chỉ mức độ hoặc phó từ phủ định.","examples":[{"zh":"这儿的水果真不少！","py":"Zhèr de shuǐguǒ zhēn bù shǎo!","vi":"Hoa quả ở đây thật nhiều!","hl":"真不少"},{"zh":"我的房间不大。","py":"Wǒ de fángjiān bú dà.","vi":"Phòng của tôi không lớn.","hl":"不大"},{"zh":"那个苹果好吃。","py":"Nàge píngguǒ hǎochī.","vi":"Quả táo kia ngon.","hl":"好吃"}],"struct":"Chủ ngữ + (Phó từ chỉ mức độ / Phó từ phủ định) + Tính từ","note":"Tính từ trực tiếp làm vị ngữ trong câu, không dùng động từ “是” phía trước."},"g3":{"han":"疑问代词“怎么样”","py":"Yíwèn dàicí “zěnmeyàng”","title":"Đại từ nghi vấn “怎么样”","explain":"Đại từ nghi vấn “怎么样” được dùng để hỏi ý kiến hoặc hỏi thăm về tình hình...","examples":[{"zh":"A: 这个杯子怎么样？ B: 我很喜欢，也不贵。","py":"A: Zhège bēizi zěnmeyàng? B: Wǒ hěn xǐhuan, yě bú guì.","vi":"A: Chiếc cốc này thế nào? B: Tôi rất thích, cũng không đắt.","hl":"怎么样"},{"zh":"A: 这本书怎么样？ B: 很好看。","py":"A: Zhè běn shū zěnmeyàng? B: Hěn hǎokàn.","vi":"A: Quyển sách này thế nào? B: Rất hay.","hl":"怎么样"},{"zh":"A: 这个菜怎么样？ B: 这个菜不太好吃，我不喜欢。","py":"A: Zhège cài zěnmeyàng? B: Zhège cài bú tài hǎochī, wǒ bù xǐhuan.","vi":"A: Món ăn này thế nào? B: Món này không ngon lắm, tôi không thích.","hl":"怎么样"}],"struct":"……怎么样？","note":"“怎么样” đứng cuối câu làm vị ngữ để hỏi ý kiến, nhận xét hoặc tình trạng."}},"grammarQuiz":[{"id":"hsk1_b10_q1","qtype":"fill","prompt":"综合练习 — 选词填空 (Chọn từ thích hợp điền vào chỗ trống):","q":"(1) 请问，这本书______钱？","opts":[{"t":"杯子","ok":false},{"t":"怎么样","ok":false},{"t":"多少","ok":true},{"t":"这些","ok":false},{"t":"块","ok":false}],"exp":"Hỏi giá tiền dùng “多少钱？” (Bao nhiêu tiền?)."},{"id":"hsk1_b10_q2a","qtype":"fill","prompt":"综合练习 — 选词填空 (Chọn từ thích hợp điền vào chỗ trống):","q":"(2a) 这个______不便宜，六十五块钱一个。","opts":[{"t":"杯子","ok":true},{"t":"怎么样","ok":false},{"t":"多少","ok":false},{"t":"这些","ok":false},{"t":"块","ok":false}],"exp":"Sau “这个” cần danh từ phù hợp với lượng từ “个” → “杯子” (cốc)."},{"id":"hsk1_b10_q2b","qtype":"fill","prompt":"综合练习 — 选词填空 (Chọn từ thích hợp điền vào chỗ trống):","q":"(2b) 这个杯子不便宜，六十五______钱一个。","opts":[{"t":"杯子","ok":false},{"t":"怎么样","ok":false},{"t":"多少","ok":false},{"t":"这些","ok":false},{"t":"块","ok":true}],"exp":"Đơn vị tiền tệ trước “钱” trong khẩu ngữ là “块” (六十五块钱)."},{"id":"hsk1_b10_q3","qtype":"fill","prompt":"综合练习 — 选词填空 (Chọn từ thích hợp điền vào chỗ trống):","q":"(3) 售货员：______苹果很好吃，你买一些吧。 王一雪：好的，我买五个。","opts":[{"t":"杯子","ok":false},{"t":"怎么样","ok":false},{"t":"多少","ok":false},{"t":"这些","ok":true},{"t":"块","ok":false}],"exp":"“这些苹果” nghĩa là “những quả táo này”."},{"id":"hsk1_b10_q4","qtype":"fill","prompt":"综合练习 — 选词填空 (Chọn từ thích hợp điền vào chỗ trống):","q":"(4) 安妮：这件衣服______？ 白家月：很好看。","opts":[{"t":"杯子","ok":false},{"t":"怎么样","ok":true},{"t":"多少","ok":false},{"t":"这些","ok":false},{"t":"块","ok":false}],"exp":"Hỏi ý kiến, nhận xét về chiếc áo dùng đại từ nghi vấn “怎么样”."}],"chars":["杯","子","售","货","员","边","钱","些","块","果","少","斤","苹","便","宜","商","店","衣","服","贵"],"rhyme":null,"notes":["小语的彩蛋 (Món quà của Tiểu Ngữ · 10-1): 认识人民币 — Nhận biết về đồng Nhân dân tệ.","Câu hỏi theo nội dung Bài khoá 3 (p.75): (1) 那件衣服王一雪想买几件？ (Vương Nhất Tuyết muốn mua mấy chiếc áo đó?) — (2) 男孩子的衣服在哪儿？ (Quần áo của bé trai ở đâu?)","课堂活动 (Hoạt động trên lớp · p.77): Đóng vai (角色扮演) — Ba người một nhóm, một người đóng vai nhân viên bán hàng, hai người còn lại đóng vai khách hàng, hội thoại với nhau dựa theo nội dung ba bài khoá trong bài học này."],"workbook":{"exercisesNote":"SBT Bài 10 (tr. 66–74): Tiểu Ngữ giảng đường — Ngữ âm (1. Đánh dấu thanh điệu; 2. Phân biệt thanh điệu khác biệt) + Đề luyện mô phỏng 模拟测练 (20 câu: Nghe 1–10, Đọc hiểu 11–20).","answerKeyNote":"语音 1 (Đánh dấu thanh điệu): (1) duì | (2) jiā | (3) guó | (4) xiǎng | (5) chāoshì | (6) niúnǎi | (7) shàngwǔ | (8) diànyǐng.\n语音 2 (Phân biệt thanh điệu): (1) C zhuō | (2) B chá | (3) B qù | (4) A yǒu | (5) C yīyuàn.\n模拟测练 — Nghe (1–10): P1: 1.B 2.C 3.B | P2: 4.B 5.B | P3: 6.C 7.D 8.B | P4: 9.A 10.B.\n模拟测练 — Đọc (11–20): P1: 11.C 12.B 13.D | P2: 14.C 15.A 16.B | P3: 17.B 18.A | P4: 19.B 20.A.","transcriptNote":""}},"11":{"pages":"78–85","titleZh":"我读大学呢","titlePy":"Wǒ dú dàxué ne","titleVi":"Em đang học đại học","goals":["Có thể nghe hiểu và sử dụng được ba cấu trúc diễn đạt hành động đang diễn ra.","Có thể nghe hiểu và đặt câu hỏi bằng cấu trúc câu hỏi chính phản.","Nắm vững cách sử dụng của động từ năng nguyện “要” để diễn đạt mong muốn làm gì hoặc dự định làm việc gì đó."],"words":[{"zh":"时候","py":"shíhou","vi":"lúc, khi","pos":"dt."},{"zh":"饭店","py":"fàndiàn","vi":"nhà hàng, khách sạn","pos":"dt."},{"zh":"知道","py":"zhīdào","vi":"biết, nhận ra","pos":"đgt."},{"zh":"正在","py":"zhèngzài","vi":"đang (làm gì)","pos":"phó."},{"zh":"找","py":"zhǎo","vi":"tìm, kiếm","pos":"đgt."},{"zh":"开车","py":"kāichē","vi":"lái xe (ô tô)","pos":"đgt."},{"zh":"车","py":"chē","vi":"xe","pos":"dt."},{"zh":"在","py":"zài","vi":"đang","pos":"phó."},{"zh":"读","py":"dú","vi":"học, đọc","pos":"đgt."},{"zh":"大学","py":"dàxué","vi":"đại học","pos":"dt."},{"zh":"大学生","py":"dàxuéshēng","vi":"sinh viên","pos":"dt."},{"zh":"学","py":"xué","vi":"học","pos":"đgt."},{"zh":"医","py":"yī","vi":"y, y học, y khoa","pos":"dt."},{"zh":"弟弟","py":"dìdi","vi":"em trai","pos":"dt."},{"zh":"起床","py":"qǐchuáng","vi":"thức dậy, ngủ dậy, dậy","pos":"đgt."},{"zh":"睡觉","py":"shuìjiào","vi":"ngủ","pos":"đgt."},{"zh":"睡","py":"shuì","vi":"ngủ","pos":"đgt."},{"zh":"那里","py":"nàlǐ","vi":"ở kia, chỗ đó","pos":"đt."},{"zh":"哪里","py":"nǎlǐ","vi":"đâu, chỗ nào, nơi nào","pos":"đt."},{"zh":"昨天","py":"zuótiān","vi":"hôm qua","pos":"dt."},{"zh":"问","py":"wèn","vi":"hỏi","pos":"đgt."},{"zh":"对","py":"duì","vi":"với, đối với","pos":"giới."},{"zh":"说","py":"shuō","vi":"nói","pos":"đgt."},{"zh":"要","py":"yào","vi":"cần, muốn, phải","pos":"đtnn."},{"zh":"小朋友","py":"xiǎopéngyǒu","vi":"bạn nhỏ","pos":"dt."}],"dialog":[{"section":"Bài khoá 1","context":"在路上，李文在找饭店，王一飞给他打电话。 Lý Văn đang tìm nhà hàng trên đường đi, Vương Nhất Phi gọi điện cho anh ấy.","audio":"11-1.mp3","speaker":"王一飞","name":"Vương Nhất Phi","zh":"喂，李文，你什么时候能到饭店？","py":"Wèi, Lǐ Wén, nǐ shénme shíhou néng dào fàndiàn?","vi":"A lô, Lý Văn à, khi nào em có thể đến nhà hàng?"},{"section":"Bài khoá 1","context":"在路上，李文在找饭店，王一飞给他打电话。 Lý Văn đang tìm nhà hàng trên đường đi, Vương Nhất Phi gọi điện cho anh ấy.","audio":"11-1.mp3","speaker":"李文","name":"Lý Văn","zh":"还不知道，正在找呢。它是不是在超市后边？","py":"Hái bù zhīdào, zhèngzài zhǎo ne. Tā shì bu shì zài chāoshì hòubian?","vi":"Cũng không biết ạ, em đang tìm đây. Nó có phải ở phía sau siêu thị không?"},{"section":"Bài khoá 1","context":"在路上，李文在找饭店，王一飞给他打电话。 Lý Văn đang tìm nhà hàng trên đường đi, Vương Nhất Phi gọi điện cho anh ấy.","audio":"11-1.mp3","speaker":"王一飞","name":"Vương Nhất Phi","zh":"是的。你开车没开车？","py":"Shì de. Nǐ kāichē méi kāichē?","vi":"Đúng rồi. Em có lái xe không?"},{"section":"Bài khoá 1","context":"在路上，李文在找饭店，王一飞给他打电话。 Lý Văn đang tìm nhà hàng trên đường đi, Vương Nhất Phi gọi điện cho anh ấy.","audio":"11-1.mp3","speaker":"李文","name":"Lý Văn","zh":"我没开车，坐车呢。","py":"Wǒ méi kāichē, zuò chē ne.","vi":"Em không lái xe, đang đi taxi đây."},{"section":"Bài khoá 2","context":"在饭店里，王一飞和李文见面后聊天儿。 Vương Nhất Phi và Lý Văn trò chuyện sau khi gặp nhau tại nhà hàng.","audio":"11-3.mp3","speaker":"王一飞","name":"Vương Nhất Phi","zh":"你还在读大学吗？","py":"Nǐ hái zài dú dàxué ma?","vi":"Em vẫn đang học đại học à?"},{"section":"Bài khoá 2","context":"在饭店里，王一飞和李文见面后聊天儿。 Vương Nhất Phi và Lý Văn trò chuyện sau khi gặp nhau tại nhà hàng.","audio":"11-3.mp3","speaker":"李文","name":"Lý Văn","zh":"对，我读大学呢，还是大学生。","py":"Duì, wǒ dú dàxué ne, hái shì dàxuéshēng.","vi":"Đúng vậy, em đang học đại học, vẫn đang là sinh viên."},{"section":"Bài khoá 2","context":"在饭店里，王一飞和李文见面后聊天儿。 Vương Nhất Phi và Lý Văn trò chuyện sau khi gặp nhau tại nhà hàng.","audio":"11-3.mp3","speaker":"王一飞","name":"Vương Nhất Phi","zh":"你们学习忙不忙？","py":"Nǐmen xuéxí máng bu máng?","vi":"Các em học có bận không?"},{"section":"Bài khoá 2","context":"在饭店里，王一飞和李文见面后聊天儿。 Vương Nhất Phi và Lý Văn trò chuyện sau khi gặp nhau tại nhà hàng.","audio":"11-3.mp3","speaker":"李文","name":"Lý Văn","zh":"非常忙，我学医，我们的课很多。","py":"Fēicháng máng, wǒ xué yī, wǒmen de kè hěn duō.","vi":"Bận lắm ạ, em học ngành y, chúng em có rất nhiều môn học."},{"section":"Bài khoá 3","context":"星期六早上，刘明要去医院加班，出门前和女儿对话。 Sáng thứ Bảy, Lưu Minh phải đến bệnh viện làm thêm giờ, anh trò chuyện với con gái trước khi ra khỏi nhà.","audio":"11-5.mp3","speaker":"刘明","name":"Lưu Minh","zh":"弟弟起床没起床呢？","py":"Dìdi qǐchuáng méi qǐchuáng ne?","vi":"Em đã thức dậy chưa con?"},{"section":"Bài khoá 3","context":"星期六早上，刘明要去医院加班，出门前和女儿对话。 Sáng thứ Bảy, Lưu Minh phải đến bệnh viện làm thêm giờ, anh trò chuyện với con gái trước khi ra khỏi nhà.","audio":"11-5.mp3","speaker":"刘小雪","name":"Lưu Tiểu Tuyết","zh":"没起床呢，还在睡觉。","py":"Méi qǐchuáng ne, hái zài shuìjiào.","vi":"Chưa thức dậy ạ, em vẫn còn đang ngủ."},{"section":"Bài khoá 3","context":"星期六早上，刘明要去医院加班，出门前和女儿对话。 Sáng thứ Bảy, Lưu Minh phải đến bệnh viện làm thêm giờ, anh trò chuyện với con gái trước khi ra khỏi nhà.","audio":"11-5.mp3","speaker":"刘明","name":"Lưu Minh","zh":"还睡呢？他今天去不去那里？","py":"Hái shuì ne? Tā jīntiān qù bu qù nàlǐ?","vi":"Vẫn còn ngủ à? Hôm nay em có đi đến đó không?"},{"section":"Bài khoá 3","context":"星期六早上，刘明要去医院加班，出门前和女儿对话。 Sáng thứ Bảy, Lưu Minh phải đến bệnh viện làm thêm giờ, anh trò chuyện với con gái trước khi ra khỏi nhà.","audio":"11-5.mp3","speaker":"刘小雪","name":"Lưu Tiểu Tuyết","zh":"去哪里？","py":"Qù nǎlǐ?","vi":"Đi đâu ạ?"},{"section":"Bài khoá 3","context":"星期六早上，刘明要去医院加班，出门前和女儿对话。 Sáng thứ Bảy, Lưu Minh phải đến bệnh viện làm thêm giờ, anh trò chuyện với con gái trước khi ra khỏi nhà.","audio":"11-5.mp3","speaker":"刘明","name":"Lưu Minh","zh":"去超市。","py":"Qù chāoshì.","vi":"Đi siêu thị."},{"section":"Bài khoá 3","context":"星期六早上，刘明要去医院加班，出门前和女儿对话。 Sáng thứ Bảy, Lưu Minh phải đến bệnh viện làm thêm giờ, anh trò chuyện với con gái trước khi ra khỏi nhà.","audio":"11-5.mp3","speaker":"刘小雪","name":"Lưu Tiểu Tuyết","zh":"我昨天问他，他对我说，他不去，他今天要和小朋友玩。","py":"Wǒ zuótiān wèn tā, tā duì wǒ shuō, tā bú qù, tā jīntiān yào hé xiǎopéngyǒu wán.","vi":"Hôm qua con hỏi em rồi. Em nói với con là em không đi, hôm nay em muốn chơi với các bạn."}],"dialogQuestions":[],"grammar":{"g1":{"han":"正反问","py":"Zhèngfǎnwèn","title":"Câu hỏi chính phản","explain":"Cấu trúc của câu hỏi chính phản là “×+不/没+×”, “×” là động từ hoặc tính từ. Sử dụng “不/没” cho câu hỏi chính phản động từ và “不” cho câu hỏi chính phản tính từ.","examples":[{"zh":"它是不是在超市后边？","py":"Tā shì bu shì zài chāoshì hòubian?","vi":"Nó có phải ở phía sau siêu thị không?","hl":"是不是"},{"zh":"你去没去学校？","py":"Nǐ qù méi qù xuéxiào?","vi":"Bạn đã đến trường chưa?","hl":"去没去"},{"zh":"这件衣服好看不好看？","py":"Zhè jiàn yīfu hǎokàn bu hǎokàn?","vi":"Chiếc áo này có đẹp không?","hl":"好看不好看"},{"zh":"A: 他去哪儿了？你知道不知道？ B: 我不知道。","py":"A: Tā qù nǎr le? Nǐ zhīdào bu zhīdào? B: Wǒ bù zhīdào.","vi":"A: Anh ấy đi đâu rồi? Bạn có biết không? B: Tôi không biết.","hl":"知道不知道"},{"zh":"A: 昨天你去没去书店？ B: 我没去。","py":"A: Zuótiān nǐ qù méi qù shūdiàn? B: Wǒ méi qù.","vi":"A: Hôm qua bạn có đi hiệu sách không? B: Tôi không đi.","hl":"去没去"},{"zh":"A: 这件衣服贵不贵？ B: 不贵。","py":"A: Zhè jiàn yīfu guì bu guì? B: Bú guì.","vi":"A: Chiếc áo này có đắt không? B: Không đắt.","hl":"贵不贵"}],"struct":"× + 不/没 + ×","note":"Trong câu hỏi chính phản không dùng thêm “吗” ở cuối câu."},"g2":{"han":"时间副词“在/正在”","py":"Shíjiān fùcí “zài/zhèngzài”","title":"Phó từ chỉ thời gian “在/正在”","explain":"Phó từ chỉ thời gian “在/正在” đứng trước động từ để biểu thị hành động đang diễn ra hoặc tình huống đang tiếp diễn. Trong bài học này giới thiệu hai hình thức: (1) 在/正在 + động từ; (2) 在/正在 + động từ + 呢. Ngoài ra, để diễn đạt đang làm việc gì có thể sử dụng hình thức thứ ba: (3) động từ + 呢. Khi trả lời phủ định, sử dụng phó từ “没(有)”.","examples":[{"zh":"你还在读大学吗？","py":"Nǐ hái zài dú dàxué ma?","vi":"Em vẫn đang học đại học à?","hl":"在读"},{"zh":"学生们在/正在上课呢。","py":"Xuéshengmen zài/zhèngzài shàngkè ne.","vi":"Các học sinh đang học trên lớp.","hl":"在/正在上课呢"},{"zh":"我们读书呢。","py":"Wǒmen dúshū ne.","vi":"Chúng tôi đang đọc sách.","hl":"读书呢"},{"zh":"A: 你在做什么呢？ B: 我正在看电视。","py":"A: Nǐ zài zuò shénme ne? B: Wǒ zhèngzài kàn diànshì.","vi":"A: Bạn đang làm gì thế? B: Tôi đang xem ti vi.","hl":"在做什么呢"},{"zh":"A: 我去看电影，你去不去？ B: 我在学习呢，不想去。","py":"A: Wǒ qù kàn diànyǐng, nǐ qù bu qù? B: Wǒ zài xuéxí ne, bù xiǎng qù.","vi":"A: Tôi đi xem phim, bạn đi không? B: Tôi đang học bài, không muốn đi.","hl":"在学习呢"},{"zh":"A: 你在买菜吗？ B: 我没买菜，买水果呢。","py":"A: Nǐ zài mǎi cài ma? B: Wǒ méi mǎi cài, mǎi shuǐguǒ ne.","vi":"A: Bạn đang mua rau à? B: Tôi không mua rau, đang mua hoa quả đây.","hl":"没买菜"}],"struct":"(1) 在/正在 + Động từ | (2) 在/正在 + Động từ + 呢 | (3) Động từ + 呢","note":"Khi phủ định hành động đang diễn ra, dùng “没(有)” trước động từ."},"g3":{"han":"能愿动词“要”","py":"Néngyuàn dòngcí “yào”","title":"Động từ năng nguyện “要”","explain":"Động từ năng nguyện “要” đặt trước động từ, biểu thị mong muốn hoặc dự định làm việc gì đó.","examples":[{"zh":"他今天要和小朋友玩。","py":"Tā jīntiān yào hé xiǎopéngyǒu wán.","vi":"Hôm nay em ấy muốn chơi với các bạn nhỏ.","hl":"要"},{"zh":"妈妈要去超市。","py":"Māma yào qù chāoshì.","vi":"Mẹ định đi siêu thị.","hl":"要"},{"zh":"白家月要在家里学中文。","py":"Bái Jiāyuè yào zài jiā li xué Zhōngwén.","vi":"Bạch Gia Nguyệt muốn học tiếng Trung ở nhà.","hl":"要"}],"struct":"Chủ ngữ + 要 + Động từ (+ Tân ngữ)","note":"Động từ năng nguyện “要” đứng trước động từ chính để diễn đạt ý muốn hoặc kế hoạch."}},"grammarQuiz":[{"id":"hsk1_b11_q1","qtype":"fill","prompt":"综合练习 — 选词填空 (Chọn từ thích hợp điền vào chỗ trống):","q":"(1) 你______超市？","opts":[{"t":"那里","ok":false},{"t":"睡觉","ok":false},{"t":"去不去","ok":true},{"t":"要","ok":false},{"t":"正在","ok":false}],"exp":"Câu hỏi chính phản động từ “去不去” (Bạn có đi siêu thị không?)."},{"id":"hsk1_b11_q2","qtype":"fill","prompt":"综合练习 — 选词填空 (Chọn từ thích hợp điền vào chỗ trống):","q":"(2) 她没在看电视，______学习呢。","opts":[{"t":"那里","ok":false},{"t":"睡觉","ok":false},{"t":"去不去","ok":false},{"t":"要","ok":false},{"t":"正在","ok":true}],"exp":"Cấu trúc “正在 + động từ + 呢” biểu thị hành động đang diễn ra."},{"id":"hsk1_b11_q3a","qtype":"fill","prompt":"综合练习 — 选词填空 (Chọn từ thích hợp điền vào chỗ trống):","q":"(3a) 弟弟：姐姐，我们去______玩吧，好不好？","opts":[{"t":"那里","ok":true},{"t":"睡觉","ok":false},{"t":"去不去","ok":false},{"t":"要","ok":false},{"t":"正在","ok":false}],"exp":"Sau “去” cần đại từ chỉ nơi chốn → “那里” (ở kia, chỗ đó)."},{"id":"hsk1_b11_q3b","qtype":"fill","prompt":"综合练习 — 选词填空 (Chọn từ thích hợp điền vào chỗ trống):","q":"(3b) 姐姐：我不去，我______读书。","opts":[{"t":"那里","ok":false},{"t":"睡觉","ok":false},{"t":"去不去","ok":false},{"t":"要","ok":true},{"t":"正在","ok":false}],"exp":"Động từ năng nguyện “要” đứng trước “读书” biểu thị dự định/mong muốn đọc sách."},{"id":"hsk1_b11_q4","qtype":"fill","prompt":"综合练习 — 选词填空 (Chọn từ thích hợp điền vào chỗ trống):","q":"(4) 妈妈：爸爸在做什么？ 孩子：他在______呢。","opts":[{"t":"那里","ok":false},{"t":"睡觉","ok":true},{"t":"去不去","ok":false},{"t":"要","ok":false},{"t":"正在","ok":false}],"exp":"Cấu trúc “在 + động từ + 呢” → “他在睡觉呢。” (Bố đang ngủ ạ.)."}],"chars":["时","候","饭","知","道","正","找","开","车","读","学","医","弟","起","床","睡","觉","昨","问","要"],"rhyme":null,"notes":["Câu hỏi theo nội dung Bài khoá 3 (p.83): (1) 弟弟起床没起床？ (Em trai đã thức dậy chưa?) — (2) 弟弟今天要做什么？ (Hôm nay em trai định làm gì?)","课堂活动 (Hoạt động trên lớp · p.85): 双人活动 (Hoạt động theo nhóm hai người) — Hai người một nhóm, lần lượt hỏi và trả lời về việc có làm hay không làm một việc nào đó. 小语的例子 (Ví dụ của Tiểu Ngữ): A: 你去不去吃午饭？ / B: 我不去。 / A: 你在做什么？ / B: 我在学中文呢。你学不学？"],"workbook":{"exercisesNote":"SBT Bài 11 (tr. 75–83): Tiểu Ngữ giảng đường — Ngữ âm (1. Đánh dấu thanh điệu; 2. Phân biệt thanh điệu khác biệt) + Đề luyện mô phỏng 模拟测练 (20 câu: Nghe 1–10, Đọc hiểu 11–20).","answerKeyNote":"语音 1 (Đánh dấu thanh điệu): (1) chàng | (2) lěng | (3) huí | (4) shuìjiào | (5) píngguǒ | (6) jīdàn | (7) dàxuéshēng | (8) diànyǐngyuàn.\n语音 2 (Phân biệt thanh điệu): (1) A mǎi | (2) C rè | (3) C xiàbān | (4) B hǎotīng | (5) B zhōngxuéshēng.\n模拟测练 — Nghe (1–10): P1: 1.C 2.B 3.C | P2: 4.B 5.C | P3: 6.D 7.C 8.B | P4: 9.B 10.C.\n模拟测练 — Đọc (11–20): P1: 11.C 12.B 13.D | P2: 14.A 15.B 16.C | P3: 17.B 18.A | P4: 19.C 20.C.","transcriptNote":""}},"12":{"pages":"86–94","titleZh":"昨天下雪了","titlePy":"Zuótiān xià xuě le","titleVi":"Hôm qua tuyết rơi rồi","goals":["Có thể nghe hiểu và miêu tả được tình hình thời tiết.","Có thể nghe hiểu và miêu tả ngắn gọn tình trạng bệnh tật.","Nắm vững cách sử dụng của trợ từ ngữ khí “了(1)”.","Nắm vững cách sử dụng của cấu trúc “太……了”.","Hiểu được lợi ích của việc “uống một chút nước ấm” mà người Trung Quốc thường khuyên khi bị ốm."],"words":[{"zh":"天气","py":"tiānqì","vi":"thời tiết","pos":"dt."},{"zh":"这里","py":"zhèlǐ","vi":"ở đây, chỗ này","pos":"đt."},{"zh":"天","py":"tiān","vi":"thời tiết, trời","pos":"dt."},{"zh":"下雨","py":"xià yǔ","vi":"mưa, mưa rơi","pos":""},{"zh":"了","py":"le","vi":"dùng cuối câu chỉ sự thay đổi tình hình hoặc trạng thái","pos":"trợ."},{"zh":"雨","py":"yǔ","vi":"mưa","pos":"dt."},{"zh":"有点儿","py":"yǒudiǎnr","vi":"hơi, hơi... một chút","pos":"phó."},{"zh":"觉得","py":"juéde","vi":"cảm thấy","pos":"đgt."},{"zh":"冷","py":"lěng","vi":"lạnh","pos":"tt."},{"zh":"下","py":"xià","vi":"(mưa, tuyết...) rơi","pos":"đgt."},{"zh":"雪","py":"xuě","vi":"tuyết","pos":"dt."},{"zh":"来","py":"lái","vi":"đến","pos":"đgt."},{"zh":"公司","py":"gōngsī","vi":"công ty","pos":"dt."},{"zh":"生病","py":"shēngbìng","vi":"ốm, bị ốm, bệnh, bị bệnh","pos":"đgt."},{"zh":"看病","py":"kànbìng","vi":"khám bệnh","pos":"đgt."},{"zh":"病","py":"bìng","vi":"ốm, bị ốm, bệnh, bị bệnh","pos":"đgt."},{"zh":"一点儿","py":"yìdiǎnr","vi":"một chút, một ít","pos":"sl."},{"zh":"药","py":"yào","vi":"thuốc","pos":"dt."},{"zh":"天","py":"tiān","vi":"ngày","pos":"lượng."},{"zh":"回","py":"huí","vi":"về, quay về","pos":"đgt."},{"zh":"再","py":"zài","vi":"sau đó, mới (chỉ trình tự)","pos":"phó."},{"zh":"喝","py":"hē","vi":"uống","pos":"đgt."},{"zh":"热","py":"rè","vi":"nóng, ấm","pos":"tt."},{"zh":"水","py":"shuǐ","vi":"nước","pos":"dt."}],"dialog":[{"section":"Bài khoá 1","context":"王一雪给王一飞打电话，询问王一飞那边的情况。 Vương Nhất Tuyết gọi điện cho Vương Nhất Phi để hỏi thăm tình hình chỗ cô ấy.","audio":"12-1.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"今天天气怎么样？","py":"Jīntiān tiānqì zěnmeyàng?","vi":"Hôm nay thời tiết thế nào?"},{"section":"Bài khoá 1","context":"王一雪给王一飞打电话，询问王一飞那边的情况。 Vương Nhất Tuyết gọi điện cho Vương Nhất Phi để hỏi thăm tình hình chỗ cô ấy.","audio":"12-1.mp3","speaker":"王一飞","name":"Vương Nhất Phi","zh":"这里的天不太好，下雨了。","py":"Zhèlǐ de tiān bú tài hǎo, xià yǔ le.","vi":"Thời tiết ở đây không ổn lắm, mưa rồi ạ."},{"section":"Bài khoá 1","context":"王一雪给王一飞打电话，询问王一飞那边的情况。 Vương Nhất Tuyết gọi điện cho Vương Nhất Phi để hỏi thăm tình hình chỗ cô ấy.","audio":"12-1.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"雨大吗？","py":"Yǔ dà ma?","vi":"Mưa to không?"},{"section":"Bài khoá 1","context":"王一雪给王一飞打电话，询问王一飞那边的情况。 Vương Nhất Tuyết gọi điện cho Vương Nhất Phi để hỏi thăm tình hình chỗ cô ấy.","audio":"12-1.mp3","speaker":"王一飞","name":"Vương Nhất Phi","zh":"有点儿大，我觉得很冷。","py":"Yǒudiǎnr dà, wǒ juéde hěn lěng.","vi":"Hơi to ạ, em cảm thấy rất lạnh."},{"section":"Bài khoá 2","context":"在公司电梯里，王一雪和杨同乐在聊天儿。 Vương Nhất Tuyết và Dương Đồng Lạc đang trò chuyện trong thang máy công ty.","audio":"12-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"昨天下雪了。","py":"Zuótiān xià xuě le.","vi":"Hôm qua tuyết rơi rồi."},{"section":"Bài khoá 2","context":"在公司电梯里，王一雪和杨同乐在聊天儿。 Vương Nhất Tuyết và Dương Đồng Lạc đang trò chuyện trong thang máy công ty.","audio":"12-3.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"是的，太冷了。","py":"Shì de, tài lěng le.","vi":"Đúng vậy, trời lạnh quá."},{"section":"Bài khoá 2","context":"在公司电梯里，王一雪和杨同乐在聊天儿。 Vương Nhất Tuyết và Dương Đồng Lạc đang trò chuyện trong thang máy công ty.","audio":"12-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"你昨天没来公司，生病了？","py":"Nǐ zuótiān méi lái gōngsī, shēngbìng le?","vi":"Hôm qua em không đến công ty, bị ốm à?"},{"section":"Bài khoá 2","context":"在公司电梯里，王一雪和杨同乐在聊天儿。 Vương Nhất Tuyết và Dương Đồng Lạc đang trò chuyện trong thang máy công ty.","audio":"12-3.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"对，我昨天去医院看病了。","py":"Duì, wǒ zuótiān qù yīyuàn kànbìng le.","vi":"Vâng, hôm qua em đi bệnh viện khám bệnh."},{"section":"Bài khoá 3","context":"昨天在医院，医生给杨同乐看病。 Hôm qua, bác sĩ khám bệnh cho Dương Đồng Lạc tại bệnh viện.","audio":"12-5.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"医生，我病了。","py":"Yīshēng, wǒ bìng le.","vi":"Thưa bác sĩ, tôi bị ốm rồi."},{"section":"Bài khoá 3","context":"昨天在医院，医生给杨同乐看病。 Hôm qua, bác sĩ khám bệnh cho Dương Đồng Lạc tại bệnh viện.","audio":"12-5.mp3","speaker":"胡医生","name":"Bác sĩ Hồ","zh":"我看看。你觉得怎么样？","py":"Wǒ kànkan. Nǐ juéde zěnmeyàng?","vi":"Để tôi khám xem. Anh cảm thấy thế nào?"},{"section":"Bài khoá 3","context":"昨天在医院，医生给杨同乐看病。 Hôm qua, bác sĩ khám bệnh cho Dương Đồng Lạc tại bệnh viện.","audio":"12-5.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"我很冷。","py":"Wǒ hěn lěng.","vi":"Tôi rất lạnh."},{"section":"Bài khoá 3","context":"昨天在医院，医生给杨同乐看病。 Hôm qua, bác sĩ khám bệnh cho Dương Đồng Lạc tại bệnh viện.","audio":"12-5.mp3","speaker":"胡医生","name":"Bác sĩ Hồ","zh":"好的，吃一点儿药，今天休息半天吧。","py":"Hǎo de, chī yìdiǎnr yào, jīntiān xiūxi bàn tiān ba.","vi":"Được rồi, uống một ít thuốc nhé, hôm nay nghỉ ngơi nửa ngày nhé."},{"section":"Bài khoá 3","context":"昨天在医院，医生给杨同乐看病。 Hôm qua, bác sĩ khám bệnh cho Dương Đồng Lạc tại bệnh viện.","audio":"12-5.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"好的。","py":"Hǎo de.","vi":"Vâng."},{"section":"Bài khoá 3","context":"昨天在医院，医生给杨同乐看病。 Hôm qua, bác sĩ khám bệnh cho Dương Đồng Lạc tại bệnh viện.","audio":"12-5.mp3","speaker":"胡医生","name":"Bác sĩ Hồ","zh":"回家后再喝些热水。","py":"Huí jiā hòu zài hē xiē rè shuǐ.","vi":"Sau khi về nhà nhớ uống thêm ít nước ấm nhé."}],"dialogQuestions":[],"grammar":{"g1":{"han":"非主谓句","py":"Fēi zhǔwèijù","title":"Câu phi chủ vị","explain":"Câu phi chủ vị là câu được cấu tạo bởi từ hoặc cụm từ, không phân biệt rõ chủ ngữ và vị ngữ, thường dùng trong văn nói.","examples":[{"zh":"下雨了。","py":"Xià yǔ le.","vi":"Trời mưa rồi.","hl":"下雨了"},{"zh":"下雪了。","py":"Xià xuě le.","vi":"Tuyết rơi rồi.","hl":"下雪了"},{"zh":"上课了。","py":"Shàngkè le.","vi":"Vào học rồi.","hl":"上课了"},{"zh":"真漂亮！","py":"Zhēn piàoliang!","vi":"Đẹp thật!","hl":"真漂亮"},{"zh":"对不起！","py":"Duìbuqǐ!","vi":"Xin lỗi!","hl":"对不起"},{"zh":"没关系！","py":"Méi guānxi!","vi":"Không có gì!","hl":"没关系"}],"struct":"Từ / Cụm từ (không phân biệt chủ ngữ và vị ngữ)","note":"Thường dùng trong khẩu ngữ hàng ngày để miêu tả thời tiết hoặc biểu đạt cảm xúc, lời chào hỏi."},"g2":{"han":"语气助词“了（1）”","py":"Yǔqì zhùcí “le (1)”","title":"Trợ từ ngữ khí “了(1)”","explain":"Trợ từ ngữ khí “了(1)” đặt ở cuối câu hoặc chỗ ngắt quãng trong câu để biểu thị sự thay đổi hoặc xuất hiện tình huống mới. Khi trả lời phủ định, sử dụng phó từ “没” và lược bỏ “了” ở cuối câu.","examples":[{"zh":"下雨了。","py":"Xià yǔ le.","vi":"Mưa rồi.","hl":"了"},{"zh":"十二点了，吃午饭吧。","py":"Shí\u0027èr diǎn le, chī wǔfàn ba.","vi":"12 giờ rồi, ăn trưa thôi.","hl":"了"},{"zh":"A: 弟弟起床了吗？ B: 没起床呢。","py":"A: Dìdi qǐchuáng le ma? B: Méi qǐchuáng ne.","vi":"A: Em trai đã thức dậy chưa? B: Chưa thức dậy.","hl":"没起床"}],"struct":"……了。 | Phủ định: 没 + Động từ (không dùng 了)","note":"Khi phủ định dùng phó từ “没” và lược bỏ “了” ở cuối câu."},"g3":{"han":"“太……了！”格式","py":"“Tài……le!” géshì","title":"Cấu trúc “太……了！”","explain":"Cấu trúc “太……了！” dùng để diễn đạt cảm thán về mức độ rất cao hoặc rất sâu sắc.","examples":[{"zh":"太冷了！","py":"Tài lěng le!","vi":"Lạnh quá!","hl":"太冷了"},{"zh":"这个杯子太小了。","py":"Zhège bēizi tài xiǎo le.","vi":"Chiếc cốc này nhỏ quá.","hl":"太小了"},{"zh":"我们今天太高兴了！","py":"Wǒmen jīntiān tài gāoxìng le!","vi":"Hôm nay chúng tôi vui quá!","hl":"太高兴了"}],"struct":"太 + Tính từ / Động từ tâm lý + 了！","note":"Thường dùng để cảm thán mức độ rất cao."}},"grammarQuiz":[{"id":"hsk1_b12_q1a","qtype":"fill","prompt":"综合练习 — 选词填空 (Chọn từ thích hợp điền vào chỗ trống):","q":"(1a) 外边正在下______，太冷了！","opts":[{"t":"怎么样","ok":false},{"t":"雪","ok":true},{"t":"了","ok":false},{"t":"看","ok":false},{"t":"太","ok":false}],"exp":"“下雪” nghĩa là “tuyết rơi”."},{"id":"hsk1_b12_q1b","qtype":"fill","prompt":"综合练习 — 选词填空 (Chọn từ thích hợp điền vào chỗ trống):","q":"(1b) 外边正在下雪，______冷了！","opts":[{"t":"怎么样","ok":false},{"t":"雪","ok":false},{"t":"了","ok":false},{"t":"看","ok":false},{"t":"太","ok":true}],"exp":"Cấu trúc cảm thán “太……了！” → “太冷了！” (Lạnh quá!)."},{"id":"hsk1_b12_q2","qtype":"fill","prompt":"综合练习 — 选词填空 (Chọn từ thích hợp điền vào chỗ trống):","q":"(2) 他去公司工作______。","opts":[{"t":"怎么样","ok":false},{"t":"雪","ok":false},{"t":"了","ok":true},{"t":"看","ok":false},{"t":"太","ok":false}],"exp":"Trợ từ ngữ khí “了” đặt cuối câu biểu thị tình huống mới (Anh ấy đi công ty làm việc rồi)."},{"id":"hsk1_b12_q3","qtype":"fill","prompt":"综合练习 — 选词填空 (Chọn từ thích hợp điền vào chỗ trống):","q":"(3) 医生：你觉得______？ 杨同乐：我很冷。","opts":[{"t":"怎么样","ok":true},{"t":"雪","ok":false},{"t":"了","ok":false},{"t":"看","ok":false},{"t":"太","ok":false}],"exp":"Hỏi cảm giác, tình trạng dùng đại từ nghi vấn “怎么样”."},{"id":"hsk1_b12_q4","qtype":"fill","prompt":"综合练习 — 选词填空 (Chọn từ thích hợp điền vào chỗ trống):","q":"(4) 王一雪：你昨天去医院______病了吗？ 杨同乐：没有，我今天去。","opts":[{"t":"怎么样","ok":false},{"t":"雪","ok":false},{"t":"了","ok":false},{"t":"看","ok":true},{"t":"太","ok":false}],"exp":"“看病” nghĩa là “khám bệnh”."}],"chars":["天","气","里","下","雨","了","觉","得","冷","雪","来","公","司","生","病","药","回","再","喝","热"],"rhyme":null,"notes":["小语助力 (Tiểu Ngữ giúp sức 1 · p.91): “看看”是“看”的重叠式，表示动作时间短。“看看” là hình thức lặp của “看”, biểu thị hành động diễn ra trong khoảng thời gian ngắn.","小语助力 (Tiểu Ngữ giúp sức 2 · p.91): 中国人喜欢喝热水，认为喝热水更健康。Người Trung Quốc thích uống nước ấm vì cho rằng uống nước ấm tốt cho sức khoẻ hơn.","Câu hỏi theo nội dung Bài khoá 2 (p.90): (1) 昨天天气怎么样？ (Thời tiết hôm qua thế nào?) — (2) 杨同乐昨天做什么了？ (Dương Đồng Lạc ngày hôm qua đã làm gì?)","Câu hỏi theo nội dung Bài khoá 3 (p.91): (1) 杨同乐生病了吗？ (Dương Đồng Lạc ốm rồi phải không?) — (2) 看病后，杨同乐回家要做什么？ (Sau khi khám bệnh xong, Dương Đồng Lạc về nhà làm gì?)","课堂活动 (Hoạt động trên lớp · p.93): Đóng vai (角色扮演) — Hai người một nhóm, một người đóng vai bác sĩ, người còn lại đóng vai bệnh nhân đến khám bệnh. 小语的例子 (Ví dụ của Tiểu Ngữ): 病人：医生，我病了。 / 医生：我看看。你觉得冷不冷？ / 病人：有点儿冷。 / 医生：好的，吃一点儿药吧。","学习小结 (Tổng kết học tập Bài 10–12 · p.93–94): Ôn tập hỏi giá sản phẩm (苹果多少钱？), cách diễn đạt số tiền (三块二，六块零两分), câu vị ngữ tính từ (这个苹果很好吃。), đại từ nghi vấn “怎么样” (这件衣服怎么样？), câu hỏi chính phản (好不好？), phó từ chỉ thời gian “在/正在” (他在休息呢。), động từ năng nguyện “要” (我要睡觉。), câu phi chủ vị (下雨了。), trợ từ ngữ khí “了(1)” (我去上课了。), cấu trúc “太……了” (太冷了！), miêu tả thời tiết (今天下雨了。) và miêu tả tình trạng bệnh tật (我病了，觉得很冷。)."],"workbook":{"exercisesNote":"SBT Bài 12 (tr. 84–92): Tiểu Ngữ giảng đường — Ngữ âm (1. Phân biệt thanh điệu; 2. Nghe âm tiết ghép từ) + Đề luyện mô phỏng 模拟测练 (20 câu: Nghe 1–10, Đọc hiểu 11–20).","answerKeyNote":"语音 1 (Phân biệt thanh điệu): (1) B shuì | (2) A wèntí | (3) B fēicháng | (4) C duìbuqǐ.\n语音 2 (Nghe âm tiết ghép từ): 你好(1) · 老师(4) · 谢谢(6) · 孩子(5) · 名字(2) · 中国(3).\n模拟测练 — Nghe (1–10): P1: 1.A 2.C 3.B | P2: 4.C 5.B | P3: 6.D 7.C 8.B | P4: 9.A 10.B.\n模拟测练 — Đọc (11–20): P1: 11.D 12.B 13.C | P2: 14.B 15.A 16.C | P3: 17.B 18.A | P4: 19.A 20.A.","transcriptNote":""}},"13":{"pages":"95–102","titleZh":"请给我一杯茶","titlePy":"Qǐng gěi wǒ yì bēi chá","titleVi":"Cho tôi một cốc trà","goals":["Có thể nghe hiểu và sử dụng được câu có hai tân ngữ (1) để biểu thị việc hỏi người khác hoặc đưa cho người khác vật gì đó...","Nắm vững cách sử dụng của động từ năng nguyện “可以”.","Nắm vững cách sử dụng của cấu trúc “động từ + 一下”.","Hiểu về các mẫu câu thường dùng khi gọi đồ ăn."],"words":[{"zh":"可以","py":"kěyǐ","vi":"có thể, được (cho phép làm gì)","pos":"đtnn."},{"zh":"再","py":"zài","vi":"lại, thêm lần nữa","pos":"phó."},{"zh":"问题","py":"wèntí","vi":"câu hỏi, vấn đề","pos":"dt."},{"zh":"卖","py":"mài","vi":"bán","pos":"đgt."},{"zh":"打电话","py":"dǎ diànhuà","vi":"gọi điện thoại","pos":"đgt."},{"zh":"一下","py":"yíxià","vi":"một chút, thử (dùng sau động từ, biểu thị hành động xảy ra nhanh hoặc thử làm)","pos":"sl."},{"zh":"服务员","py":"fúwùyuán","vi":"nhân viên phục vụ, người phục vụ","pos":"dt."},{"zh":"女士","py":"nǚshì","vi":"bà, cô, quý bà, quý cô","pos":"dt."},{"zh":"请","py":"qǐng","vi":"mời, xin, hãy","pos":"đgt."},{"zh":"坐","py":"zuò","vi":"ngồi","pos":"đgt."},{"zh":"给","py":"gěi","vi":"đưa cho, cho","pos":"đgt."},{"zh":"杯","py":"bēi","vi":"ly, cốc, tách","pos":"dt."},{"zh":"要","py":"yào","vi":"cần, muốn","pos":"đgt."},{"zh":"早饭","py":"zǎofàn","vi":"bữa sáng","pos":"dt."},{"zh":"这个","py":"zhège","vi":"cái này","pos":"đt."},{"zh":"面包","py":"miànbāo","vi":"bánh mì","pos":"dt."},{"zh":"鸡蛋","py":"jīdàn","vi":"trứng gà","pos":"dt."},{"zh":"先生","py":"xiānsheng","vi":"anh, ông, ngài, quý ông","pos":"dt."},{"zh":"一半","py":"yíbàn","vi":"một nửa","pos":"số."},{"zh":"茶","py":"chá","vi":"trà, chè","pos":"dt."}],"dialog":[{"section":"Bài khóa 1","context":"Bạch Gia Nguyệt hỏi bài cô Vương ở trong lớp sau khi tan học.","audio":"13-1.mp3","speaker":"A","name":"白家月","zh":"王老师，我可以再问您一个问题吗？","py":"Wáng lǎoshī, wǒ kěyǐ zài wèn nín yí gè wèntí ma?","vi":"Thưa cô Vương, em có thể hỏi thêm cô một câu nữa không ạ?"},{"section":"Bài khóa 1","context":"","audio":"13-1.mp3","speaker":"B","name":"王一飞","zh":"可以。你有什么问题？","py":"Kěyǐ. Nǐ yǒu shénme wèntí?","vi":"Được chứ. Em có vấn đề gì nào?"},{"section":"Bài khóa 1","context":"","audio":"13-1.mp3","speaker":"A","name":"白家月","zh":"那个小店卖不卖手机？","py":"Nàge xiǎo diàn mài bu mài shǒujī?","vi":"Cửa hàng nhỏ kia có bán điện thoại di động không ạ?"},{"section":"Bài khóa 1","context":"","audio":"13-1.mp3","speaker":"B","name":"王一飞","zh":"我不知道。你可以打电话问一下。","py":"Wǒ bù zhīdào. Nǐ kěyǐ dǎ diànhuà wèn yíxià.","vi":"Cô không biết. Em có thể gọi điện thoại hỏi xem."},{"section":"Bài khóa 2","context":"Vương Nhất Tuyết muốn ăn sáng ở trong quán cà phê.","audio":"13-3.mp3","speaker":"A","name":"服务员","zh":"女士，请坐！您喝什么？","py":"Nǚshì, qǐng zuò! Nín hē shénme?","vi":"Mời cô ngồi! Cô uống gì ạ?"},{"section":"Bài khóa 2","context":"","audio":"13-3.mp3","speaker":"B","name":"王一雪","zh":"我看一下。请给我一杯牛奶。","py":"Wǒ kàn yíxià. Qǐng gěi wǒ yì bēi niúnǎi.","vi":"Để tôi xem một chút. Cho tôi một cốc sữa."},{"section":"Bài khóa 2","context":"","audio":"13-3.mp3","speaker":"A","name":"服务员","zh":"好的。您还要什么？","py":"Hǎo de. Nín hái yào shénme?","vi":"Vâng. Cô còn dùng thêm gì nữa không?"},{"section":"Bài khóa 2","context":"","audio":"13-3.mp3","speaker":"B","name":"王一雪","zh":"我还没吃早饭，再要这个面包和鸡蛋吧。","py":"Wǒ hái méi chī zǎofàn, zài yào zhège miànbāo hé jīdàn ba.","vi":"Tôi vẫn chưa ăn sáng, cho tôi cái bánh mì này và trứng nhé."},{"section":"Bài khóa 3","context":"Lưu Minh đang gọi món ăn ở nhà hàng.","audio":"13-5.mp3","speaker":"A","name":"服务员","zh":"先生，请坐！您要什么？","py":"Xiānsheng, qǐng zuò! Nín yào shénme?","vi":"Mời anh ngồi! Anh cần gì ạ?"},{"section":"Bài khóa 3","context":"","audio":"13-5.mp3","speaker":"B","name":"刘明","zh":"我要一斤饺子。","py":"Wǒ yào yì jīn jiǎozi.","vi":"Cho tôi một cân sủi cảo."},{"section":"Bài khóa 3","context":"","audio":"13-5.mp3","speaker":"A","name":"服务员","zh":"好的。一斤饺子40个。","py":"Hǎo de. Yì jīn jiǎozi sìshí gè.","vi":"Vâng ạ. Một cân sủi cảo có 40 cái."},{"section":"Bài khóa 3","context":"","audio":"13-5.mp3","speaker":"B","name":"刘明","zh":"40个太多了，我要一半吧。","py":"Sìshí gè tài duō le, wǒ yào yíbàn ba.","vi":"40 cái thì nhiều quá, tôi lấy nửa cân thôi nhé."},{"section":"Bài khóa 3","context":"","audio":"13-5.mp3","speaker":"A","name":"服务员","zh":"半斤20个。您想喝什么？","py":"Bàn jīn èrshí gè. Nín xiǎng hē shénme?","vi":"Nửa cân là 20 cái. Anh muốn uống gì không ạ?"},{"section":"Bài khóa 3","context":"","audio":"13-5.mp3","speaker":"B","name":"刘明","zh":"请给我一杯茶吧。","py":"Qǐng gěi wǒ yì bēi chá ba.","vi":"Cho tôi một cốc trà nhé."}],"dialogQuestions":[],"grammar":{"g1":{"han":"可以","py":"kěyǐ","title":"1. Động từ năng nguyện “可以”","explain":"Động từ năng nguyện “可以” được đặt trước động từ để biểu thị khả năng, năng lực hoặc sự cho phép.","examples":[{"zh":"我可以再问您一个问题吗？","py":"Wǒ kěyǐ zài wèn nín yí gè wèntí ma?","vi":"Em có thể hỏi thêm cô một câu nữa không ạ?","hl":"可以"},{"zh":"你们可以看这本书。","py":"Nǐmen kěyǐ kàn zhè běn shū.","vi":"Các bạn có thể xem cuốn sách này.","hl":"可以"},{"zh":"A：我可以坐吗？ B：可以，请坐！","py":"A: Wǒ kěyǐ zuò ma? B: Kěyǐ, qǐng zuò!","vi":"A: Tôi có thể ngồi không? B: Được, mời ngồi!","hl":"可以"}],"struct":"Chủ ngữ + 可以 + Động từ (+ Tân ngữ)","note":"Thường dùng trong câu hỏi xin phép “…可以…吗？” và câu trả lời cho phép “可以”."},"g2":{"han":"一下","py":"yíxià","title":"2. Cấu trúc “động từ + 一下”","explain":"Cấu trúc “động từ + 一下” trong bài này dùng để biểu thị việc thực hiện hành động một lần hoặc thử làm việc gì đó, hành động diễn ra trong thời gian ngắn.","examples":[{"zh":"你可以打电话问一下。","py":"Nǐ kěyǐ dǎ diànhuà wèn yíxià.","vi":"Em có thể gọi điện thoại hỏi xem một chút.","hl":"问一下"},{"zh":"请休息一下。","py":"Qǐng xiūxi yíxià.","vi":"Xin hãy nghỉ ngơi một chút.","hl":"休息一下"},{"zh":"你看一下吧。","py":"Nǐ kàn yíxià ba.","vi":"Bạn xem một chút đi.","hl":"看一下"}],"struct":"Động từ + 一下","note":"Dùng sau động từ cũng giúp ngữ khí câu nói trở nên nhẹ nhàng, lịch sự hơn."},"g3":{"han":"给/问","py":"gěi / wèn","title":"3. Câu có hai tân ngữ (1)","explain":"Câu có hai tân ngữ là câu mà một động từ mang hai tân ngữ. Trong quyển sách này, chúng ta học câu có hai tân ngữ được tạo bởi động từ “给” và “问”.","examples":[{"zh":"请给我一杯牛奶。","py":"Qǐng gěi wǒ yì bēi niúnǎi.","vi":"Xin cho tôi một cốc sữa.","hl":"给我一杯牛奶"},{"zh":"白家月给安妮一个苹果。","py":"Bái Jiāyuè gěi Ānnī yí gè píngguǒ.","vi":"Bạch Gia Nguyệt đưa cho Annie một quả táo.","hl":"给安妮一个苹果"},{"zh":"我问老师两个问题。","py":"Wǒ wèn lǎoshī liǎng gè wèntí.","vi":"Tôi hỏi cô giáo hai câu hỏi.","hl":"问老师两个问题"}],"struct":"Chủ ngữ + 给 / 问 + Tân ngữ 1 (người) + Tân ngữ 2 (vật / việc)","note":"Tân ngữ chỉ người luôn đứng trước, tân ngữ chỉ sự vật/vấn đề đứng sau."}},"grammarQuiz":[{"id":"hsk1_b13_q1","qtype":"fill","prompt":"选词填空 · Chọn từ thích hợp điền vào chỗ trống (tr.101):","q":"（1）请 ______ 我一杯热水。","opts":[{"t":"一下","ok":false},{"t":"可以","ok":false},{"t":"给","ok":true},{"t":"问题","ok":false},{"t":"要","ok":false}],"exp":"Đáp án C (给): Câu có hai tân ngữ với động từ 给 (请给我一杯热水 — Xin cho tôi một cốc nước nóng)."},{"id":"hsk1_b13_q2","qtype":"fill","prompt":"选词填空 · Chọn từ thích hợp điền vào chỗ trống (tr.101):","q":"（2）我们 ______ 一斤饺子。","opts":[{"t":"一下","ok":false},{"t":"可以","ok":false},{"t":"给","ok":false},{"t":"问题","ok":false},{"t":"要","ok":true}],"exp":"Đáp án E (要): Chúng tôi lấy/gọi một cân sủi cảo (我们要一斤饺子)."},{"id":"hsk1_b13_q3","qtype":"fill","prompt":"选词填空 · Chọn từ thích hợp điền vào chỗ trống (tr.101):","q":"（3a）A：我 ______ 坐这儿吗？ B：没问题，请坐。","opts":[{"t":"一下","ok":false},{"t":"可以","ok":true},{"t":"给","ok":false},{"t":"问题","ok":false},{"t":"要","ok":false}],"exp":"Đáp án B (可以): Dùng động từ năng nguyện 可以 để xin phép (我可以坐这儿吗？ — Tôi có thể ngồi ở đây không?)."},{"id":"hsk1_b13_q4","qtype":"fill","prompt":"选词填空 · Chọn từ thích hợp điền vào chỗ trống (tr.101):","q":"（3b）A：我可以坐这儿吗？ B：没 ______ ，请坐。","opts":[{"t":"一下","ok":false},{"t":"可以","ok":false},{"t":"给","ok":false},{"t":"问题","ok":true},{"t":"要","ok":false}],"exp":"Đáp án D (问题): 没问题 nghĩa là “không vấn đề gì” (没问题，请坐)."},{"id":"hsk1_b13_q5","qtype":"fill","prompt":"选词填空 · Chọn từ thích hợp điền vào chỗ trống (tr.101):","q":"（4）A：这个商店卖不卖手机？ B：你可以去问 ______ 。","opts":[{"t":"一下","ok":true},{"t":"可以","ok":false},{"t":"给","ok":false},{"t":"问题","ok":false},{"t":"要","ok":false}],"exp":"Đáp án A (一下): Cấu trúc Động từ + 一下 (去问一下 — đi hỏi thử một chút)."}],"chars":["可","以","再","问","题","卖","打","请","坐","给","杯","要","早","饭","面","包","鸡","蛋","半","茶"],"rhyme":null,"notes":["Câu hỏi thảo luận Bài khóa 1 (tr.96): (1) 白家月还有什么问题？ (Bạch Gia Nguyệt còn có câu hỏi gì vậy?) · (2) 王老师对白家月说什么了？ (Cô Vương đã nói gì với Bạch Gia Nguyệt?)","Câu hỏi thảo luận Bài khóa 2 (tr.98): (1) 服务员问王一雪什么问题了？ (Nhân viên phục vụ hỏi Vương Nhất Tuyết vấn đề gì vậy?) · (2) 王一雪吃早饭了吗？ (Vương Nhất Tuyết đã ăn sáng chưa?)","Câu hỏi thảo luận Bài khóa 3 (tr.100): (1) 刘明想要多少饺子？ (Lưu Minh muốn gọi bao nhiêu sủi cảo?) · (2) 刘明要米饭了吗？ (Lưu Minh có gọi cơm trắng không?)","Hoạt động trên lớp (tr.102): Ba người một nhóm, một người đóng vai phục vụ, hai người còn lại đóng vai khách hàng, thực hiện việc gọi món trong quán cà phê.","小语的彩蛋 · Món quà của Tiểu Ngữ 13-1 (tr.102): 中国茶 — Trà Trung Quốc."],"workbook":{"exercisesNote":"SBT Bài 13 (tr. 93–101): Tiểu Ngữ giảng đường — Ngữ âm (1. Phân biệt thanh điệu; 2. Nghe âm tiết ghép từ) + Đề luyện mô phỏng 模拟测练 (20 câu: Nghe 1–10, Đọc hiểu 11–20).","answerKeyNote":"语音 1 (Phân biệt thanh điệu): (1) B shuǐguǒ | (2) A xuéxí | (3) B xiě Hànzì | (4) C zhǎo tóngxué.\n语音 2 (Nghe âm tiết ghép từ): 你好(1) · 饺子(5) · 公司(2) · 朋友(6) · 先生(3) · 工作(4).\n模拟测练 — Nghe (1–10): P1: 1.C 2.A 3.C | P2: 4.C 5.C | P3: 6.C 7.D 8.B | P4: 9.B 10.A.\n模拟测练 — Đọc (11–20): P1: 11.B 12.D 13.C | P2: 14.C 15.A 16.B | P3: 17.B 18.A | P4: 19.C 20.A.","transcriptNote":""}},"14":{"pages":"103–111","titleZh":"我看了一个电影","titlePy":"Wǒ kànle yí gè diànyǐng","titleVi":"Mình đã xem một bộ phim","goals":["Có thể nghe hiểu và sử dụng được trợ từ động thái “了 (2)” để biểu thị hành động đã xảy ra hoặc đã hoàn thành.","Nắm vững cách dùng của phó từ chỉ phạm vi “都”.","Nắm vững cách dùng cơ bản của một số từ li hợp.","Hiểu và có thể miêu tả được tình hình học tập."],"words":[{"zh":"上","py":"shàng","vi":"lên (xe, tàu...)","pos":"đgt."},{"zh":"火车","py":"huǒchē","vi":"tàu, tàu hoả, xe lửa","pos":"dt."},{"zh":"中午","py":"zhōngwǔ","vi":"buổi trưa","pos":"dt."},{"zh":"开","py":"kāi","vi":"lái, chạy, khởi hành (phương tiện giao thông)","pos":"đgt."},{"zh":"有些","py":"yǒuxiē","vi":"có một số, có một vài","pos":"đt."},{"zh":"有的","py":"yǒude","vi":"có người, có cái","pos":"đt."},{"zh":"了","py":"le","vi":"dùng sau động từ chỉ sự hoàn thành của động tác","pos":"trợ."},{"zh":"写","py":"xiě","vi":"viết","pos":"đgt."},{"zh":"都","py":"dōu","vi":"đều","pos":"phó."},{"zh":"听见","py":"tīngjiàn","vi":"nghe thấy","pos":"đgt."},{"zh":"不要","py":"búyào","vi":"đừng, không được","pos":"phó."},{"zh":"说话","py":"shuōhuà","vi":"nói chuyện","pos":"đgt."},{"zh":"听","py":"tīng","vi":"nghe","pos":"đgt."},{"zh":"哪些","py":"nǎxiē","vi":"những... nào","pos":"đt."},{"zh":"字","py":"zì","vi":"chữ","pos":"dt."},{"zh":"汉语","py":"Hànyǔ","vi":"tiếng Trung Quốc, tiếng Hán","pos":"dt. riêng"},{"zh":"汉字","py":"Hànzì","vi":"chữ Hán","pos":"dt. riêng"},{"zh":"明年","py":"míngnián","vi":"sang năm, năm tới","pos":"dt."},{"zh":"上","py":"shàng","vi":"lên, bắt đầu (làm gì đó vào thời gian cố định)","pos":"đgt."},{"zh":"中学","py":"zhōngxué","vi":"trường trung học, trung học","pos":"dt."},{"zh":"小学","py":"xiǎoxué","vi":"trường tiểu học, tiểu học","pos":"dt."},{"zh":"中学生","py":"zhōngxuéshēng","vi":"học sinh trung học, học sinh cấp hai","pos":"dt."},{"zh":"小学生","py":"xiǎoxuéshēng","vi":"học sinh tiểu học, học sinh cấp một","pos":"dt."},{"zh":"上学","py":"shàngxué","vi":"đi học, bắt đầu đi học","pos":"đgt."},{"zh":"他们","py":"tāmen","vi":"họ, chúng, bọn họ, các anh ấy, các em ấy...","pos":"đt."},{"zh":"她们","py":"tāmen","vi":"họ, chúng, bọn họ, các chị ấy, các em ấy...","pos":"đt."},{"zh":"它们","py":"tāmen","vi":"chúng (đại từ nhân xưng ngôi thứ ba số nhiều, chỉ vật)","pos":"đt."},{"zh":"晚","py":"wǎn","vi":"muộn, trễ","pos":"tt."}],"dialog":[{"section":"Bài khóa 1","context":"Bạch Gia Nguyệt và Trần Thiên Trung đang thảo luận về chuyến du lịch ngoại khoá lần trước ở trong lớp sau giờ tan học.","audio":"14-1.mp3","speaker":"A","name":"白家月","zh":"你们上火车后看见王老师了吗？","py":"Nǐmen shàng huǒchē hòu kànjiàn Wáng lǎoshī le ma?","vi":"Sau khi lên tàu các bạn có nhìn thấy cô Vương không?"},{"section":"Bài khóa 1","context":"","audio":"14-1.mp3","speaker":"B","name":"陈天中","zh":"没看见。中午车开后，有些人在看书，有些人睡觉了。","py":"Méi kànjiàn. Zhōngwǔ chē kāi hòu, yǒuxiē rén zài kàn shū, yǒuxiē rén shuìjiào le.","vi":"Không nhìn thấy đâu. Buổi trưa, sau khi tàu chạy, có một số người đọc sách, một số người ngủ."},{"section":"Bài khóa 1","context":"","audio":"14-1.mp3","speaker":"A","name":"白家月","zh":"你呢？","py":"Nǐ ne?","vi":"Còn bạn thì sao?"},{"section":"Bài khóa 1","context":"","audio":"14-1.mp3","speaker":"B","name":"陈天中","zh":"我看了一个电影。","py":"Wǒ kànle yí gè diànyǐng.","vi":"Mình đã xem một bộ phim."},{"section":"Bài khóa 2","context":"Cô Vương Nhất Phi hỏi thăm tình hình học tập của học sinh ở trong lớp học.","audio":"14-3.mp3","speaker":"A","name":"王一飞","zh":"你们会说汉语了，也会写汉字了吗？","py":"Nǐmen huì shuō Hànyǔ le, yě huì xiě Hànzì le ma?","vi":"Các em đã biết nói tiếng Trung Quốc rồi, cũng đã biết viết chữ Hán rồi phải không?"},{"section":"Bài khóa 2","context":"","audio":"14-3.mp3","speaker":"B","name":"白家月","zh":"我们都会写了。","py":"Wǒmen dōu huì xiě le.","vi":"Chúng em đều biết viết rồi ạ."},{"section":"Bài khóa 2","context":"","audio":"14-3.mp3","speaker":"C","name":"陈天中","zh":"老师，我听不见。","py":"Lǎoshī, wǒ tīng bú jiàn.","vi":"Thưa cô, em không nghe thấy ạ."},{"section":"Bài khóa 2","context":"","audio":"14-3.mp3","speaker":"A","name":"王一飞","zh":"请大家不要说话！请听老师的问题：你们都会写哪些汉字了？","py":"Qǐng dàjiā búyào shuōhuà! Qǐng tīng lǎoshī de wèntí: Nǐmen dōu huì xiě nǎxiē Hànzì le?","vi":"Mọi người đừng nói chuyện! Hãy lắng nghe câu hỏi của cô: Các em đã biết viết những chữ Hán nào rồi?"},{"section":"Bài khóa 2","context":"","audio":"14-3.mp3","speaker":"C","name":"陈天中","zh":"我会写这些字了，您看！","py":"Wǒ huì xiě zhèxiē zì le, nín kàn!","vi":"Cô xem này, em đã biết viết những chữ này rồi!"},{"section":"Bài khóa 3","context":"Lưu Minh và Vương Nhất Tuyết đang trò chuyện về tình hình học tập của các con ở trong nhà.","audio":"14-5.mp3","speaker":"A","name":"刘明","zh":"明年女儿上中学。","py":"Míngnián nǚ\u0027ér shàng zhōngxué.","vi":"Sang năm con gái lên trung học."},{"section":"Bài khóa 3","context":"","audio":"14-5.mp3","speaker":"B","name":"王一雪","zh":"对。儿子也上小学了。","py":"Duì. Érzi yě shàng xiǎoxué le.","vi":"Đúng vậy. Con trai cũng lên tiểu học."},{"section":"Bài khóa 3","context":"","audio":"14-5.mp3","speaker":"A","name":"刘明","zh":"我们家有了一个中学生。","py":"Wǒmen jiā yǒule yí gè zhōngxuéshēng.","vi":"Nhà mình có một học sinh trung học rồi."},{"section":"Bài khóa 3","context":"","audio":"14-5.mp3","speaker":"B","name":"王一雪","zh":"还有了一个小学生。","py":"Hái yǒule yí gè xiǎoxuéshēng.","vi":"Còn có thêm một học sinh tiểu học nữa."},{"section":"Bài khóa 3","context":"","audio":"14-5.mp3","speaker":"A","name":"刘明","zh":"上学后，他们都忙了。","py":"Shàngxué hòu, tāmen dōu máng le.","vi":"Sau khi vào học, các con đều bận rộn cả."},{"section":"Bài khóa 3","context":"","audio":"14-5.mp3","speaker":"B","name":"王一雪","zh":"是的。太晚了，睡觉吧。","py":"Shì de. Tài wǎn le, shuìjiào ba.","vi":"Đúng vậy. Muộn quá rồi, đi ngủ thôi."}],"dialogQuestions":[],"grammar":{"g1":{"han":"了","py":"le","title":"1. Trợ từ động thái “了 (2)”","explain":"Trợ từ động thái “了 (2)” đứng sau động từ để biểu thị hành động đã xảy ra hoặc đã hoàn thành. Khi phủ định dùng “没”, bỏ “了”.","examples":[{"zh":"我看了一个电影。","py":"Wǒ kànle yí gè diànyǐng.","vi":"Mình đã xem một bộ phim.","hl":"了"},{"zh":"我买了一个新电脑。","py":"Wǒ mǎile yí gè xīn diànnǎo.","vi":"Tôi đã mua một chiếc máy tính mới.","hl":"了"},{"zh":"我昨天没去商店买东西。","py":"Wǒ zuótiān méi qù shāngdiàn mǎi dōngxi.","vi":"Hôm qua tôi không đi cửa hàng mua đồ.","hl":"没"}],"struct":"Khẳng định: Động từ + 了 (+ Tân ngữ) | Phủ định: 没 + Động từ (+ Tân ngữ)","note":"Hoàn thành hội thoại (tr.105): (1) A: 你去哪儿(了)？ B: 我今天有课，去学校上(了)课，还在那儿吃(了)午饭。 (2) A: 我昨天看(了)电影，(没)去超市。你呢？ B: 我昨天去(了)超市，(没)看电影。"},"g2":{"han":"离合词","py":"líhécí","title":"2. Từ li hợp (1)","explain":"Các từ như “上课”, “下课”, “上班”, “下班”, “说话”, “读书”, “睡觉”, “看病”, “生病”... trong quyển sách này là cấu trúc động từ đặc biệt, khi sử dụng có thể tách ra hoặc hợp lại. Khi hợp lại sẽ là từ, khi thêm các thành phần khác vào giữa thì trở thành cụm từ, do vậy được gọi là từ li hợp. Khi các từ li hợp tách ra, chỉ có một số thành phần có thể chèn vào giữa.","examples":[{"zh":"睡觉 → 睡了觉；睡了一觉","py":"shuìjiào → shuìle jiào; shuìle yí jiào","vi":"ngủ → đã ngủ; đã ngủ một giấc","hl":"睡了觉"},{"zh":"上课 → 上了课；上中文课","py":"shàngkè → shàngle kè; shàng Zhōngwén kè","vi":"lên lớp → đã lên lớp; học giờ tiếng Trung","hl":"上了课"},{"zh":"下班 → 下了班","py":"xiàbān → xiàle bān","vi":"tan làm → đã tan làm","hl":"下了班"},{"zh":"生病 → 生了病；生了大病","py":"shēngbìng → shēngle bìng; shēngle dà bìng","vi":"bị ốm → đã bị ốm; đã bị ốm nặng","hl":"生了病"},{"zh":"说话 → 说了话；说了很多话","py":"shuōhuà → shuōle huà; shuōle hěn duō huà","vi":"nói chuyện → đã nói chuyện; đã nói rất nhiều chuyện","hl":"说了话"}],"struct":"Hợp (AB) ↔ Tách (A + 了 / định ngữ / bổ ngữ + B)","note":"Trợ từ động thái “了” chèn vào giữa động từ và tân ngữ của từ li hợp (ví dụ: 睡了觉, 上了课)."},"g3":{"han":"都","py":"dōu","title":"3. Phó từ chỉ phạm vi “都”","explain":"Phó từ chỉ phạm vi “都” dùng để biểu thị toàn bộ, tất cả. Đối tượng được bao quát đứng trước “都”. Khi phủ định, từ phủ định đứng sau “都”.","examples":[{"zh":"我们都会写了。","py":"Wǒmen dōu huì xiě le.","vi":"Chúng em đều biết viết rồi ạ.","hl":"都"},{"zh":"我和我的朋友们都去。","py":"Wǒ hé wǒ de péngyoumen dōu qù.","vi":"Tôi và các bạn của tôi đều đi.","hl":"都"},{"zh":"同学们都没听见。","py":"Tóngxuémen dōu méi tīngjiàn.","vi":"Các bạn học đều không nghe thấy.","hl":"都没"}],"struct":"Chủ ngữ (số nhiều) + 都 (+ 不 / 没) + Động từ / Tính từ","note":"Lưu ý: “都不/都没” diễn tả “tất cả đều không” (phủ định toàn bộ)."}},"grammarQuiz":[{"id":"hsk1_b14_q1","qtype":"fill","prompt":"选词填空 · Chọn từ thích hợp điền vào chỗ trống (tr.110):","q":"（1）我写 ______ 很多汉字。","opts":[{"t":"上学","ok":false},{"t":"了","ok":true},{"t":"都","ok":false},{"t":"听见","ok":false},{"t":"有的","ok":false}],"exp":"Đáp án B (了): Trợ từ động thái 了 đứng sau động từ 写 biểu thị động tác đã hoàn thành (我写了很多汉字)."},{"id":"hsk1_b14_q2","qtype":"fill","prompt":"选词填空 · Chọn từ thích hợp điền vào chỗ trống (tr.110):","q":"（2）他没 ______ 老师说什么。","opts":[{"t":"上学","ok":false},{"t":"了","ok":false},{"t":"都","ok":false},{"t":"听见","ok":true},{"t":"有的","ok":false}],"exp":"Đáp án D (听见): Anh ấy không nghe thấy cô giáo nói gì (他没听见老师说什么)."},{"id":"hsk1_b14_q3","qtype":"fill","prompt":"选词填空 · Chọn từ thích hợp điền vào chỗ trống (tr.110):","q":"（3）白家月：你们昨天在车上做什么了？ 陈天中：我看了一本书， ______ 人在睡觉。","opts":[{"t":"上学","ok":false},{"t":"了","ok":false},{"t":"都","ok":false},{"t":"听见","ok":false},{"t":"有的","ok":true}],"exp":"Đáp án E (有的): 有的人 ở đây bằng với 有些人 — có một số người đang ngủ."},{"id":"hsk1_b14_q4","qtype":"fill","prompt":"选词填空 · Chọn từ thích hợp điền vào chỗ trống (tr.110):","q":"（4a）刘明：明年 ______ 后，他们都忙了。 王一雪：是的。","opts":[{"t":"上学","ok":true},{"t":"了","ok":false},{"t":"都","ok":false},{"t":"听见","ok":false},{"t":"有的","ok":false}],"exp":"Đáp án A (上学): 明年上学后 — Sau khi bắt đầu đi học vào năm tới."},{"id":"hsk1_b14_q5","qtype":"fill","prompt":"选词填空 · Chọn từ thích hợp điền vào chỗ trống (tr.110):","q":"（4b）刘明：明年上学后，他们 ______ 忙了。 王一雪：是的。","opts":[{"t":"上学","ok":false},{"t":"了","ok":false},{"t":"都","ok":true},{"t":"听见","ok":false},{"t":"有的","ok":false}],"exp":"Đáp án C (都): Phó từ chỉ phạm vi 都 đặt sau chủ ngữ số nhiều 他们 (他们都忙了 — các con đều bận rồi)."}],"chars":["上","火","车","中","午","开","些","写","都","听","话","字","汉","语","明","年","他","她","它","晚"],"rhyme":null,"notes":["小语助力 · Tiểu Ngữ giúp sức (tr.104): 本课“有些”也可以说“有的”。 — Trong bài này, “有些” cũng có thể nói là “有的”.","小语助力 · Tiểu Ngữ giúp sức (tr.109): 还有两个近似的代词，一个是“她们”，指称自己和对方以外的若干女性；另一个是“它们”，指称不止一个的事物等。三个词读音一样，但所指意义不同。 — Còn có hai đại từ tương tự, một là “她们”, dùng để chỉ một nhóm nữ giới nhưng không bao gồm người nghe và người nói; đại từ còn lại là “它们”, dùng để chỉ nhiều hơn một sự vật. Ba từ này có cách đọc giống nhau nhưng nghĩa khác nhau.","Câu hỏi thảo luận Bài khóa 1 (tr.104): (1) 车开后，大家在做什么？ (Sau khi tàu chạy, mọi người làm gì?) · (2) 陈天中为什么没看见王老师？ (Tại sao Trần Thiên Trung không nhìn thấy cô Vương?)","Câu hỏi thảo luận Bài khóa 2 (tr.107): (1) 白家月会写汉字了吗？ (Bạch Gia Nguyệt đã biết viết chữ Hán chưa?) · (2) 陈天中会写汉字了吗？ (Trần Thiên Trung đã biết viết chữ Hán chưa?)","Câu hỏi thảo luận Bài khóa 3 (tr.110): (1) 明年女儿和儿子都上小学吗？ (Sang năm, con gái và con trai đều bắt đầu học tiểu học phải không?) · (2) 上学后，他们忙不忙？ (Sau khi vào học, các bạn ấy có bận không?)","Hoạt động trên lớp (tr.111): Hai người một nhóm, nói về những việc bạn đã làm vào thứ Bảy hoặc Chủ nhật tuần trước (Ví dụ của Tiểu Ngữ: 我星期六上午上了中文课，中午吃了饭后休息了一下，下午去商店买了一些东西，晚上和朋友吃了晚饭。……)."],"workbook":{"exercisesNote":"SBT Bài 14 (tr. 102–110): Tiểu Ngữ giảng đường — Ngữ âm (1. Nghe âm tiết ghép từ; 2. Nghe phân biệt ngữ điệu câu trần thuật A / nghi vấn B) + Đề luyện mô phỏng 模拟测练 (20 câu: Nghe 1–10, Đọc hiểu 11–20).","answerKeyNote":"语音 1 (Nghe âm tiết ghép từ): 你好(1) · 女儿(5) · 好玩儿(6) · 没关系(2) · 男朋友(3) · 不客气(4).\n语音 2 (Ngữ điệu — A trần thuật, B nghi vấn): (1) 你是学生吗？(B) | (2) 你是哪国人？(B) | (3) 我叫李文。(A) | (4) 今天我休息。(A) | (5) 谁是老师？(B) | (6) 我想去超市买东西。(A).\n模拟测练 — Nghe (1–10): P1: 1.C 2.C 3.B | P2: 4.C 5.B | P3: 6.D 7.B 8.C | P4: 9.A 10.A.\n模拟测练 — Đọc (11–20): P1: 11.C 12.B 13.D | P2: 14.B 15.A 16.C | P3: 17.B 18.A | P4: 19.C 20.A.","transcriptNote":""}},"15":{"pages":"112–121","titleZh":"大兴机场见！","titlePy":"Dàxīng Jīchǎng jiàn!","titleVi":"Hẹn gặp ở sân bay Đại Hưng!","goals":["Có thể nghe hiểu và sử dụng được các từ ngữ liên quan để diễn đạt ý định và kế hoạch du lịch.","Nắm vững câu ghép đẳng lập “……，还/也……”.","Hiểu về văn hoá bàn ăn và nghi lễ tiếp khách của Trung Quốc.","Hiểu về thủ đô Bắc Kinh của Trung Quốc."],"words":[{"zh":"爱","py":"ài","vi":"thích, yêu thích","pos":"đgt."},{"zh":"哪个","py":"nǎge","vi":"cái nào, nào","pos":"đt."},{"zh":"去年","py":"qùnián","vi":"năm ngoái","pos":"dt."},{"zh":"男朋友","py":"nánpéngyou","vi":"bạn trai, người yêu","pos":"dt."},{"zh":"几","py":"jǐ","vi":"vài, mấy","pos":"số."},{"zh":"年","py":"nián","vi":"năm","pos":"dt."},{"zh":"好玩儿","py":"hǎowánr","vi":"vui, thích, thú vị","pos":"tt."},{"zh":"西安","py":"Xī\u0027ān","vi":"Tây An","pos":"dt. riêng"},{"zh":"北京","py":"Běijīng","vi":"Bắc Kinh","pos":"dt. riêng"},{"zh":"飞机","py":"fēijī","vi":"máy bay","pos":"dt."},{"zh":"要","py":"yào","vi":"cần, mất (thời gian)","pos":"đgt."},{"zh":"小时","py":"xiǎoshí","vi":"tiếng đồng hồ, giờ","pos":"dt."},{"zh":"家人","py":"jiārén","vi":"người nhà","pos":"dt."},{"zh":"时间","py":"shíjiān","vi":"thời gian","pos":"dt."},{"zh":"机场","py":"jīchǎng","vi":"sân bay","pos":"dt."},{"zh":"接","py":"jiē","vi":"đón, tiếp đón","pos":"đgt."},{"zh":"住","py":"zhù","vi":"ở","pos":"đgt."},{"zh":"早","py":"zǎo","vi":"sớm","pos":"tt."},{"zh":"那","py":"nà","vi":"vậy thì, thế thì","pos":"liên."},{"zh":"大兴机场","py":"Dàxīng Jīchǎng","vi":"sân bay Đại Hưng","pos":"dt. riêng"}],"dialog":[{"section":"Bài khóa 1","context":"Lý Văn mời các bạn Trần Thiên Trung, Bạch Gia Nguyệt thưởng thức món ăn Trung Quốc tại nhà mình.","audio":"15-1.mp3","speaker":"A","name":"李文","zh":"你们爱吃哪个菜？","py":"Nǐmen ài chī nǎge cài?","vi":"Các bạn thích món ăn nào?"},{"section":"Bài khóa 1","context":"","audio":"15-1.mp3","speaker":"B","name":"白家月","zh":"我喜欢这个，也喜欢那个。","py":"Wǒ xǐhuan zhège, yě xǐhuan nàge.","vi":"Mình thích món này, cũng thích món kia nữa."},{"section":"Bài khóa 1","context":"","audio":"15-1.mp3","speaker":"C","name":"陈天中","zh":"这些菜都好吃，还很好看。","py":"Zhèxiē cài dōu hǎochī, hái hěn hǎokàn.","vi":"Những món ăn này đều ngon, còn rất đẹp mắt nữa."},{"section":"Bài khóa 1","context":"","audio":"15-1.mp3","speaker":"A","name":"李文","zh":"我爱吃中国菜，也喜欢做。大家多吃点儿。","py":"Wǒ ài chī Zhōngguócài, yě xǐhuan zuò. Dàjiā duō chī diǎnr.","vi":"Mình thích ăn món Trung Quốc, cũng rất thích nấu nữa. Mọi người ăn nhiều một chút nhé."},{"section":"Bài khóa 2","context":"Mọi người vừa ăn vừa thảo luận về kế hoạch kỳ nghỉ tại nhà Lý Văn.","audio":"15-3.mp3","speaker":"A","name":"李文","zh":"你们都想去哪儿？","py":"Nǐmen dōu xiǎng qù nǎr?","vi":"Các bạn đều muốn đi đâu vậy?"},{"section":"Bài khóa 2","context":"","audio":"15-3.mp3","speaker":"B","name":"安妮","zh":"去年我和男朋友去了西安，今年我想去北京。","py":"Qùnián wǒ hé nánpéngyou qùle Xī\u0027ān, jīnnián wǒ xiǎng qù Běijīng.","vi":"Năm ngoái mình và bạn trai đã đi Tây An, năm nay mình muốn đi Bắc Kinh."},{"section":"Bài khóa 2","context":"","audio":"15-3.mp3","speaker":"C","name":"白家月","zh":"前几年我去了西安，非常好玩儿。今年我也想去北京。","py":"Qián jǐ nián wǒ qùle Xī\u0027ān, fēicháng hǎowánr. Jīnnián wǒ yě xiǎng qù Běijīng.","vi":"Mấy năm trước mình đã đi Tây An, rất vui. Năm nay mình cũng muốn đi Bắc Kinh."},{"section":"Bài khóa 2","context":"","audio":"15-3.mp3","speaker":"A","name":"李文","zh":"我和王老师都是北京人，北京非常漂亮。","py":"Wǒ hé Wáng lǎoshī dōu shì Běijīng rén, Běijīng fēicháng piàoliang.","vi":"Mình và cô Vương đều là người Bắc Kinh, Bắc Kinh rất đẹp."},{"section":"Bài khóa 3","context":"Bạch Gia Nguyệt, Annie và cô Vương đang nói chuyện về việc đi du lịch Bắc Kinh ở bên ngoài lớp học.","audio":"15-5.mp3","speaker":"A","name":"王一飞","zh":"你们的飞机到北京要几个小时？","py":"Nǐmen de fēijī dào Běijīng yào jǐ gè xiǎoshí?","vi":"Chuyến bay của các em đến Bắc Kinh mất mấy tiếng?"},{"section":"Bài khóa 3","context":"","audio":"15-5.mp3","speaker":"B","name":"白家月","zh":"九个小时。","py":"Jiǔ gè xiǎoshí.","vi":"9 tiếng ạ."},{"section":"Bài khóa 3","context":"","audio":"15-5.mp3","speaker":"A","name":"王一飞","zh":"我家人都在北京，星期天我姐姐也有时间，她可以去机场接你们，你们也可以住我家。","py":"Wǒ jiārén dōu zài Běijīng, Xīngqītiān wǒ jiějie yě yǒu shíjiān, tā kěyǐ qù jīchǎng jiē nǐmen, nǐmen yě kěyǐ zhù wǒ jiā.","vi":"Người nhà cô đều ở Bắc Kinh, Chủ nhật chị gái cô cũng có thời gian, chị ấy có thể đi sân bay đón các em, các em cũng có thể ở nhà cô."},{"section":"Bài khóa 3","context":"","audio":"15-5.mp3","speaker":"C","name":"安妮","zh":"我们星期日早上八点到大兴机场，早不早？","py":"Wǒmen Xīngqīrì zǎoshang bā diǎn dào Dàxīng Jīchǎng, zǎo bu zǎo?","vi":"8 giờ sáng Chủ nhật chúng em đã đến sân bay Đại Hưng, có sớm không cô?"},{"section":"Bài khóa 3","context":"","audio":"15-5.mp3","speaker":"A","name":"王一飞","zh":"不早。","py":"Bù zǎo.","vi":"Không sớm đâu."},{"section":"Bài khóa 3","context":"","audio":"15-5.mp3","speaker":"B","name":"白家月","zh":"谢谢老师！那我们和您姐姐在大兴机场见！","py":"Xièxie lǎoshī! Nà wǒmen hé nín jiějie zài Dàxīng Jīchǎng jiàn!","vi":"Cảm ơn cô ạ! Vậy chúng em hẹn gặp chị cô ở sân bay Đại Hưng nhé!"}],"dialogQuestions":[],"grammar":{"g1":{"han":"还/也","py":"hái / yě","title":"1. Câu ghép đẳng lập “……，还/也……”","explain":"Câu ghép đẳng lập là câu được tạo bởi hai hay nhiều vế câu có liên quan về mặt lôgic và đối xứng với nhau về mặt cấu trúc. Trong quyển sách này giới thiệu câu ghép đẳng lập “……，还/也……”.","examples":[{"zh":"我喜欢这个，也喜欢那个。","py":"Wǒ xǐhuan zhège, yě xǐhuan nàge.","vi":"Mình thích món này, cũng thích món kia nữa.","hl":"也"},{"zh":"王老师是北京人，李文也是北京人。","py":"Wáng lǎoshī shì Běijīng rén, Lǐ Wén yě shì Běijīng rén.","vi":"Cô Vương là người Bắc Kinh, Lý Văn cũng là người Bắc Kinh.","hl":"也"},{"zh":"我喜欢喝中国茶，还喜欢吃中国菜。","py":"Wǒ xǐhuan hē Zhōngguó chá, hái xǐhuan chī Zhōngguócài.","vi":"Tôi thích uống trà Trung Quốc, còn thích ăn món Trung Quốc nữa.","hl":"还"}],"struct":"Vế câu 1，还 / 也 + Vế câu 2","note":"“还” thường dùng khi cùng một chủ ngữ bổ sung thêm ý/hành động; “也” dùng được cho cả cùng chủ ngữ lẫn khác chủ ngữ."}},"grammarQuiz":[{"id":"hsk1_b15_q1","qtype":"fill","prompt":"选词填空 · Chọn từ thích hợp điền vào chỗ trống (tr.118):","q":"（1）这本书有15课，我们 ______ 学了。","opts":[{"t":"爱","ok":false},{"t":"时间","ok":false},{"t":"早不早","ok":false},{"t":"都","ok":true},{"t":"飞机","ok":false}],"exp":"Đáp án D (都): Cuốn sách này có 15 bài, chúng tôi đều đã học rồi (我们都学了)."},{"id":"hsk1_b15_q2","qtype":"fill","prompt":"选词填空 · Chọn từ thích hợp điền vào chỗ trống (tr.118):","q":"（2）我的家人都 ______ 喝茶。","opts":[{"t":"爱","ok":true},{"t":"时间","ok":false},{"t":"早不早","ok":false},{"t":"都","ok":false},{"t":"飞机","ok":false}],"exp":"Đáp án A (爱): Người nhà tôi đều thích uống trà (我的家人都爱喝茶)."},{"id":"hsk1_b15_q3","qtype":"fill","prompt":"选词填空 · Chọn từ thích hợp điền vào chỗ trống (tr.118):","q":"（3）陈天中：我们明天晚上六点到，你觉得 ______ ？ 李文：不早。","opts":[{"t":"爱","ok":false},{"t":"时间","ok":false},{"t":"早不早","ok":true},{"t":"都","ok":false},{"t":"飞机","ok":false}],"exp":"Đáp án C (早不早): Câu trả lời là “不早” (không sớm), nên câu hỏi là “你觉得早不早？” (bạn thấy có sớm không?)."},{"id":"hsk1_b15_q4","qtype":"fill","prompt":"选词填空 · Chọn từ thích hợp điền vào chỗ trống (tr.118):","q":"（4a）王一飞：她们想坐 ______ 去北京，你们呢？ 陈天中：我们没有时间，不能出去玩。","opts":[{"t":"爱","ok":false},{"t":"时间","ok":false},{"t":"早不早","ok":false},{"t":"都","ok":false},{"t":"飞机","ok":true}],"exp":"Đáp án E (飞机): 坐飞机去北京 — đi máy bay đến Bắc Kinh."},{"id":"hsk1_b15_q5","qtype":"fill","prompt":"选词填空 · Chọn từ thích hợp điền vào chỗ trống (tr.118):","q":"（4b）王一飞：她们想坐飞机去北京，你们呢？ 陈天中：我们没有 ______ ，不能出去玩。","opts":[{"t":"爱","ok":false},{"t":"时间","ok":true},{"t":"早不早","ok":false},{"t":"都","ok":false},{"t":"飞机","ok":false}],"exp":"Đáp án B (时间): 我们没有时间 — chúng em không có thời gian."}],"chars":["爱","哪","去","年","男","几","玩","西","安","北","京","飞","机","时","间","场","接","住","早","那"],"rhyme":null,"notes":["小语助力 · Tiểu Ngữ giúp sức (tr.113): 劝饭是一种中式餐桌文化，体现了中国人的热情好客。 — Mời người khác ăn nhiều hơn là một nét văn hoá trên bàn ăn của Trung Quốc, thể hiện sự nhiệt tình và hiếu khách của người Trung Quốc.","Câu hỏi thảo luận Bài khóa 1 (tr.113): (1) 白家月爱吃哪个菜？ (Bạch Gia Nguyệt thích ăn món nào?) · (2) 李文做饭好吃不好吃？ (Lý Văn nấu ăn có ngon không?)","Câu hỏi thảo luận Bài khóa 2 (tr.115): (1) 安妮今年想去哪儿？ (Annie năm nay muốn đi đâu?) · (2) 前几年白家月去了哪儿？ (Mấy năm trước, Bạch Gia Nguyệt đã đi đâu?)","Câu hỏi thảo luận Bài khóa 3 (tr.117): (1) 大兴机场在哪儿？ (Sân bay Đại Hưng ở đâu?) · (2) 王老师的姐姐可以去接白家月和安妮吗？ (Chị gái của cô Vương có thể đi đón Bạch Gia Nguyệt và Annie không?)","Hoạt động trên lớp (tr.119): Ba người lần lượt đóng vai Lý Văn, Trần Thiên Trung và Bạch Gia Nguyệt. Lý Văn mời Trần Thiên Trung và Bạch Gia Nguyệt đến nhà chơi và cùng làm món ăn Trung Quốc.","小语的彩蛋 · Món quà của Tiểu Ngữ 15-1 (tr.119): 北京欢迎你 — Bắc Kinh chào đón bạn.","学习小结 · Tổng kết học tập Bài 13–15 (tr.120–121): Tự đánh giá từ ngữ đã nhớ/chưa nhớ và 8 nội dung trọng tâm: (1) Động từ năng nguyện “可以” (我可以吃吗？); (2) Cấu trúc “động từ + 一下” (看一下); (3) Câu có hai tân ngữ (1) (给我一杯水。); (4) Trợ từ động thái “了 (2)” (读了一本书); (5) Từ li hợp (1) (吃了饭，睡一觉); (6) Phó từ chỉ phạm vi “都” (我们都来了。); (7) Câu ghép đẳng lập “……，还/也……” (我喜欢看书，也喜欢看电影。); (8) Hiểu về văn hoá bàn ăn và nghi lễ tiếp khách của Trung Quốc (了解中国餐桌文化、待客礼仪。)."],"workbook":{"exercisesNote":"SBT Bài 15 (tr. 111–120): Tiểu Ngữ giảng đường — Ngữ âm (1. Nghe âm tiết ghép từ; 2. Nghe phân biệt ngữ điệu 4 loại câu: A trần thuật, B nghi vấn, C cảm thán, D cầu khiến) + Đề luyện mô phỏng 模拟测练 (20 câu: Nghe 1–10, Đọc hiểu 11–20).","answerKeyNote":"语音 1 (Nghe âm tiết ghép từ): 你好(1) · 说话(4) · 坐飞机(6) · 没看见(2) · 哪些人(3) · 什么时候(5).\n语音 2 (Ngữ điệu — A trần thuật, B nghi vấn, C cảm thán, D cầu khiến): (1) 你是学生吗？(B) | (2) 我爱吃水果。(A) | (3) 这件衣服真漂亮！(C) | (4) 你们去哪里？(B) | (5) 请坐。(D) | (6) 雨大吗？(B).\n模拟测练 — Nghe (1–10): P1: 1.A 2.B 3.C | P2: 4.A 5.C | P3: 6.B 7.D 8.C | P4: 9.A 10.B.\n模拟测练 — Đọc (11–20): P1: 11.D 12.B 13.C | P2: 14.B 15.A 16.C | P3: 17.B 18.A | P4: 19.C 20.A.","transcriptNote":""}},"mock":{"pages":"121–131 (SBT)","titleZh":"模拟测试 · HSK（一级）模拟试卷","titlePy":"Mónǐ cèshì · HSK (Yī jí) mónǐ shìjuàn","titleVi":"Đề thi thử HSK (Cấp 1) chính thức","goals":["Làm quen cấu trúc đề thi HSK (Cấp 1) chuẩn gồm 40 câu: Phần I Nghe hiểu (20 câu, ~12 phút + 3 phút điền phiếu trả lời) và Phần II Đọc hiểu (20 câu, 20 phút).","Luyện nghe 4 dạng bài (Câu 1–20) cùng file audio chính thức: 模拟测试——HSK(一级）模拟试卷 听力.mp3.","Luyện đọc hiểu tương tác toàn bộ Câu 26–40 (đối đáp tình huống, điền từ vào chỗ trống, đọc câu chọn đáp án đúng) kèm giải thích chi tiết.","Đối chiếu đầy đủ đáp án chính thức 40 câu theo SBT trang 28."],"words":[],"dialog":[{"section":"Hướng dẫn làm bài (SBT tr. 121)","context":"","audio":"模拟测试——HSK(一级）模拟试卷 听力.mp3","speaker":"Hướng dẫn","name":"Lưu ý phòng thi","zh":"一、HSK（一级）分两部分，共40题：1. 听力（20题，约12分钟）；2. 阅读（20题，20分钟）。二、听力结束后，有3分钟填写答题卡。三、全部考试约40分钟（含考生填写个人信息时间5分钟）。","py":"Yī, HSK (Yī jí) fēn liǎng bùfen, gòng 40 tí: 1. Tīnglì (20 tí, yuē 12 fēnzhōng); 2. Yuèdú (20 tí, 20 fēnzhōng). Èr, tīnglì jiéshù hòu, yǒu 3 fēnzhōng tiánxiě dátíkǎ. Sān, quánbù kǎoshì yuē 40 fēnzhōng (hán kǎoshēng tiánxiě gèrén xìnxī shíjiān 5 fēnzhōng).","vi":"1. HSK (Cấp 1) chia làm 2 phần, tổng cộng 40 câu: Nghe hiểu (20 câu, ~12 phút) và Đọc hiểu (20 câu, 20 phút). 2. Sau khi kết thúc phần Nghe có 3 phút điền phiếu trả lời. 3. Toàn bộ bài thi khoảng 40 phút (gồm 5 phút điền thông tin cá nhân)."},{"section":"Phần I · Nghe hiểu — Đoạn 1 (Câu 1–5, SBT tr. 122–123)","context":"","audio":"模拟测试——HSK(一级）模拟试卷 听力.mp3","speaker":"Đề Nghe","name":"Câu 1–5 (Chọn tranh A/B/C)","zh":"例如：A（书）| B（电脑）| C（苹果）✓\n1. A（包子）| B（茶）| C（饺子）\n2. A（看电视/足球）| B（洗碗）| C（画画儿）\n3. A（踢足球）| B（超市付款）| C（看书）\n4. A（钟表A）| B（钟表B）| C（钟表C）\n5. A（小男孩和小狗）| B（妈妈抱宝宝）| C（两个小朋友）","py":"","vi":"Nghe băng và chọn 1 trong 3 hình A, B, C tương ứng (xem hình minh họa gốc tại SBT tr. 122–123). Đáp án: 1.C · 2.A · 3.C · 4.B · 5.C."},{"section":"Phần I · Nghe hiểu — Đoạn 2 (Câu 6–10, SBT tr. 124)","context":"","audio":"模拟测试——HSK(一级）模拟试卷 听力.mp3","speaker":"Đề Nghe","name":"Câu 6–10 (Nghe câu hỏi, chọn đáp án)","zh":"例如：今天天气怎么样？ — A 在学习 | B 很好听 | C 非常热 ✓\n6. A 哪里 | B 打电话 | C 做饭好吃\n7. A 白天 | B 生病了 | C 水果店\n8. A 八元 | B 不是 | C 便宜\n9. A 去年 | B 很漂亮 | C 我弟弟\n10. A 没有 | B 再见 | C 不要","py":"Lìrú: Jīntiān tiānqì zěnmeyàng? — A zài xuéxí | B hěn hǎotīng | C fēicháng rè ✓\n6. A nǎlǐ | B dǎ diànhuà | C zuò fàn hǎochī\n7. A báitiān | B shēngbìng le | C shuǐguǒdiàn\n8. A bā yuán | B bú shì | C piányi\n9. A qùnián | B hěn piàoliang | C wǒ dìdi\n10. A méiyǒu | B zàijiàn | C búyào","vi":"Nghe câu hỏi và chọn phương án trả lời phù hợp A, B hoặc C. Đáp án: 6.B · 7.C · 8.B · 9.C · 10.A."},{"section":"Phần I · Nghe hiểu — Đoạn 3 (Câu 11–15, SBT tr. 125)","context":"","audio":"模拟测试——HSK(一级）模拟试卷 听力.mp3","speaker":"Đề Nghe","name":"Câu 11–15 (Nghe hội thoại, nối tranh A–F)","zh":"例如：女：你好！ 男：你好！很高兴认识你。→ [C]\n图片：A（医生打电话）| B（两把椅子）| C（两人握手）| D（在电影院看电影）| E（天气热吹风扇）| F（睡觉）","py":"Lìrú: Nǚ: Nǐ hǎo! Nán: Nǐ hǎo! Hěn gāoxìng rènshi nǐ. → [C]","vi":"Nghe đoạn hội thoại ngắn và ghép với tranh A–F tương ứng (xem tranh tại SBT tr. 125). Đáp án: 11.B · 12.D · 13.E · 14.A · 15.F."},{"section":"Phần I · Nghe hiểu — Đoạn 4 (Câu 16–20, SBT tr. 126)","context":"","audio":"模拟测试——HSK(一级）模拟试卷 听力.mp3","speaker":"Đề Nghe","name":"Câu 16–20 (Nghe đoạn ngắn, trả lời câu hỏi)","zh":"例如：下午我去超市，我想买一些水果。问：说话人下午去哪里？ — A 超市 ✓ | B 医院 | C 学校\n16. A 60岁 | B 60多岁 | C 70岁\n17. A 电脑 | B 杯子 | C 手机\n18. A 女儿 | B 妹妹 | C 高女士\n19. A 包子 | B 面包 | C 面条儿\n20. A 早上 | B 中午 | C 星期天","py":"Lìrú: Xiàwǔ wǒ qù chāoshì, wǒ xiǎng mǎi yìxiē shuǐguǒ. Wèn: Shuōhuàrén xiàwǔ qù nǎlǐ? — A chāoshì ✓ | B yīyuàn | C xuéxiào\n16. A 60 suì | B 60 duō suì | C 70 suì\n17. A diànnǎo | B bēizi | C shǒujī\n18. A nǚ\u0027ér | B mèimei | C Gāo nǚshì\n19. A bāozi | B miànbāo | C miàntiáor\n20. A zǎoshang | B zhōngwǔ | C Xīngqītiān","vi":"Nghe câu/đoạn ngắn và câu hỏi rồi chọn phương án đúng A, B hoặc C. Đáp án: 16.A · 17.C · 18.A · 19.B · 20.B."}],"dialogQuestions":[],"grammar":{"g1":{"han":"考纲","py":"kǎogāng","title":"Cấu trúc đề thi HSK (Cấp 1) — 40 câu","explain":"Đề thi HSK (Cấp 1) gồm 2 phần lớn, tổng cộng 40 câu (thời gian làm bài khoảng 40 phút gồm 5 phút điền thông tin cá nhân):\n• Phần I — Nghe hiểu (Câu 1–20, ~12 phút + 3 phút tô phiếu): Phần 1 (1–5) chọn tranh A/B/C; Phần 2 (6–10) nghe câu hỏi chọn câu trả lời A/B/C; Phần 3 (11–15) nghe hội thoại ghép tranh A–F; Phần 4 (16–20) nghe đoạn ngắn và câu hỏi chọn A/B/C.\n• Phần II — Đọc hiểu (Câu 21–40, 20 phút): Phần 1 (21–25) đọc câu ghép tranh A–F (tr. 128); Phần 2 (26–30) chọn câu đối đáp đúng A–F (tr. 129); Phần 3 (31–35) chọn từ điền chỗ trống A–F (tr. 130); Phần 4 (36–40) đọc câu chọn đáp án đúng A/B/C (tr. 131).","examples":[{"zh":"一、听力（20题，约12分钟）","py":"Yī, tīnglì (20 tí, yuē 12 fēnzhōng)","vi":"Phần I: Nghe hiểu (20 câu, khoảng 12 phút, cộng thêm 3 phút tô phiếu trả lời)."},{"zh":"二、阅读（20题，20分钟）","py":"Èr, yuèdú (20 tí, 20 fēnzhōng)","vi":"Phần II: Đọc hiểu (20 câu, 20 phút)."}],"note":"Trong ứng dụng này, toàn bộ Câu 26–40 của phần Đọc hiểu đã được số hóa thành bài trắc nghiệm tương tác ở tab Bài tập; Câu 21–25 (nối câu với tranh) được trình bày đầy đủ câu chữ và đáp án ngay bên dưới."},"g2":{"han":"阅读一","py":"yuèdú yī","title":"Đọc hiểu Phần 1 — Câu 21–25 (Ghép câu với tranh A–F, SBT tr. 128)","explain":"Đọc từng câu bên dưới và ghép với bức tranh phù hợp trong 6 tranh A–F ở SBT trang 128:\n• Tranh A: Cốc sữa tươi và 2 quả trứng gà.\n• Tranh B: Bác sĩ nam mặc áo blouse trắng đeo ống nghe.\n• Tranh C: Gia đình 4 người (bố, mẹ và hai con).\n• Tranh D: Cô gái đang chọn mua rau trong siêu thị.\n• Tranh E (Ví dụ): Cô gái đang đọc sách — 例如：我很喜欢这本书。(Wǒ hěn xǐhuan zhè běn shū.)\n• Tranh F: Hai bạn gái cùng cầm micro hát.","examples":[{"zh":"21. 王先生是医生。 → [B]","py":"Wáng xiānsheng shì yīshēng.","vi":"Ông Vương là bác sĩ. (Đáp án: B)"},{"zh":"22. 姐姐上午去超市买了菜。 → [D]","py":"Jiějie shàngwǔ qù chāoshì mǎile cài.","vi":"Chị gái buổi sáng đi siêu thị mua rau rồi. (Đáp án: D)"},{"zh":"23. 今天的早饭是牛奶和鸡蛋。 → [A]","py":"Jīntiān de zǎofàn shì niúnǎi hé jīdàn.","vi":"Bữa sáng hôm nay là sữa tươi và trứng gà. (Đáp án: A)"},{"zh":"24. 我家有四口人，爸爸、妈妈、弟弟和我。 → [C]","py":"Wǒ jiā yǒu sì kǒu rén, bàba, māma, dìdi hé wǒ.","vi":"Nhà tôi có bốn người: bố, mẹ, em trai và tôi. (Đáp án: C)"},{"zh":"25. 她和好朋友都爱唱歌。 → [F]","py":"Tā hé hǎo péngyou dōu ài chàng gē.","vi":"Cô ấy và bạn thân đều thích hát. (Đáp án: F)"}],"note":"Đáp án chính thức SBT trang 28: 21. B | 22. D | 23. A | 24. C | 25. F."}},"grammarQuiz":[{"id":"hsk1_mock_26","qtype":"fill","prompt":"Đọc hiểu Phần 2 (Chọn câu đối đáp đúng A–F):","q":"Câu 26: 这是我的书，你的呢？ (Zhè shì wǒ de shū, nǐ de ne?)","opts":[{"t":"商店。 (Shāngdiàn.)","ok":false},{"t":"我学生。 (Wǒ xuéshēng.)","ok":false},{"t":"在桌子上。 (Zài zhuōzi shang.)","ok":true},{"t":"还没有。 (Hái méiyǒu.)","ok":false},{"t":"下雪了。 (Xià xuě le.)","ok":false},{"t":"好的，谢谢！ (Hǎo de, xièxie!)","ok":false}],"exp":"Đáp án chính thức SBT trang 28: C. «这是我的书，你的呢？» (Đây là sách của tôi, còn của bạn đâu?) → «在桌子上。» (Ở trên bàn.)"},{"id":"hsk1_mock_27","qtype":"fill","prompt":"Đọc hiểu Phần 2 (Chọn câu đối đáp đúng A–F):","q":"Câu 27: 你去哪儿买苹果？ (Nǐ qù nǎr mǎi píngguǒ?)","opts":[{"t":"商店。 (Shāngdiàn.)","ok":true},{"t":"我学生。 (Wǒ xuéshēng.)","ok":false},{"t":"在桌子上。 (Zài zhuōzi shang.)","ok":false},{"t":"还没有。 (Hái méiyǒu.)","ok":false},{"t":"下雪了。 (Xià xuě le.)","ok":false},{"t":"好的，谢谢！ (Hǎo de, xièxie!)","ok":false}],"exp":"Đáp án chính thức SBT trang 28: A. «你去哪儿买苹果？» (Bạn đi đâu mua táo?) → «商店。» (Cửa hàng.)"},{"id":"hsk1_mock_28","qtype":"fill","prompt":"Đọc hiểu Phần 2 (Chọn câu đối đáp đúng A–F):","q":"Câu 28: 昨天天气怎么样？ (Zuótiān tiānqì zěnmeyàng?)","opts":[{"t":"商店。 (Shāngdiàn.)","ok":false},{"t":"我学生。 (Wǒ xuéshēng.)","ok":false},{"t":"在桌子上。 (Zài zhuōzi shang.)","ok":false},{"t":"还没有。 (Hái méiyǒu.)","ok":false},{"t":"下雪了。 (Xià xuě le.)","ok":true},{"t":"好的，谢谢！ (Hǎo de, xièxie!)","ok":false}],"exp":"Đáp án chính thức SBT trang 28: E. «昨天天气怎么样？» (Thời tiết hôm qua thế nào?) → «下雪了。» (Tuyết rơi rồi.)"},{"id":"hsk1_mock_29","qtype":"fill","prompt":"Đọc hiểu Phần 2 (Chọn câu đối đáp đúng A–F):","q":"Câu 29: 你和谁打电话呢？ (Nǐ hé shéi dǎ diànhuà ne?)","opts":[{"t":"商店。 (Shāngdiàn.)","ok":false},{"t":"我学生。 (Wǒ xuéshēng.)","ok":true},{"t":"在桌子上。 (Zài zhuōzi shang.)","ok":false},{"t":"还没有。 (Hái méiyǒu.)","ok":false},{"t":"下雪了。 (Xià xuě le.)","ok":false},{"t":"好的，谢谢！ (Hǎo de, xièxie!)","ok":false}],"exp":"Đáp án chính thức SBT trang 28: B. «你和谁打电话呢？» (Bạn đang gọi điện thoại với ai thế?) → «我学生。» (Học sinh của tôi.)"},{"id":"hsk1_mock_30","qtype":"fill","prompt":"Đọc hiểu Phần 2 (Chọn câu đối đáp đúng A–F):","q":"Câu 30: 你下班了吗？ (Nǐ xiàbān le ma?)","opts":[{"t":"商店。 (Shāngdiàn.)","ok":false},{"t":"我学生。 (Wǒ xuéshēng.)","ok":false},{"t":"在桌子上。 (Zài zhuōzi shang.)","ok":false},{"t":"还没有。 (Hái méiyǒu.)","ok":true},{"t":"下雪了。 (Xià xuě le.)","ok":false},{"t":"好的，谢谢！ (Hǎo de, xièxie!)","ok":false}],"exp":"Đáp án chính thức SBT trang 28: D. «你下班了吗？» (Bạn tan làm rồi à?) → «还没有。» (Vẫn chưa.)"},{"id":"hsk1_mock_31","qtype":"fill","prompt":"Đọc hiểu Phần 3 (Chọn từ thích hợp A–F điền vào chỗ trống):","q":"Câu 31: 大家都没吃（　）呢。 (Dàjiā dōu méi chī ( ) ne.)","opts":[{"t":"认识 (rènshi)","ok":false},{"t":"住 (zhù)","ok":false},{"t":"晚饭 (wǎnfàn)","ok":true},{"t":"叫 (jiào)","ok":false},{"t":"汉字 (Hànzì)","ok":false},{"t":"块 (kuài)","ok":false}],"exp":"Đáp án chính thức SBT trang 28: C (晚饭 wǎnfàn — bữa tối). «大家都没吃晚饭呢。» (Mọi người đều chưa ăn tối đâu.)"},{"id":"hsk1_mock_32","qtype":"fill","prompt":"Đọc hiểu Phần 3 (Chọn từ thích hợp A–F điền vào chỗ trống):","q":"Câu 32: 在今天的中文课上，我学了很多（　）。 (Zài jīntiān de Zhōngwén kè shang, wǒ xuéle hěn duō ( ).)","opts":[{"t":"认识 (rènshi)","ok":false},{"t":"住 (zhù)","ok":false},{"t":"晚饭 (wǎnfàn)","ok":false},{"t":"叫 (jiào)","ok":false},{"t":"汉字 (Hànzì)","ok":true},{"t":"块 (kuài)","ok":false}],"exp":"Đáp án chính thức SBT trang 28: E (汉字 Hànzì — chữ Hán). «在今天的中文课上，我学了很多汉字。» (Trong giờ tiếng Trung hôm nay, tôi đã học rất nhiều chữ Hán.)"},{"id":"hsk1_mock_33","qtype":"fill","prompt":"Đọc hiểu Phần 3 (Chọn từ thích hợp A–F điền vào chỗ trống):","q":"Câu 33: 对不起，我不（　）这个人。 (Duìbuqǐ, wǒ bú ( ) zhège rén.)","opts":[{"t":"认识 (rènshi)","ok":true},{"t":"住 (zhù)","ok":false},{"t":"晚饭 (wǎnfàn)","ok":false},{"t":"叫 (jiào)","ok":false},{"t":"汉字 (Hànzì)","ok":false},{"t":"块 (kuài)","ok":false}],"exp":"Đáp án chính thức SBT trang 28: A (认识 rènshi — quen biết). «对不起，我不认识这个人。» (Xin lỗi, tôi không quen người này.)"},{"id":"hsk1_mock_34","qtype":"fill","prompt":"Đọc hiểu Phần 3 (Chọn từ thích hợp A–F điền vào chỗ trống):","q":"Câu 34: 我和家人（　）在北京。 (Wǒ hé jiārén ( ) zài Běijīng.)","opts":[{"t":"认识 (rènshi)","ok":false},{"t":"住 (zhù)","ok":true},{"t":"晚饭 (wǎnfàn)","ok":false},{"t":"叫 (jiào)","ok":false},{"t":"汉字 (Hànzì)","ok":false},{"t":"块 (kuài)","ok":false}],"exp":"Đáp án chính thức SBT trang 28: B (住 zhù — sống/ở). «我和家人住在北京。» (Tôi và gia đình sống ở Bắc Kinh.)"},{"id":"hsk1_mock_35","qtype":"fill","prompt":"Đọc hiểu Phần 3 (Chọn từ thích hợp A–F điền vào chỗ trống):","q":"Câu 35: 男：这些东西可以卖多少钱？ (Zhèxiē dōngxi kěyǐ mài duōshao qián?) / 女：80（　）。","opts":[{"t":"认识 (rènshi)","ok":false},{"t":"住 (zhù)","ok":false},{"t":"晚饭 (wǎnfàn)","ok":false},{"t":"叫 (jiào)","ok":false},{"t":"汉字 (Hànzì)","ok":false},{"t":"块 (kuài)","ok":true}],"exp":"Đáp án chính thức SBT trang 28: F (块 kuài — đồng/tệ). «这些东西可以卖多少钱？— 80块。» (Những đồ này có thể bán bao nhiêu tiền? — 80 tệ.)"},{"id":"hsk1_mock_36","qtype":"correct","prompt":"Đọc hiểu Phần 4 (Đọc câu và chọn đáp án đúng A–C):","q":"Câu 36: 下雨了，我们坐出租车回家吧。 (Xià yǔ le, wǒmen zuò chūzūchē huí jiā ba.) ★ 说话人想怎么回家？ (Shuōhuàrén xiǎng zěnme huí jiā?)","opts":[{"t":"开车 (kāichē)","ok":false},{"t":"坐飞机 (zuò fēijī)","ok":false},{"t":"坐出租车 (zuò chūzūchē)","ok":true}],"exp":"Đáp án chính thức SBT trang 28: C (坐出租车 — đi taxi). Câu gốc: «Trời mưa rồi, chúng ta bắt taxi về nhà đi.»"},{"id":"hsk1_mock_37","qtype":"correct","prompt":"Đọc hiểu Phần 4 (Đọc câu và chọn đáp án đúng A–C):","q":"Câu 37: 我儿子今年16岁了，正在上中学。 (Wǒ érzi jīnnián 16 suì le, zhèngzài shàng zhōngxué.) ★ 说话人的儿子是： (Shuōhuàrén de érzi shì:)","opts":[{"t":"小学生 (xiǎoxuéshēng)","ok":false},{"t":"中学生 (zhōngxuéshēng)","ok":true},{"t":"大学生 (dàxuéshēng)","ok":false}],"exp":"Đáp án chính thức SBT trang 28: B (中学生 — học sinh trung học). Câu gốc: «Con trai tôi năm nay 16 tuổi rồi, đang học trung học.»"},{"id":"hsk1_mock_38","qtype":"correct","prompt":"Đọc hiểu Phần 4 (Đọc câu và chọn đáp án đúng A–C):","q":"Câu 38: 小猫和小狗都在房间外睡觉呢。 (Xiǎo māo hé xiǎo gǒu dōu zài fángjiān wài shuìjiào ne.) ★ 小狗在： (Xiǎo gǒu zài:)","opts":[{"t":"桌子下 (zhuōzi xià)","ok":false},{"t":"房间里 (fángjiān li)","ok":false},{"t":"房间外 (fángjiān wài)","ok":true}],"exp":"Đáp án chính thức SBT trang 28: C (房间外 — bên ngoài phòng). Câu gốc: «Mèo con và chó con đều đang ngủ ở ngoài phòng.»"},{"id":"hsk1_mock_39","qtype":"correct","prompt":"Đọc hiểu Phần 4 (Đọc câu và chọn đáp án đúng A–C):","q":"Câu 39: 我同学在这个学校工作很多年了，你有问题可以问他。 (Wǒ tóngxué zài zhège xuéxiào gōngzuò hěn duō nián le, nǐ yǒu wèntí kěyǐ wèn tā.) ★ 说话人的同学在哪儿上班？ (Shuōhuàrén de tóngxué zài nǎr shàngbān?)","opts":[{"t":"饭店 (fàndiàn)","ok":false},{"t":"医院 (yīyuàn)","ok":false},{"t":"学校 (xuéxiào)","ok":true}],"exp":"Đáp án chính thức SBT trang 28: C (学校 — trường học). Câu gốc: «Bạn học của tôi làm việc ở ngôi trường này nhiều năm rồi, bạn có thắc mắc có thể hỏi anh ấy.»"},{"id":"hsk1_mock_40","qtype":"correct","prompt":"Đọc hiểu Phần 4 (Đọc câu và chọn đáp án đúng A–C):","q":"Câu 40: 这个小朋友写字真好看。 (Zhège xiǎopéngyǒu xiě zì zhēn hǎokàn.) ★ 那个小朋友： (Nàge xiǎopéngyǒu:)","opts":[{"t":"名字好听 (míngzi hǎotīng)","ok":false},{"t":"写字好看 (xiě zì hǎokàn)","ok":true},{"t":"正在读书 (zhèngzài dúshū)","ok":false}],"exp":"Đáp án chính thức SBT trang 28: B (写字好看 — viết chữ đẹp). Câu gốc: «Bạn nhỏ này viết chữ đẹp thật.»"}],"chars":[],"rhyme":null,"notes":["Phần Nghe (Câu 1–20, SBT tr. 122–126) đi kèm file âm thanh: 模拟测试——HSK(一级）模拟试卷 听力.mp3. Các câu dùng tranh minh họa là Câu 1–5 (tr. 122–123) và Câu 11–15 (tr. 125); toàn bộ phương án chữ Hán + Pinyin của Câu 6–10 (tr. 124) và Câu 16–20 (tr. 126) đã được ghi đầy đủ trong mục Nghe hiểu.","Bảng đáp án Nghe hiểu (Câu 1–20, SBT tr. 28): Phần 1: 1.C · 2.A · 3.C · 4.B · 5.C | Phần 2: 6.B · 7.C · 8.B · 9.C · 10.A | Phần 3: 11.B · 12.D · 13.E · 14.A · 15.F | Phần 4: 16.A · 17.C · 18.A · 19.B · 20.B.","Bảng đáp án Đọc hiểu (Câu 21–40, SBT tr. 28): Phần 1: 21.B · 22.D · 23.A · 24.C · 25.F | Phần 2: 26.C · 27.A · 28.E · 29.B · 30.D | Phần 3: 31.C · 32.E · 33.A · 34.B · 35.F | Phần 4: 36.C · 37.B · 38.C · 39.C · 40.B."],"workbook":{"exercisesNote":"HSK（一级）模拟试卷 gồm Phần I Nghe (Câu 1–20, file MP3: 模拟测试——HSK(一级）模拟试卷 听力.mp3, SBT tr. 122–126) và Phần II Đọc hiểu (Câu 21–40, SBT tr. 128–131; đã số hóa câu 26–40 vào bài trắc nghiệm tương tác; câu 21–25 dùng tranh minh họa trang 128 và được liệt kê chi tiết trong phần Ngữ pháp/Hướng dẫn).","answerKeyNote":"I. NGHE (1–20):\n• Phần 1: 1. C | 2. A | 3. C | 4. B | 5. C\n• Phần 2: 6. B | 7. C | 8. B | 9. C | 10. A\n• Phần 3: 11. B | 12. D | 13. E | 14. A | 15. F\n• Phần 4: 16. A | 17. C | 18. A | 19. B | 20. B\n\nII. ĐỌC HIỂU (21–40):\n• Phần 1: 21. B | 22. D | 23. A | 24. C | 25. F\n• Phần 2: 26. C | 27. A | 28. E | 29. B | 30. D\n• Phần 3: 31. C | 32. E | 33. A | 34. B | 35. F\n• Phần 4: 36. C | 37. B | 38. C | 39. C | 40. B","transcriptNote":""}}};
